// ★ 2.2.0 KEYWORD GATE — ส่งโมดูลเฉพาะตอนที่เกี่ยวข้อง
// เดิมส่งทุกโมดูลทุกเทิร์นแม้ไม่มีใครพูดถึงเรื่องนั้น
// ══════════════════════════════════════════════════════════
const PP_KW_DEFAULT = {
 msg: 'ข้อความ,แชท,ทัก,ส่ง,พิมพ์,ตอบ,เสียง,สติกเกอร์,ตำแหน่ง,ที่ไหน,ของขวัญ,line,text,message',
 groupcall: 'โทร,สาย,รับสาย,วางสาย,คุยสาย,กลุ่ม,แชทกลุ่ม,call,ring',
 feed: 'โพสต์,ฟีด,ลง,คอมเมนต์,เม้น,ไลก์,กดใจ,รีโพสต์,แชร์,โพล,ig,feed,post',
 story: 'สตอรี่,สตอรี,story,ลงสตอรี่,ดูสตอรี่',
 wallet: 'เงิน,โอน,จ่าย,ยืม,ขอเงิน,ค่า,บาท,วอน,ราคา,ซื้อ,money,pay',
 social: 'ติดตาม,ฟอล,เลิกติดตาม,สเตตัส,โปรไฟล์,follow,status',
 news: 'ข่าว,ประกาศ,เหตุการณ์,หนังสือพิมพ์,news',
 inv_contacts: '',
 inv_stickers: 'สติกเกอร์,sticker',
 inv_posts: 'โพสต์,ฟีด,คอมเมนต์,รีโพสต์,แชร์,post,feed',
 inv_ui: 'ธีม,สี,วอลเปเปอร์,หน้าตา,มือถือ,ฟอง,theme',
 actionlog: '',
};
function ppKwOn(key) {
 const cfg = getCfg();
 if (cfg.kwEnabled !== true) return false;
 const m = cfg.kwPerMod || {};
 return m[key] === true;
}
function ppKwWords(key) {
 const cfg = getCfg();
 const raw = (cfg.kwWords && cfg.kwWords[key] !== undefined) ? cfg.kwWords[key] : PP_KW_DEFAULT[key];
 return String(raw || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
}
/** ข้อความที่ใช้ตรวจคีย์เวิร์ด — ข้อความผู้ใช้ล่าสุด + บทตอบก่อนหน้า */
function ppKwHaystack(chat) {
 try {
  const arr = Array.isArray(chat) ? chat : [];
  const tail = arr.slice(-3);
  return tail.map(m => String((m && (m.mes || m.content)) || '')).join(' ').toLowerCase();
 } catch { return ''; }
}
/** โมดูลนี้ผ่านด่านคีย์เวิร์ดไหม — ไม่เปิดคีย์เวิร์ด = ผ่านตลอด */
function ppKwPass(key, hay) {
 if (!ppKwOn(key)) return true;
 const words = ppKwWords(key);
 if (!words.length) return true;
 return words.some(w => hay.includes(w));
}
// ── ตัวแก้คำ prompt ──
function ppPromptText(key, fallback) {
 const cfg = getCfg();
 const edit = cfg.promptEdits && cfg.promptEdits[key];
 if (typeof edit === 'string' && edit.trim()) return edit;
 return fallback;
}
function ppPromptIsEdited(key) {
 const cfg = getCfg();
 const e = cfg.promptEdits && cfg.promptEdits[key];
 return typeof e === 'string' && e.trim().length > 0;
}
function ppResetPrompt(key) {
 const cfg = getCfg();
 if (cfg.promptEdits) delete cfg.promptEdits[key];
 saveCfg();
}
/** ชนิดเหตุการณ์ที่แต่ละโมดูลต้องมีชื่ออยู่ใน prompt — ใช้เตือนตอนผู้ใช้แก้คำ */
const PP_MOD_TYPES = {
 msg: ['dm', 'voice', 'sticker', 'location', 'gift', 'poll', 'unsend', 'story_reply', 'contact', 'nickname'],
 groupcall: ['group', 'call', 'missed_call', 'call_log', 'group_create'],
 feed: ['post', 'comment', 'like', 'poll_vote', 'repost', 'share_post'],
 story: ['story', 'story_like'],
 wallet: ['wallet', 'wallet_request', 'wallet_set'],
 social: ['follow', 'unfollow', 'note', 'lock_account', 'approve_follow'],
 news: ['news'],
};
function ppPromptMissingTypes(key, text) {
 const need = PP_MOD_TYPES[key];
 if (!need) return [];
 const t = String(text || '');
 return need.filter(n => !t.includes(n));
}
// ══════════════════════════════════════════════════════════
// ★ 2.3.0 SYNC ECHO — ตัวละครรู้ว่าเทิร์นก่อนตัวเองส่งอะไรเข้ามือถือ
// คนละเรื่องกับกระจกฝั่งบอท
//   กระจกฝั่งบอท = สิ่งที่ตัวละครทำในแอปตอนผู้ใช้กดปุ่มดาว
//   ตัวนี้ = บทโรลของเขาทำให้อะไรเข้ามือถือ
// ★ 2.3.0 เก็บเนื้อความจริงด้วย ไม่ใช่แค่ชื่อชนิด และให้ผู้ใช้จิ้มเลือกได้
// ══════════════════════════════════════════════════════════
/** ★ 2.4.0 กุญแจรูทของ echo — ใช้ตัวเดียวกับที่ระบบแยกประวัติแชท
 * สลับแชทใน SillyTavern แล้วแต่ละรูทจำเรื่องของตัวเอง ไม่ต้องลบอะไร */
function ppEchoRouteKey() {
 const cid = currentCharacterId();
 if (!cid) return 'global';
 const chat = ppStChatId();
 return chat ? `${cid}::${chat}` : String(cid);
}
function ppEchoItems(routeKey) {
 const cfg = getCfg();
 if (!cfg.echoByRoute || typeof cfg.echoByRoute !== 'object') cfg.echoByRoute = {};
 // ย้ายของเก่าจากรุ่นก่อนเข้ารูทปัจจุบันครั้งเดียว
 if (!cfg.echoMigrated) {
  cfg.echoMigrated = true;
  const old = Array.isArray(cfg.echoItems) ? cfg.echoItems : [];
  if (old.length) {
   const k0 = ppEchoRouteKey();
   if (!Array.isArray(cfg.echoByRoute[k0])) cfg.echoByRoute[k0] = [];
   Array.prototype.push.apply(cfg.echoByRoute[k0], old);
   console.log(`[pocket-phone] ย้าย echo เก่า ${old.length} รายการเข้ารูท ${k0}`);
  }
  cfg.echoItems = [];
  saveCfg();
 }
 const k = routeKey || ppEchoRouteKey();
 if (!Array.isArray(cfg.echoByRoute[k])) cfg.echoByRoute[k] = [];
 return cfg.echoByRoute[k];
}
/** จำนวนรูทที่มี echo เก็บไว้ */
function ppEchoRouteCount() {
 const cfg = getCfg();
 const m = cfg.echoByRoute || {};
 return Object.keys(m).filter(k => Array.isArray(m[k]) && m[k].length).length;
}
/** ล้างรายการที่หมดอายุตามที่ผู้ใช้ตั้ง — ★ 2.4.0 ทำทุกรูท */
function ppEchoPrune() {
 const cfg = getCfg();
 const hrs = Math.max(0, parseFloat(cfg.echoTtlHours) || 0);
 if (!hrs) return;
 ppEchoItems(); // กระตุ้นการย้ายของเก่าก่อน
 const cut = Date.now() - hrs * 3600000;
 const m = cfg.echoByRoute || {};
 let changed = false;
 Object.keys(m).forEach(k => {
  if (!Array.isArray(m[k])) return;
  const before = m[k].length;
  m[k] = m[k].filter(x => (x.ts || 0) >= cut);
  if (m[k].length !== before) changed = true;
 });
 if (changed) saveCfg();
}
/** รายการที่ติ๊กเปิดไว้และยังไม่หมดอายุ */
function ppEchoActive() {
 ppEchoPrune();
 const cfg = getCfg();
 const max = Math.max(1, Math.min(60, cfg.echoMaxItems || 20));
 return ppEchoItems().filter(x => x.on !== false).slice(-max);
}
function ppEchoCount() { ppEchoPrune(); return ppEchoItems().length; }
function ppEchoActiveCount() { return ppEchoActive().length; }
/** ★ 2.4.0 เก็บเข้ารูทปัจจุบัน ไม่ปนกับรูทอื่น */
function ppSyncEchoRecord(rows) {
 const cfg = getCfg();
 if (cfg.echoSyncEnabled === false) return;
 if (!Array.isArray(rows) || !rows.length) return;
 const k = ppEchoRouteKey();
 const list = ppEchoItems(k);
 const cap = Math.max(20, (cfg.echoMaxItems || 20) * 3);
 rows.forEach(r => {
  list.push({
   id: newId(),
   type: String(r.type || '?'),
   label: String(r.label || '').slice(0, 120),
   detail: String(r.detail || '').slice(0, Math.max(40, cfg.echoDetailLen || 200)),
   ts: Date.now(),
   on: true,
  });
 });
 if (list.length > cap) cfg.echoByRoute[k] = list.slice(-cap);
 saveCfg();
}
function ppSyncEchoLabel(type, label) {
 const t = String(type || '').toLowerCase();
 const lb = String(label || '');
 const map = {
  dm: 'ส่งข้อความเข้ามือถือ', voice: 'ส่งคลิปเสียง', sticker: 'ส่งสติกเกอร์',
  location: 'ส่งตำแหน่ง', gift: 'ส่งของขวัญ', poll: 'สร้างโพล',
  unsend: 'ยกเลิกข้อความที่ส่งไป', story_reply: 'ตอบสตอรี่',
  contact: 'บันทึกตัวเองเข้าคอนแทกต์', nickname: 'ตั้งชื่อที่บันทึกผู้ใช้ไว้',
  group: 'ส่งข้อความในกลุ่ม', group_create: 'สร้างกลุ่มแล้วดึงผู้ใช้เข้า',
  call: 'โทรเข้ามือถือ', missed_call: 'โทรแล้วไม่มีคนรับ', call_log: 'มีสายที่คุยกันไปแล้ว',
  post: 'โพสต์ลงฟีด', comment: 'คอมเมนต์โพสต์', comment_reply: 'ตอบคอมเมนต์',
 board_post: 'ตั้งกระทู้ใหม่ในเว็บบอร์ด', board_reply: 'มีคนตอบกระทู้ในเว็บบอร์ด',
  like: 'กดถูกใจโพสต์', unlike: 'เลิกถูกใจโพสต์', save_post: 'บันทึกโพสต์ไว้',
  repost: 'รีโพสต์', share_post: 'แชร์โพสต์เข้าแชท', poll_vote: 'โหวตโพล',
  story: 'ลงสตอรี่', story_like: 'ถูกใจสตอรี่',
  wallet: 'มีเงินเปลี่ยนมือ', wallet_request: 'ขอเงิน', wallet_set: 'ยอดเงินตัวเองเปลี่ยน',
  follow: 'ติดตามผู้ใช้', follow_request: 'ขอติดตามผู้ใช้', unfollow: 'เลิกติดตามผู้ใช้',
  note: 'ตั้งสเตตัสตัวเอง', news: 'มีข่าวขึ้นในแอปข่าว',
  photo_decline: 'ไม่เอารูปที่ผู้ใช้ฝากไปโพสต์',
 };
 const head = map[t] || t;
 return lb ? `${head} — ${lb}` : head;
}
/** ★ 2.3.0 ดึงเนื้อความจริงจาก event เพื่อให้ตัวละครเห็นว่าพูดว่าอะไร */
function ppEchoDetail(ev) {
 if (!ev || typeof ev !== 'object') return '';
 const grab = v => {
  if (!v) return '';
  if (Array.isArray(v)) return v.map(x => String(x || '').trim()).filter(Boolean).join(' / ');
  return String(v).trim();
 };
 const bits = [];
 const txt = grab(ev.text || ev.messages);
 if (txt) bits.push(`"${txt}"`);
 if (ev.label) bits.push(`สติกเกอร์ ${grab(ev.label)}`);
 if (ev.place) bits.push(`ที่ ${grab(ev.place)}`);
 if (ev.gift) bits.push(`ของขวัญ ${grab(ev.gift)}`);
 if (ev.amount) bits.push(`${fmtMoney(Math.abs(parseInt(ev.amount, 10) || 0))}`);
 if (ev.reason || ev.note) bits.push(`เหตุผล ${grab(ev.reason || ev.note)}`);
 if (ev.group) bits.push(`กลุ่ม ${grab(ev.group)}`);
 if (ev.question) bits.push(`โพล ${grab(ev.question)}`);
 if (ev.minutes) bits.push(`คุยกัน ${parseInt(ev.minutes, 10) || 0} นาที`);
 if (ev.transcript) { const tr = grab(ev.transcript); if (tr) bits.push(`ในสาย ${tr}`); }
 if (ev.quote) bits.push(`เขียนทับว่า "${grab(ev.quote)}"`);
 if (ev.source) bits.push(`แหล่ง ${grab(ev.source)}`);
 if (ev.count) bits.push(`${parseInt(ev.count, 10) || 0} ครั้ง`);
 return bits.join(' · ');
}
// ══════════════════════════════════════════════════════════
// ★ 2.8.5 ECHO DELETE — ตัวลบที่เขียนกลับเข้ารูทที่ถูก
// ต้นเหตุเดิม ตัวลบเขียนค่าใหม่ลง cfg.echoItems ซึ่งเป็นที่เก็บของรุ่นก่อน 2.4.0
// แต่ตัวอ่านไปอ่านจาก cfg.echoByRoute ที่แยกตามรูทแชท
// ลบถูกที่แต่ลบผิดกล่อง ของจริงจึงไม่ขยับ แล้วหน้าจอวาดใหม่จากกล่องเดิม
// ══════════════════════════════════════════════════════════
/** ลบรายการตาม id — คืนจำนวนที่ลบได้จริง
 * ค้นทุกรูท ไม่ใช่แค่รูทปัจจุบัน เพราะรายการอาจค้างมาจากรูทอื่น */
function ppEchoDelete(ids) {
 const cfg = getCfg();
 ppEchoItems(); // กระตุ้นการย้ายของเก่าให้เสร็จก่อน
 const kill = new Set(Array.isArray(ids) ? ids : [ids]);
 if (!kill.size) return 0;
 let removed = 0;
 const map = cfg.echoByRoute || {};
 Object.keys(map).forEach(k => {
  if (!Array.isArray(map[k])) return;
  const before = map[k].length;
  map[k] = map[k].filter(x => !kill.has(x.id));
  removed += before - map[k].length;
 });
 // เก็บกวาดช่องเก่าด้วย เผื่อมีของค้างจากรุ่นก่อน 2.4.0
 if (Array.isArray(cfg.echoItems) && cfg.echoItems.length) {
  const before2 = cfg.echoItems.length;
  cfg.echoItems = cfg.echoItems.filter(x => !kill.has(x.id));
  removed += before2 - cfg.echoItems.length;
 }
 kill.forEach(id => ppEchoSelected.delete(id));
 if (removed) saveCfg();
 console.info('[pocket-phone] ลบผลซิงค์', { ขอลบ: kill.size, ลบได้: removed });
 return removed;
}
/** ล้างรายการทั้งหมดของรูทหนึ่ง — คืนจำนวนที่ลบ */
function ppEchoClearRoute(routeKey) {
 const cfg = getCfg();
 ppEchoItems();
 const k = routeKey || ppEchoRouteKey();
 const arr = (cfg.echoByRoute || {})[k];
 const n = Array.isArray(arr) ? arr.length : 0;
 if (n) {
  arr.forEach(x => ppEchoSelected.delete(x.id));
  cfg.echoByRoute[k] = [];
  saveCfg();
 }
 console.info('[pocket-phone] ล้างผลซิงค์ของรูท', k, n);
 return n;
}
/** ล้างทุกรูททั้งระบบ — ใช้เมื่อมีของค้างข้ามรูท */
function ppEchoClearAllRoutes() {
 const cfg = getCfg();
 ppEchoItems();
 let n = 0;
 const map = cfg.echoByRoute || {};
 Object.keys(map).forEach(k => {
  if (!Array.isArray(map[k])) return;
  n += map[k].length;
  map[k] = [];
 });
 if (Array.isArray(cfg.echoItems)) { n += cfg.echoItems.length; cfg.echoItems = []; }
 ppEchoSelected.clear();
 if (n) saveCfg();
 console.info('[pocket-phone] ล้างผลซิงค์ทุกรูท', n);
 return n;
}
/** นับรายการทุกรูทรวมกัน — ใช้บอกผู้ใช้ว่ามีของค้างที่รูทอื่นไหม */
function ppEchoCountAllRoutes() {
 const cfg = getCfg();
 ppEchoItems();
 let n = 0;
 const map = cfg.echoByRoute || {};
 Object.keys(map).forEach(k => { if (Array.isArray(map[k])) n += map[k].length; });
 if (Array.isArray(cfg.echoItems)) n += cfg.echoItems.length;
 return n;
}
window.PP_ECHO_DIAG = () => {
 const cfg = getCfg();
 ppEchoItems();
 const map = cfg.echoByRoute || {};
 const rows = {
  รูทที่ใช้อยู่: ppEchoRouteKey(),
  ในรูทนี้: ppEchoCount(),
  เปิดไว้: ppEchoActiveCount(),
  ทุกรูทรวม: ppEchoCountAllRoutes(),
  จำนวนรูท: Object.keys(map).filter(k => (map[k] || []).length).length,
  ช่องเก่าค้าง: Array.isArray(cfg.echoItems) ? cfg.echoItems.length : 0,
  เลือกไว้: ppEchoSelected.size,
 };
 console.table(rows);
 return rows;
};
/** ข้อความ system ที่ส่งกลับเข้าโรลเทิร์นถัดไป */
/** ★ 2.4.1 บรรทัดเวลาจริง — สร้างสดทุกครั้งที่เรียก ไม่เคยถูกแคช
 * สาเหตุที่เวลาไม่ตรงในรุ่น 2.4.0:
 *   ผมเสียบบรรทัดนี้ไว้ใน core ของ ppBuildBridgeParts ซึ่งผลลัพธ์ถูกเก็บใน
 *   bridgeTokenCache แล้วใช้ซ้ำทุกเทิร์น เวลาที่โมเดลเห็นจึงเป็นเวลาตอนกดวัดโทเคน
 *   ครั้งล่าสุด ไม่ใช่เวลาตอนเจน
 * รุ่นนี้ย้ายออกไปเป็น system message แยก สร้างใหม่ทุกครั้งที่ interceptor ทำงาน
 * อ่านนาฬิกาตัวเดียวกับที่โชว์มุมซ้ายบนของมือถือ คือ new Date() สด ๆ */
function ppRealTimeStamp() {
 const d = new Date();
 const dow = ['อาทิตย์', 'จันทร์', 'อังคาร', 'พุธ', 'พฤหัสบดี', 'ศุกร์', 'เสาร์'][d.getDay()];
 const h = d.getHours();
 const part = h < 5 ? 'ดึกมาก' : h < 8 ? 'เช้าตรู่' : h < 11 ? 'ตอนเช้า'
  : h < 13 ? 'เที่ยง' : h < 16 ? 'บ่าย' : h < 19 ? 'เย็น' : h < 22 ? 'หัวค่ำ' : 'ดึก';
 return {
  hhmm: `${h}:${String(d.getMinutes()).padStart(2, '0')}`,
  dow, part,
  day: d.getDate(),
  month: TH_MONTHS_FULL[d.getMonth()],
  year: d.getFullYear() + 543,
 };
}
/** ข้อความเวลาที่ส่งให้โมเดล — คืน '' ถ้าปิดสวิตช์ */
function ppRealTimeLine(ctxLabel) {
 if (getCfg().realTimeMode !== true) return '';
 const t = ppRealTimeStamp();
 return `REAL TIME RIGHT NOW — วัน${t.dow} ที่ ${t.day} ${t.month} ${t.year} เวลา ${t.hhmm} (${t.part}). `
  + `${ctxLabel || ''}This is the actual clock on the user's device at this exact moment. `
  + `If you mention the time, the day, or the part of day at all, it must match this exactly. Never invent a different hour or day.`;
}
/** ข้อความเวลาสำหรับ system message ในบทหลัก */
function ppRealTimeSystemMsg() {
 if (getCfg().realTimeMode !== true) return '';
 const t = ppRealTimeStamp();
 return `[REAL-WORLD CLOCK — วัน${t.dow} ที่ ${t.day} ${t.month} ${t.year} เวลา ${t.hhmm} น. (${t.part})]\n`
  + `This is the user's actual device clock at this exact moment, refreshed every turn. `
  + `Any time reference in your reply — clock time, day of week, date, or part of day — must match this. `
  + `Never carry over a time from an earlier turn. Never invent an hour.`;
}
/** ข้อความที่จะแสดงให้ผู้ใช้ตรวจในหน้าตั้งค่า */
function ppRealTimePreview() {
 const t = ppRealTimeStamp();
 return `วัน${t.dow} ที่ ${t.day} ${t.month} ${t.year} เวลา ${t.hhmm} น. (${t.part})`;
}
function ppBuildSyncEcho() {
 const cfg = getCfg();
 if (cfg.echoSyncEnabled === false) return '';
 const rows = ppEchoActive();
 if (!rows.length) return '';
 const un = getUserDisplayName();
 const lines = rows.map(r => {
  const head = ppSyncEchoLabel(r.type, r.label);
  return r.detail ? `- ${head}\n    ${r.detail}` : `- ${head}`;
 });
 return [
  `[WHAT YOU ALREADY PUT ON ${un.toUpperCase()}'S PHONE — already done, already visible to them.]`,
  lines.join('\n'),
  `You caused all of that in your earlier replies and every one of it went through. ${un} can see it on their phone right now, word for word as written above.`,
  `Never say you have not done it yet. Never repeat it as if new. Never act surprised that it exists. Never contradict what you already wrote there. Build forward from it.`,
 ].join('\n');
}
function ppSyncEchoLineCount() { return ppEchoActiveCount(); }
/** ★ 2.3.0 วัดโทเคนของ echo ที่ค้างอยู่ */
async function ppEchoTokens() {
 const txt = ppBuildSyncEcho();
 if (!txt) return 0;
 try { return await ppCountTokens(txt); } catch { return 0; }
}
// ══════════════════════════════════════════════════════════
// ★ 2.5.0 MULTI-ACCOUNT — หลายบัญชีแบบ IG กับ X
// โครงเดิมเก็บเจ้าของโพสต์เป็น 'user' ค่าเดียว
// รุ่นนี้แทรกชั้นบัญชีเข้าไป ทุกที่ที่เคยเป็น 'user' กลายเป็นบัญชีที่ใช้อยู่
// ตัวละครและ NPC ก็มีหลายบัญชีได้ ใช้โครงเดียวกัน
// ══════════════════════════════════════════════════════════
function ppAccounts() {
 const cfg = getCfg();
 if (!Array.isArray(cfg.accounts)) cfg.accounts = [];
 // ย้ายข้อมูลเดิมเข้าบัญชีหลักครั้งเดียว ไม่มีอะไรหาย
 if (!cfg.accountsMigrated) {
  cfg.accountsMigrated = true;
  if (!cfg.accounts.some(a => a.id === 'main')) {
   cfg.accounts.unshift({
    id: 'main', owner: 'user',
    name: cfg.userAppName || '', handle: cfg.userHandle || '',
    avatar: '', cover: cfg.userCover || '',
    bio: cfg.userBio || '', link: cfg.userLink || '',
    followerCount: 0, followingCount: 0,
    locked: !!cfg.accountLocked, knownBy: null, theme: '',
    primary: true, ts: Date.now(),
   });
  }
  saveCfg();
  console.log('[pocket-phone] สร้างบัญชีหลักจากข้อมูลเดิมแล้ว');
 }
 return cfg.accounts;
}
/** บัญชีของเจ้าของรายนี้ — owner 'user' คือของคุณ ที่เหลือคือ id คอนแทกต์ */
function ppAccountsOf(owner) {
 const o = owner || 'user';
 return ppAccounts().filter(a => (a.owner || 'user') === o);
}
function ppFindAccount(id) {
 if (!id) return ppAccounts().find(a => a.id === 'main') || null;
 return ppAccounts().find(a => a.id === id) || null;
}
/** บัญชีที่ใช้อยู่ตอนนี้ */
function ppActiveAccount() {
 const cfg = getCfg();
 const id = cfg.activeAccount || 'main';
 return ppFindAccount(id) || ppFindAccount('main');
}
function ppActiveAccountId() {
 const a = ppActiveAccount();
 return a ? a.id : 'main';
}
/** ค่าที่ใช้แทน 'user' ในฟีลด์ author — บัญชีหลักยังเป็น 'user' เพื่อไม่ให้ข้อมูลเก่าพัง */
function ppAuthorKey(accId) {
 const id = accId || ppActiveAccountId();
 return id === 'main' ? 'user' : 'acc:' + id;
}
function ppIsMyAuthor(author) {
 const a = String(author || '');
 if (a === 'user') return true;
 if (!a.startsWith('acc:')) return false;
 const acc = ppFindAccount(a.slice(4));
 return !!(acc && (acc.owner || 'user') === 'user');
}
/** ชื่อที่แสดงของบัญชี */
function ppAccName(accId) {
 const a = ppFindAccount(accId);
 if (!a) return getUserDisplayName();
 if (a.id === 'main') return (a.name && a.name.trim()) || getUserDisplayName();
 return (a.name && a.name.trim()) || 'บัญชีที่ ' + a.id.slice(0, 4);
}
function ppAccHandle(accId) {
 const a = ppFindAccount(accId);
 if (!a) return getUserHandle();
 if (a.handle && a.handle.trim()) return a.handle.trim().replace(/^@/, '');
 if (a.id === 'main') return getUserHandle();
 return ppAccName(accId).replace(/\s+/g, '').toLowerCase();
}
function ppAccAvatar(accId) {
 const a = ppFindAccount(accId);
 if (!a) return ppUserAvatarCache;
 if (a.avatar) return a.avatar;
 if (a.id === 'main') return ppUserAvatarCache;
 return '';
}
/** แปลง author key ให้เป็นชื่อที่อ่านได้ — ใช้แทนตัวเดิมทุกที่ */
function ppAuthorLabel(author) {
 const a = String(author || '');
 if (a === 'user') return ppAccName('main');
 if (a.startsWith('acc:')) return ppAccName(a.slice(4));
 return '';
}
function ppAuthorAvatar(author) {
 const a = String(author || '');
 if (a === 'user') return ppAccAvatar('main');
 if (a.startsWith('acc:')) return ppAccAvatar(a.slice(4));
 return '';
}
// ══════════════════════════════════════════════════════════
// ★ 2.8.3 ตัวช่วยกลางของระบบบัญชี
// ปัญหาเดิม โค้ดหลายจุดตรวจแค่ค่า 'user' ตรงตัว พอเจ้าของกลายเป็น acc:xxx
// มันตกจากทุกเงื่อนไขแล้วเงียบไปเลย ทั้งรูป ทั้งฟีด ทั้งคนคอมเมนต์
// ต่อจากนี้ทุกจุดต้องเรียกผ่านตัวช่วยเหล่านี้ ห้ามเทียบสตริงตรง ๆ อีก
// ══════════════════════════════════════════════════════════
/** รูปของเจ้าของรายนี้ — รับได้ทุกรูปแบบ user · acc:xxx · id คอนแทกต์ · ghost: */
function ppAvatarOf(id) {
 const s = String(id || '');
 if (!s) return '';
 if (s === 'user') return ppAccAvatar('main');
 if (s.startsWith('acc:')) {
  const a = ppFindAccount(s.slice(4));
  if (!a) return '';
  if (a.avatar) return a.avatar;
  if (a.id === 'main') return ppUserAvatarCache;
  return '';
 }
 if (s.startsWith('ghost:')) return '';
 if (s === 'news') return '';
 const c = findContact(s);
 return c ? (c.avatar || '') : '';
}
/** ชื่อที่แสดงของเจ้าของรายนี้ */
function ppNameOf(id) {
 const s = String(id || '');
 if (!s) return '?';
 if (s === 'user') return ppAccName('main');
 if (s.startsWith('acc:')) return ppAccName(s.slice(4));
 if (s.startsWith('ghost:')) return s.slice(6) || 'ใครไม่รู้';
 const c = findContact(s);
 return c ? dname(c) : s;
}
/** โพสต์นี้เป็นของบัญชีไหนของผู้ใช้ — คืน main หรือ id บัญชี ถ้าไม่ใช่ของผู้ใช้คืน null */
function ppPostAccountId(p) {
 const a = String((p && p.author) || '');
 if (a === 'user') return 'main';
 if (a.startsWith('acc:')) {
  const acc = ppFindAccount(a.slice(4));
  if (acc && (acc.owner || 'user') === 'user') return acc.id;
 }
 return null;
}
/** เจ้าของโพสต์ในรูปคอนแทกต์ — แปลง acc: ของ NPC กลับเป็นตัวเจ้าของ */
function ppPostOwnerContact(p) {
 const a = String((p && p.author) || '');
 if (!a || a === 'user' || a === 'news' || a.startsWith('ghost:')) return null;
 if (a.startsWith('acc:')) {
  const acc = ppFindAccount(a.slice(4));
  const own = acc && (acc.owner || 'user');
  return own && own !== 'user' ? own : null;
 }
 return a;
}
/** บัญชีนี้ล็อกอยู่ไหม — บัญชีหลักใช้ค่าเดิมของแอป */
function ppAccLocked(accId) {
 if (!accId || accId === 'main') return getCfg().accountLocked === true;
 const a = ppFindAccount(accId);
 return !!(a && a.locked === true);
}
function ppAccBio(accId) {
 const cfg = getCfg();
 if (!accId || accId === 'main') {
  const a0 = ppFindAccount('main');
  return (a0 && a0.bio) || cfg.userBio || '';
 }
 const a = ppFindAccount(accId);
 return (a && a.bio) || '';
}
function ppAccLink(accId) {
 const cfg = getCfg();
 if (!accId || accId === 'main') {
  const a0 = ppFindAccount('main');
  return (a0 && a0.link) || cfg.userLink || '';
 }
 const a = ppFindAccount(accId);
 return (a && a.link) || '';
}
/** ยอดผู้ติดตามที่แสดงของบัญชีนี้ = คนที่เลือกไว้ + ตัวเลขที่ตั้งเอง */
function ppAccFollowerTotal(accId) {
 if (!accId || accId === 'main') return totalFollowerCount();
 const a = ppFindAccount(accId) || {};
 return ppAccFollowers(accId).length + (a.followerCount || 0);
}
function ppAccFollowingTotal(accId) {
 if (!accId || accId === 'main') return (getCfg().following || []).length;
 const a = ppFindAccount(accId) || {};
 return ppAccFollowing(accId).length + (a.followingCount || 0);
}
/** ★ 2.8.3 เลือกผู้ติดตามหรือคนที่ตามอยู่ของบัญชีนั้น — ใช้ได้ทั้งบัญชีหลักและบัญชีรอง */
function ppAccPeopleEditor(accId, which, after) {
 const isFol = which !== 'following';
 const id = accId || 'main';
 // บัญชีหลักใช้ทางเดิมเพื่อให้บันทึกกิจกรรมยังเหมือนเก่า
 if (id === 'main') {
  return ppAccountList(isFol ? 'followers' : 'following',
   isFol ? 'ผู้ติดตาม' : 'กำลังติดตาม',
   isFol ? 'ผู้ติดตาม' : 'กำลังติดตาม');
 }
 const arr = isFol ? ppAccFollowers(id) : ppAccFollowing(id);
 const nm = ppAccName(id);
 ppMultiSelect({
  title: `${isFol ? 'ผู้ติดตามของ' : 'บัญชีนี้ติดตาม'} @${ppAccHandle(id)}`,
  selected: arr.slice(),
  onDone: sel => {
   const before = arr.slice();
   arr.length = 0;
   Array.prototype.push.apply(arr, sel);
   saveCfg();
   const added = sel.filter(x => !before.includes(x)).map(cname);
   const removed = before.filter(x => !sel.includes(x)).map(cname);
   const sub = [];
   if (added.length) sub.push(`เพิ่ม: ${added.join(', ')}`);
   if (removed.length) sub.push(`เอาออก: ${removed.join(', ')}`);
   if (sub.length) ppLog('account', `แก้ไข${isFol ? 'ผู้ติดตาม' : 'รายชื่อที่ติดตาม'}ของบัญชี ${nm}`, sub);
   ppRefreshAllViews();
   ppToast(`บันทึกแล้ว · ${sel.length} คน`);
   if (after) after();
  },
 });
}
/** ★ 2.8.3 เลือกรูปโปรไฟล์ของบัญชีจากเครื่อง — ย่อให้เล็กก่อนเก็บ */
function ppAccAvatarPick(accId, after) {
 const a = ppFindAccount(accId);
 if (!a) return;
 let inp = document.getElementById('pp-accav-file');
 if (!inp) {
  inp = document.createElement('input');
  inp.type = 'file';
  inp.id = 'pp-accav-file';
  inp.accept = 'image/*';
  inp.hidden = true;
  (document.getElementById('pp-frame') || document.body).appendChild(inp);
 }
 inp.onchange = async e => {
  const f = e.target.files && e.target.files[0];
  e.target.value = '';
  inp.onchange = null;
  if (!f) return;
  islandStatus('กำลังย่อรูป…');
  const dataUrl = await ppReadImageFile(f, 640, { keepAlpha: true });
  islandCollapse();
  if (!dataUrl) { ppToast('อ่านไฟล์รูปไม่ได้ ลองรูปที่เล็กลง'); return; }
  // ★ 2.9.1 รูปโปรไฟล์ครอบเป็นสี่เหลี่ยมจัตุรัสได้ จะได้ไม่โดนวงกลมตัดหัว
  ppMaybeCrop(dataUrl, url => {
   a.avatar = url;
   saveCfg();
   ppRefreshAllViews();
   ppToast('เปลี่ยนรูปแล้ว');
   if (after) after();
  }, { ratio: 1, maxDim: 320, keepAlpha: true });
 };
 setTimeout(() => inp.click(), 30);
}
/** สร้างบัญชีใหม่ */
function ppCreateAccount(owner, name) {
 const cfg = getCfg();
 const acc = {
  id: newId(), owner: owner || 'user',
  name: String(name || '').slice(0, 60), handle: '',
  avatar: '', cover: '', bio: '', link: '',
  followerCount: 0, followingCount: 0,
  locked: false, knownBy: [], theme: '',
  primary: false, ts: Date.now(),
 };
 ppAccounts().push(acc);
 saveCfg();
 return acc;
}
/** ลบบัญชี พร้อมเลือกว่าจะลบโพสต์ด้วยไหม */
function ppDeleteAccount(accId, alsoPosts) {
 const cfg = getCfg();
 if (accId === 'main') return { ok: false, reason: 'ลบบัญชีหลักไม่ได้' };
 const key = ppAuthorKey(accId);
 let removed = 0;
 if (alsoPosts) {
  const before = cfg.feedPosts.length;
  cfg.feedPosts = cfg.feedPosts.filter(p => p.author !== key);
  removed = before - cfg.feedPosts.length;
  cfg.stories = (cfg.stories || []).filter(s => s.author !== key);
 } else {
  // ย้ายโพสต์กลับบัญชีหลัก
  cfg.feedPosts.forEach(p => { if (p.author === key) p.author = 'user'; });
  (cfg.stories || []).forEach(s => { if (s.author === key) s.author = 'user'; });
 }
 cfg.accounts = ppAccounts().filter(a => a.id !== accId);
 if (cfg.activeAccount === accId) cfg.activeAccount = 'main';
 saveCfg();
 return { ok: true, removed };
}
/** สลับบัญชี */
function ppSwitchAccount(accId) {
 const cfg = getCfg();
 const a = ppFindAccount(accId);
 if (!a) return false;
 cfg.activeAccount = a.id;
 saveCfg();
 ppLog('account', `สลับไปใช้บัญชี ${ppAccName(a.id)} (@${ppAccHandle(a.id)})`);
 return true;
}
/** ตัวละครคนนี้รู้ไหมว่าบัญชีนี้เป็นคุณ */
function ppAccKnownBy(accId, cid) {
 const a = ppFindAccount(accId);
 if (!a) return true;
 if (a.id === 'main') return true;
 if (a.knownBy === null || a.knownBy === undefined) return true; // null = ทุกคนรู้
 return Array.isArray(a.knownBy) && a.knownBy.includes(cid);
}
/** ผู้ติดตามของบัญชีนี้ — บัญชีหลักใช้ของเดิม บัญชีอื่นเก็บแยก */
function ppAccFollowers(accId) {
 const cfg = getCfg();
 if (!accId || accId === 'main') return cfg.followers || [];
 const a = ppFindAccount(accId);
 if (!a) return [];
 if (!Array.isArray(a.followers)) a.followers = [];
 return a.followers;
}
function ppAccFollowing(accId) {
 const cfg = getCfg();
 if (!accId || accId === 'main') return cfg.following || [];
 const a = ppFindAccount(accId);
 if (!a) return [];
 if (!Array.isArray(a.following)) a.following = [];
 return a.following;
}
// ══════════════════════════════════════════════════════════
// ★ 2.5.0 NPC KEYWORD — ดึงโปรไฟล์ NPC เข้าโรลเมื่อมีคนเอ่ยชื่อ
// ปิดเป็นค่าเริ่มต้น เทิร์นที่ไม่มีใครเอ่ยชื่อจะไม่กินโทเคนเลย
// ══════════════════════════════════════════════════════════
/** คีย์เวิร์ดของ NPC คนนี้ — ชื่อเป็นคำเริ่มต้นให้อัตโนมัติ */
function ppNpcKwWords(c) {
 if (!c) return [];
 const out = [];
 const push = s => {
  const t = String(s || '').trim().toLowerCase();
  if (t && t.length >= 2 && !out.includes(t)) out.push(t);
 };
 push(dname(c));
 push(c.name);
 push(c.handle);
 String(c.kwWords || '').split(',').forEach(push);
 // ★ 2.7.0 ชื่อและคำค้นของบัญชีรองก็ดึงเจ้าของเข้าโรลได้
 try {
  ppAccountsOf(c.id).forEach(a => {
   push(a.name);
   push(a.handle);
   String(a.kwWords || '').split(',').forEach(push);
  });
 } catch {}
 return out;
}
/** NPC ที่มีโปรไฟล์และเข้าเงื่อนไขในข้อความล่าสุด */
function ppNpcKwMatches(hay) {
 const cfg = getCfg();
 if (cfg.npcKwEnabled !== true) return [];
 const H = String(hay || '').toLowerCase();
 if (!H) return [];
 const scope = currentCharacterId();
 const out = [];
 getContacts().forEach(c => {
  if (!c.npc) return;
  if (c.kwOff === true) return;
  // เอาเฉพาะ NPC ที่ผูกกับตัวละครที่เปิดอยู่ ถ้ามีตัวละครเปิดอยู่
  if (scope && c.baseCharId !== scope && c.ownerCharId !== scope) return;
  const words = ppNpcKwWords(c);
  if (!words.length) return;
  if (!words.some(w => H.includes(w))) return;
  out.push(c);
 });
 const max = Math.max(1, Math.min(6, cfg.npcKwMax || 3));
 return out.slice(0, max);
}
/** ข้อความ system ที่แนบโปรไฟล์ NPC เข้าโรล */
function ppNpcKwBlock(hay) {
 const hits = ppNpcKwMatches(hay);
 const cfg = getCfg();
 cfg.npcKwLastHit = hits.map(c => dname(c));
 if (!hits.length) return '';
 const rows = hits.map(c => {
  const bits = [`${dname(c)}`];
  if (c.handle) bits.push(`@${c.handle}`);
  if (c.npcDesc) bits.push(String(c.npcDesc).replace(/\s+/g, ' ').slice(0, 260));
  if (c.bio) bits.push(`bio: ${String(c.bio).replace(/\s+/g, ' ').slice(0, 120)}`);
  const posts = ppProfilePosts(c.id).slice(-2)
   .map(p => `"${String(p.text || '[รูป]').replace(/\s+/g, ' ').slice(0, 60)}"`);
  if (posts.length) bits.push(`เพิ่งโพสต์ว่า ${posts.join(' ')}`);
  if (c.followerCount) bits.push(`ผู้ติดตาม ${fmtCount(c.followerCount)}`);
  // ★ 2.7.0 บัญชีรอง — โรลจะแยกออกว่าแอคไหนคือแอคไหน
  try {
   const alt = ppAccountsOf(c.id);
   if (alt.length) {
    bits.push('also runs: ' + alt.map(a => {
     const nm = ppAccName(a.id);
     const h = ppAccHandle(a.id);
     const kw = String(a.kwWords || '').trim();
     return `${nm}(@${h}${kw ? ' — ' + kw : ''})`;
    }).join(' · '));
   }
  } catch {}
  ppNpcFlags(c);
  // ★ 2.8.0 บัญชีส่วนตัวของเขา
  if (c.locked === true) {
   bits.push(c.approved === true
    ? `their account is private but the user is allowed in`
    : c.reqPending === true
     ? `their account is private and the user has asked to be let in — they must decide`
     : `their account is private; the user cannot see their posts`);
  }
  const rel = [];
  if (c.folUser) rel.push('follows the user');
  const hostId = c.baseCharId || c.ownerCharId;
  if (hostId && c.folHost) rel.push(`follows ${cname(hostId)}`);
  if (hostId && c.hostFol) rel.push(`followed by ${cname(hostId)}`);
  if (rel.length) bits.push(rel.join(', '));
  return `- ${bits.join(' · ')}`;
 });
 return [
  `[NPC PROFILES — these people already exist with a set profile. Use them as written; do not invent a different personality for them.]`,
  rows.join('\n'),
 ].join('\n');
}
async function ppNpcKwTokens() {
 const cfg = getCfg();
 const npcs = getContacts().filter(c => c.npc && c.kwOff !== true);
 if (!npcs.length) return 0;
 // วัดจากตัวอย่างสามตัวแรกเพื่อให้เห็นค่าโดยประมาณของกรณีเข้าเงื่อนไข
 const sample = npcs.slice(0, Math.max(1, Math.min(3, cfg.npcKwMax || 3)));
 const hay = sample.map(dname).join(' ');
 const saved = cfg.npcKwEnabled;
 cfg.npcKwEnabled = true;
 let n = 0;
 try { n = await ppCountTokens(ppNpcKwBlock(hay)); } catch {} finally { cfg.npcKwEnabled = saved; }
 return n;
}
window.PP_LOADED = 'parsed-1of4';
