/* ══════════════════════════════════════════════════════════
 * ★ 2.10.0 หมวดตกแต่ง
 * ฟอนต์ไทยจาก Google Fonts โหลดเฉพาะตัวที่เลือก ไม่โหลดยกชุด
 * ══════════════════════════════════════════════════════════ */
/* ══════════════════════════════════════════════════════════
 * ★ 2.11.0 ชุดหน้าจอสำเร็จรูป
 * ทุกธีมวาดด้วย CSS ล้วน ไม่ใช้ไฟล์รูป จึงส่งต่อได้ครบและไม่กินพื้นที่
 * ══════════════════════════════════════════════════════════ */
/** ★ 2.12.0 ชุดสีสร้างจากสูตร ได้ทั้งจำนวนมากและกลมกลืนกันทุกชุด
 * h = องศาสี · s = ความอิ่มสี · mode = light หรือ dark
 * ทุกชุดวาดด้วย CSS ล้วน ไม่มีไฟล์รูป จึงส่งต่อได้ครบและไม่กินพื้นที่ */
function _ppTheme(id, name, sub, h, sat, mode) {
 const L = (l, a) => `hsl(${h} ${sat}% ${l}%${a != null ? ` / ${a}` : ''})`;
 if (mode === 'dark') return {
  id, name, sub, dark: 1,
  bg: `linear-gradient(178deg,${L(8)},${L(13)} 55%,${L(19)})`,
  ink: L(70), cl: L(88),
  surf: `hsl(${h} ${sat}% 100% / .12)`, soft: `hsl(${h} ${sat}% 100% / .06)`,
  sh: `inset 0 0 0 .5px hsl(${h} ${sat}% 100% / .16)`,
 };
 return {
  id, name, sub, dark: 0,
  bg: `linear-gradient(176deg,${L(97)},${L(93)} 48%,${L(87)})`,
  ink: L(42), cl: L(58),
  surf: 'rgba(255,255,255,.88)', soft: 'rgba(255,255,255,.55)',
  sh: `0 2px 8px ${L(60, .22)}`,
 };
}
