function userAvatarAuto() {
 const c = ctx();
 try {
 if (c) {
 if (c.userAvatar) return `/User Avatars/${c.userAvatar}`;
 if (c.user_avatar) return `/User Avatars/${c.user_avatar}`;
 const pa = c.powerUserSettings?.persona_description_avatar;
 if (pa) return `/User Avatars/${pa}`;
 }
 } catch {}
 return '';
}
async function refreshUserAvatar() {
 const cfg = getCfg();
 if (cfg.userAvatarMode === 'custom') { const img = await loadMedia('user-avatar'); ppUserAvatarCache = img || userAvatarAuto(); }
 else ppUserAvatarCache = userAvatarAuto();
 return ppUserAvatarCache;
}
function avHTML(src, fallbackChar, size, cls) {
 const s = size || 52;
 const k = cls ? ' ' + cls : '';
 if (src) {
 return `<img class="pp-avatar${k}" style="width:${s}px;height:${s}px" src="${esc(src)}"
 onerror="this.replaceWith(document.createRange().createContextualFragment('<span class=\\'pp-avatar pp-avatar-fb${k}\\' style=\\'width:${s}px;height:${s}px;font-size:${Math.round(s * 0.4)}px\\'>${esc(fallbackChar || '?')}</span>'))">`;
 }
 return `<span class="pp-avatar pp-avatar-fb${k}" style="width:${s}px;height:${s}px;font-size:${Math.round(s * 0.4)}px">${esc(fallbackChar || '?')}</span>`;
}
function userAvatarHTML(size, cls) { return avHTML(ppUserAvatarCache, getUserDisplayName()[0] || 'U', size, cls); }
function contactAvatarHTML(c, size, cls) { return avHTML(c && c.avatar, dname(c)[0], size, cls); }
function groupAvatarHTML(g, size) {
 const s = size || 52;
 const mem = groupMemberContacts(g).slice(0, 2);
 if (!mem.length) return avHTML('', (g && g.name || 'G')[0], s);
 const inner = mem.map((c, i) => `<span class="pp-grp-av-piece pos${i}">${contactAvatarHTML(c, Math.round(s * 0.62))}</span>`).join('');
 return `<span class="pp-grp-av" style="width:${s}px;height:${s}px">${inner}</span>`;
}
function threadAvatarHTML(tid, size) {
 if (isGroupId(tid)) return groupAvatarHTML(getGroup(tid), size);
 return contactAvatarHTML(findContact(tid) || { name: tid }, size);
}
function threadName(tid) {
 if (isGroupId(tid)) { const g = getGroup(tid); return g ? (g.name || 'กลุ่ม') : 'กลุ่ม'; }
 return cname(tid);
}

function startClock() {
 if (ppClockTimer) return;
 const tick = () => {
 const t = ppNow();
 document.querySelectorAll('.pp-clock').forEach(e => e.textContent = t);
 const dl = document.getElementById('pp-home-date'); if (dl) dl.textContent = ppDateLabel();
 // ★ 2.20.0 ส่งแผนที่ถึงเวลาแล้ว เช็คทุกนาทีตอนเปิดมือถืออยู่
 try { if (!tick._n || Date.now() - tick._n > 55000) { tick._n = Date.now(); ppFlushBack(); ppFlushPlans(); } } catch {}
 };
 tick();
 ppClockTimer = setInterval(tick, 10000);
}
function applyTheme() {
 const frame = document.getElementById('pp-frame');
 if (!frame) return;
 const cfg = getCfg();
 frame.classList.toggle('light', cfg.theme === 'light');
 frame.style.setProperty('--pp-accent', cfg.accent || '#0a84ff');
}
function applyIsland() {
 const island = document.getElementById('pp-island');
 if (island) island.style.display = getCfg().dynamicIsland ? 'flex' : 'none';
}
async function applyWallpaper() {
 const el = document.getElementById('pp-home-wp');
 if (!el) return;
 const cfg = getCfg();
 el.style.filter = `blur(${cfg.homeBlur ?? 6}px)`;
 const wp = cfg.wallpaper || 'aurora';
 if (wp === 'custom') {
 const img = await loadMedia('home-wp');
 if (img) { el.style.background = '#000 center/cover no-repeat'; el.style.backgroundImage = `url(${img})`; return; }
 }
 el.style.backgroundImage = '';
 el.style.background = WALLPAPERS[wp] || WALLPAPERS.aurora;
}
function updateHomeWidgets() {
 const info = periodTodayInfo();
 const pm = document.getElementById('pp-w-period');
 const ps = document.getElementById('pp-w-period-sub');
 if (pm) {
 if (info.onPeriod) { pm.textContent = `วันที่ ${info.dayNum}`; if (ps) ps.textContent = 'มีประจำเดือน'; }
 else if (info.upcomingIn != null && info.upcomingIn >= 0) { pm.textContent = `อีก ${info.upcomingIn} วัน`; if (ps) ps.textContent = phaseLabel(info.phase); }
 else { pm.textContent = '—'; if (ps) ps.textContent = 'ยังไม่มีข้อมูล'; }
 }
 const cfg = getCfg();
 const wm = document.getElementById('pp-w-wallet');
 const ws = document.getElementById('pp-w-wallet-sub');
 if (wm) wm.textContent = fmtMoney(walletBalanceGet());
 if (ws) { const sp = spentToday(); ws.textContent = sp ? `วันนี้ใช้ ${fmtMoney(sp)}` : 'วันนี้ยังไม่ใช้'; }
 // badges
 const totalUnread = Object.values(cfg.unread || {}).reduce((a, b) => a + b, 0);
 // ล้าง badge ทุกตัวก่อน กันค้างจาก nav ที่ไม่ได้เซ็ต
 document.querySelectorAll('.pp-icon-badge').forEach(el => { el.textContent = ''; el.style.display = 'none'; el.classList.remove('dot'); });
 const setBadge = (nav, n, dot) => {
 const el = document.querySelector(`[data-badge="${nav}"]`);
 if (!el) return;
 const v = Number(n) || 0;
 if (dot) {
  el.classList.toggle('dot', v > 0);
  // เว้นวรรคไม่ตัด เพื่อไม่ให้ตรงกฎ :empty ที่ซ่อนป้ายไว้ตอนไม่มีของใหม่
  el.textContent = v > 0 ? '\u00A0' : '';
  el.style.display = v > 0 ? 'block' : 'none';
  return;
 }
 el.textContent = v > 0 ? String(v) : '';
 el.style.display = v > 0 ? 'block' : 'none';
 };
 setBadge('messages', totalUnread);
 setBadge('feed', unreadNotifCount() + unseenMentions() + newsPosts().filter(p => !(cfg.newsSeen || {})[p.id]).length);
 // [2.39.0] เปลี่ยนจากเลขจำนวนรุ่นเป็นจุดแดงเฉย ๆ กันตัวเลขดูรกตา
 setBadge('helper', ppUnreadVersions().length, true);
 // ★ 1.4.0 เอาแอปข่าวออกจากหน้าโฮมแล้ว — ข่าวรวมอยู่ในเลขของฟีด
}

// ══════════════════════════════════════════════════════════
// nav
// ══════════════════════════════════════════════════════════
function ppOpen() {
 const dlg = document.getElementById('pp-dialog');
 if (!dlg) return;
 if (getCfg().extOff) { try { toastr.info('Pocket Phone ปิดอยู่ · เปิดได้ที่แผงควบคุม'); } catch {} return; }
 applyTheme(); applyIsland(); applyWallpaper(); ppApplyDeco(); ppApplyStatusBar(); ppApplyCtrl(); startClock();
 ppApplyIglass(); ppLgWatch();
 try { ppShowLock(); } catch {}
 try {
  const sb = document.getElementById('pp-statusbar');
  if (sb) sb.style.display = getCfg().hideStatusBar ? 'none' : '';
  const fr = document.getElementById('pp-frame');
  if (fr) fr.classList.toggle('no-statusbar', !!getCfg().hideStatusBar);
 } catch {}
 try { ppFixGroupSenders(); ppFlushBack(); ppFlushPlans(); } catch (e) { console.error('[pocket-phone] plans', e); }
 // ★ 2.35.0 เปิดมือถือแล้วแปลว่าออกจากโหมดแอพแล้ว เก็บปุ่มกลับบ้านทิ้ง
 try { if (getCfg().stAppMode) { getCfg().stAppMode = false; saveCfg(); } ppStHomeBtn(false); } catch {}
 refreshUserAvatar().then(() => { if (ppCurrentScreen === 'home') updateHomeWidgets(); });
 pruneStories(); updateHomeWidgets(); ppUpdateLogBadge();
 ppClearRoute(); // ★ 1.7.1 เปิดมือถือใหม่ = ล้างเส้นทางเก่า
 if (typeof dlg.showModal === 'function' && !dlg.open) dlg.showModal();
 else dlg.setAttribute('open', '');
 islandRefresh();
}
/* ══════════════════════════════════════════════════════════
 * ★ 2.36.0 เว็บบอร์ด — กระทู้ถามตอบแบบไทย
 * ออกแบบเอง ไม่อิงชื่อหรือโลโก้ของเว็บจริงที่ไหน
 * ══════════════════════════════════════════════════════════ */
const PP_BOARD_ROOMS = [
 { id: 'all', name: 'ทั้งหมด', icon: '' },
 { id: 'ask', name: 'ถามตอบ', sub: 'สงสัยอะไรถามได้' },
 { id: 'vent', name: 'ระบายใจ', sub: 'ที่ปล่อยของหนัก ๆ' },
 { id: 'talk', name: 'ซุบซิบ', sub: 'เรื่องเล่าและข่าวลือ' },
 { id: 'review', name: 'รีวิว', sub: 'ของกิน ของใช้ ที่เที่ยว' },
 { id: 'love', name: 'ความรัก', sub: 'ปรึกษาเรื่องหัวใจ' },
];
function ppBoard() {
 const cfg = getCfg();
 if (!Array.isArray(cfg.boardThreads)) cfg.boardThreads = [];
 return cfg.boardThreads;
}
function ppBoardFind(id) { return ppBoard().find(t => t.id === id); }
function ppBoardRoomName(id) { return (PP_BOARD_ROOMS.find(r => r.id === id) || {}).name || 'ทั่วไป'; }
/** ชื่อที่โชว์ในบอร์ด ใช้นามแฝง ไม่ใช่ชื่อจริง เหมือนเว็บบอร์ดจริง */
function ppBoardName(a, ghostName) {
 if (a === 'ghost') return String(ghostName || 'คนแปลกหน้า').trim() || 'คนแปลกหน้า';
 if (a === 'user') return getCfg().boardAlias || 'สมาชิกหมายเลข ' + (getCfg().boardNum || 1);
 const c = findContact(a);
 return c ? dname(c) : String(a || 'สมาชิก');
}
/** ★ 2.38.0 ยอดวิว คำนวณจากอายุกระทู้กับความนิยม ไม่ต้องเก็บเพิ่ม
 * สุ่มด้วยรหัสกระทู้ จึงได้เลขเดิมทุกครั้ง ไม่กระพริบไปมา */
function ppBoardViews(t) {
 if (!t) return 0;
 let seed = 0;
 String(t.id || '').split('').forEach(ch => { seed = (seed * 31 + ch.charCodeAt(0)) % 9973; });
 const hrs = Math.max(1, (Date.now() - (t.ts || 0)) / 3600000);
 const r = (t.replies || []).length;
 const base = 18 + seed % 60 + r * (9 + seed % 14) + (t.likes || 0) * 4;
 return Math.round(base * Math.min(9, 1 + Math.log2(hrs + 1) * 0.7));
}
/** แท็กอัตโนมัติจากเนื้อหา ไม่ต้องให้ผู้ใช้ใส่เอง */
function ppBoardTags(t) {
 if (!t) return [];
 if (Array.isArray(t.tags) && t.tags.length) return t.tags.slice(0, 3);
 const txt = String((t.title || '') + ' ' + (t.body || ''));
 const rules = [
  [/เรียน|สอบ|การบ้าน|ครู|โรงเรียน/, 'เรื่องเรียน'],
  [/รัก|แฟน|ชอบ|อกหัก|จีบ/, 'ความรัก'],
  [/เงิน|ราคา|ถูก|แพง|ซื้อ/, 'เงินทอง'],
  [/กิน|ร้าน|อร่อย|คาเฟ่/, 'ของกิน'],
  [/เศร้า|เหนื่อย|ท้อ|ร้องไห้/, 'ระบาย'],
  [/ช่วย|ทำไง|ยังไง|แนะนำ/, 'ขอคำแนะนำ'],
 ];
 const out = [];
 rules.forEach(([re, tag]) => { if (out.length < 3 && re.test(txt)) out.push(tag); });
 return out;
}
/** กระทู้ที่ยังไม่มีใครตอบ */
function ppBoardUnanswered() { return ppBoard().filter(t => !(t.replies || []).length); }
function ppBoardMarks() {
 const cfg = getCfg();
 if (!Array.isArray(cfg.boardMarks)) cfg.boardMarks = [];
 return cfg.boardMarks;
}

function ppBoardHot(t) {
 const r = (t.replies || []).length;
 const age = Math.max(1, (Date.now() - (t.ts || 0)) / 3600000);
 return (r * 3 + (t.likes || 0)) / Math.pow(age, .4);
}

/** ══ ★ 2.35.0 เปิด SillyTavern เป็นแอพในมือถือ ══
 * มือถือย่อหายไป เหลือบทหลักเต็มจอเหมือนเปิดแอพจริง
 * มีปุ่มกลับบ้านลอยไว้ กดแล้วมือถือกลับมาที่หน้าจอหลักเหมือนเดิม
 * ไม่แตะโครงของ SillyTavern เลย จึงไม่พังเมื่อเขาอัปเดต */
/** ★ 2.35.0 เปิดปิดแถบสถานะบนสุด
 * ปิดแล้วเนื้อหาต้องขยายขึ้นไปแทนที่ ไม่ทิ้งช่องว่างไว้
 * เกาะเกี่ยวกับ Dynamic Island ด้วย เพราะมันอยู่ในแถบเดียวกัน */
/** ══ ★ 2.36.0 ศูนย์ควบคุม ══
 * ไม่ได้ทำงานจริงทุกปุ่ม แต่สถานะเปลี่ยนได้และมีผลกับแถบสถานะจริง */
function ppCtrl() {
 const cfg = getCfg();
 if (!cfg.ctrl || typeof cfg.ctrl !== 'object') cfg.ctrl = { wifi: true, bt: false, air: false, dnd: false, bright: 80, vol: 60 };
 return cfg.ctrl;
}
function ppOpenControl() {
 const c = ppCtrl();
 document.getElementById('pp-cc')?.remove();
 const box = document.createElement('div');
 box.id = 'pp-cc';
 const tile = (k, on, icon, lb) =>
  `<button class="pp-cc-tile${on ? ' on' : ''}" data-cc="${k}">${icon}<span>${esc(lb)}</span></button>`;
 box.innerHTML = `<div class="pp-cc-sheet">
  <div class="pp-cc-grab"></div>
  <div class="pp-cc-grid">
   ${tile('air', c.air, ICON.plane || ICON.send, 'โหมดบิน')}
   ${tile('wifi', c.wifi && !c.air, ICON.wifi, 'ไวไฟ')}
   ${tile('bt', c.bt && !c.air, ICON.link || ICON.share, 'บลูทูธ')}
   ${tile('dnd', c.dnd, ICON.moon || ICON.bell, 'ห้ามรบกวน')}
  </div>
  <div class="pp-cc-row">
   ${tile('theme', getCfg().theme !== 'light', ICON.moon || ICON.eye, 'โหมดมืด')}
   ${tile('sb', getCfg().statusBar !== false, ICON.phone || ICON.gear, 'แถบสถานะ')}
  </div>
  <div class="pp-cc-row">
   <button class="pp-cc-tile" data-nav="browser">${ICON.compass}<span>ค้นหาและเกม</span></button>
  </div>
  <div class="pp-cc-slider">
   <span class="lb">${ICON.sun || ICON.eye} ความสว่าง</span>
   <input type="range" min="30" max="100" value="${c.bright}" id="pp-cc-bright">
  </div>
  <div class="pp-cc-slider">
   <span class="lb">${ICON.volume || ICON.music} เสียง</span>
   <input type="range" min="0" max="100" value="${c.vol}" id="pp-cc-vol">
  </div>
  <button class="pp-cc-done">เสร็จแล้ว</button>
 </div>`;
 const f = document.getElementById('pp-frame');
 (f || document.body).appendChild(box);
 requestAnimationFrame(() => box.classList.add('show'));
 const close = () => { box.classList.remove('show'); setTimeout(() => box.remove(), 240); };
 box.addEventListener('click', ev => { if (ev.target === box) close(); });
 box.querySelector('.pp-cc-done')?.addEventListener('click', ev => { ev.stopPropagation(); close(); });
 box.querySelectorAll('[data-cc]').forEach(b => b.addEventListener('click', ev => {
  ev.stopPropagation();
  const k = b.dataset.cc;
  const cfg = getCfg();
  if (k === 'theme') { cfg.theme = cfg.theme === 'light' ? 'dark' : 'light'; applyTheme(); }
  else if (k === 'sb') { cfg.statusBar = cfg.statusBar === false; ppApplyStatusBar(); }
  else if (k === 'air') { c.air = !c.air; if (c.air) { c.wifi = false; c.bt = false; } }
  else { if (c.air) { ppToast('ปิดโหมดบินก่อน'); return; } c[k] = !c[k]; }
  saveCfg(); ppApplyCtrl(); close(); setTimeout(ppOpenControl, 180);
 }));
 const bind = (id, key) => {
  const el = document.getElementById(id);
  if (!el) return;
  el.addEventListener('input', () => { c[key] = +el.value; saveCfg(); ppApplyCtrl(); });
 };
 bind('pp-cc-bright', 'bright');
 bind('pp-cc-vol', 'vol');
 box.querySelector('[data-nav="browser"]')?.addEventListener('click', () => close());
}
/** ทาผลของศูนย์ควบคุมลงเครื่อง */
function ppApplyCtrl() {
 const f = document.getElementById('pp-frame');
 if (!f) return;
 const c = ppCtrl();
 f.style.setProperty('--pp-bright', String(Math.max(30, Math.min(100, c.bright || 80)) / 100));
 f.classList.toggle('pp-air', !!c.air);
 f.classList.toggle('pp-nowifi', !c.wifi || !!c.air);
 f.classList.toggle('pp-dnd', !!c.dnd);
 try { const el = ppAudio(); if (el) el.volume = Math.max(0, Math.min(1, (c.vol || 60) / 100)); } catch {}
}

/** ══ ★ 2.36.0 หน้าล็อก ══ */
function ppShowLock() {
 if (!getCfg().lockOn) return false;
 const f = document.getElementById('pp-frame');
 if (!f || document.getElementById('pp-lock')) return true;
 const d = new Date();
 const un = (getCfg().unread || {});
 const n = Object.values(un).reduce((a, b) => a + (+b || 0), 0);
 const box = document.createElement('div');
 box.id = 'pp-lock';
 box.innerHTML = `
  <div class="pp-lock-clock">${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}</div>
  <div class="pp-lock-date">${esc(ppDateLabel())}</div>
  ${n ? `<div class="pp-lock-notif">${ICON.messages}<span>${n} ข้อความที่ยังไม่อ่าน</span></div>` : ''}
  <div class="pp-lock-hint">ปัดขึ้นเพื่อปลดล็อก</div>`;
 f.appendChild(box);
 requestAnimationFrame(() => box.classList.add('show'));
 const unlock = () => {
  box.classList.add('gone');
  setTimeout(() => box.remove(), 380);
 };
 let y0 = null;
 box.addEventListener('pointerdown', e => { y0 = e.clientY; });
 box.addEventListener('pointerup', e => {
  if (y0 !== null && y0 - e.clientY > 40) unlock();
  else if (y0 !== null && Math.abs(y0 - e.clientY) < 6) unlock();
  y0 = null;
 });
 return true;
}

function ppApplyStatusBar() {
 const f = document.getElementById('pp-frame');
 if (!f) return;
 const on = getCfg().statusBar !== false;
 f.classList.toggle('no-statusbar', !on);
 // เกาะรถไฟกันไว้ ถ้าปิดแถบแล้วเกาะยังลอยอยู่จะดูแปลก
 const isl = document.getElementById('pp-island');
 if (isl) isl.style.display = on ? '' : 'none';
 // ★ 2.36.0 ปุ่มปิดอยู่ในแถบสถานะ พอซ่อนแถบก็หายไปด้วย จนกดออกไม่ได้
 // ต้องมีปุ่มสำรองลอยไว้เสมอเมื่อแถบถูกซ่อน
 let esc = document.getElementById('pp-escape-btn');
 if (!on) {
  if (!esc) {
   esc = document.createElement('button');
   esc.id = 'pp-escape-btn';
   esc.title = 'ปิดมือถือ';
   esc.innerHTML = ICON.close;
   esc.addEventListener('click', ev => { ev.stopPropagation(); ppClose(); });
   f.appendChild(esc);
  }
  esc.style.display = '';
 } else if (esc) { esc.style.display = 'none'; }
}

/* ══════════════════════════════════════════════════════════
 * [2.39.0] iGlassOS — การตั้งค่า Liquid Glass และการทาผล
 * เก็บข้อมูลไว้ใต้ cfg.iglass แบบ lazy เหมือน ppCtrl()
 * ══════════════════════════════════════════════════════════ */
function ppGx() {
 const cfg = getCfg();
 if (!cfg.iglass || typeof cfg.iglass !== 'object') cfg.iglass = {};
 const d = {
  lg: true,            // เปิดปิด Liquid Glass ทั้งชุด
  material: 'tinted',  // lg-clear | lg-tinted | lg-frosted
  edge: 70,             // ความแรงของขอบแสง 0-100
  parallax: true,       // วอลเปเปอร์ขยับตามนิ้ว/เมาส์
  haptics: true,        // การสั่น
  battPct: false,       // แสดง % แบตบนแถบสถานะ
  lowpower: false,      // โหมดประหยัดพลังงาน
  chatFx: false,        // เอฟเฟกต์เต็มจอในแชท (ปิดเป็นค่าเริ่มต้น เปิดได้ที่ตั้งค่า > ตกแต่ง > แชท)
 };
 for (const k of Object.keys(d)) if (cfg.iglass[k] === undefined) cfg.iglass[k] = d[k];
 return cfg.iglass;
}
/** ทาคลาส/ตัวแปร Liquid Glass ลงเฟรม เรียกซ้ำได้ปลอดภัย */
function ppApplyIglass() {
 const f = document.getElementById('pp-frame');
 if (!f) return;
 const g = ppGx();
 f.classList.toggle('pp-lg', !!g.lg);
 f.classList.remove('lg-clear', 'lg-tinted', 'lg-frosted');
 f.classList.add('lg-' + (g.material === 'clear' || g.material === 'frosted' ? g.material : 'tinted'));
 f.classList.toggle('pp-lowpower', !!g.lowpower);
 f.style.setProperty('--lg-edge-a', String(Math.max(0, Math.min(100, g.edge != null ? g.edge : 70)) / 100));
 try { if (document.getElementById('pp-home')) ppRenderHomeDots(); } catch {}
 requestAnimationFrame(ppLgSyncPills);
}
/** วัดตำแหน่งปุ่มที่เลือก (.on) ในแท็บ/สวิตช์แบ่งหมวดทุกตัว แล้วส่งเป็น CSS var
 * ให้หยดกระจกไหลตามได้โดยไม่ต้องแก้ทุกฟังก์ชัน render ที่สร้างแท็บ */
function ppLgSyncPills() {
 const f = document.getElementById('pp-frame');
 if (!f || !f.classList.contains('pp-lg')) return;
 f.querySelectorAll('.pp-seg, .pp-tabs, .pp-helper-tabs, .pp-tabbar, .pp-chat-tabs').forEach(el => {
  const on = el.querySelector('button.on, .pp-app.on');
  if (!on) { el.style.setProperty('--i-w', '0px'); return; }
  const er = el.getBoundingClientRect(), or_ = on.getBoundingClientRect();
  el.style.setProperty('--i-x', (or_.left - er.left) + 'px');
  el.style.setProperty('--i-w', or_.width + 'px');
 });
}
let ppLgObserver = null;
function ppLgWatch() {
 const f = document.getElementById('pp-frame');
 if (!f || ppLgObserver) return;
 ppLgObserver = new MutationObserver(() => { clearTimeout(ppLgWatch._t); ppLgWatch._t = setTimeout(ppLgSyncPills, 30); });
 ppLgObserver.observe(f, { childList: true, subtree: true, attributes: true, attributeFilter: ['class'] });
 window.addEventListener('resize', () => ppLgSyncPills());
}


function ppEnterStApp() {
 const cfg = getCfg();
 cfg.stAppMode = true;
 saveCfg();
 try {
  const d = document.getElementById('pp-dialog');
  if (d && d.open) { try { d.close(); } catch {} d.removeAttribute('open'); }
 } catch {}
 ppStHomeBtn(true);
 try { toastr.info('กดปุ่มวงกลมมุมล่างขวาเพื่อกลับมือถือ'); } catch {}
}
function ppExitStApp() {
 const cfg = getCfg();
 cfg.stAppMode = false;
 saveCfg();
 ppStHomeBtn(false);
 ppNav('home');
 ppOpen();
}
/** ปุ่มกลับบ้าน ลอยอยู่ตอนอยู่ในโหมดแอพ */
function ppStHomeBtn(show) {
 let b = document.getElementById('pp-sthome');
 if (!show) { if (b) b.remove(); return; }
 if (b) return;
 b = document.createElement('button');
 b.id = 'pp-sthome';
 b.title = 'กลับมือถือ';
 b.innerHTML = `<span class="pp-sthome-bar"></span>`;
 // ลากย้ายได้ เผื่อไปบังปุ่มของ SillyTavern
 let pid = null, sx = 0, sy = 0, ox = 0, oy = 0, moved = false;
 const pos = getCfg().stHomePos || { x: 0, y: 0 };
 b.style.transform = `translate(${pos.x}px, ${pos.y}px)`;
 b.addEventListener('pointerdown', e => {
  if (pid !== null) return;
  pid = e.pointerId; moved = false;
  sx = e.clientX; sy = e.clientY;
  const p2 = getCfg().stHomePos || { x: 0, y: 0 };
  ox = p2.x; oy = p2.y;
  try { b.setPointerCapture(pid); } catch {}
 });
 b.addEventListener('pointermove', e => {
  if (e.pointerId !== pid) return;
  const dx = e.clientX - sx, dy = e.clientY - sy;
  if (!moved && Math.abs(dx) + Math.abs(dy) > 6) moved = true;
  if (!moved) return;
  e.preventDefault();
  const cfg2 = getCfg();
  cfg2.stHomePos = { x: ox + dx, y: oy + dy };
  b.style.transform = `translate(${cfg2.stHomePos.x}px, ${cfg2.stHomePos.y}px)`;
 });
 b.addEventListener('pointerup', e => {
  if (e.pointerId !== pid) return;
  try { b.releasePointerCapture(pid); } catch {}
  pid = null;
  if (moved) saveCfg(); else ppExitStApp();
 });
 b.addEventListener('pointercancel', () => { pid = null; });
 document.body.appendChild(b);
}

function ppClose() {
 const dlg = document.getElementById('pp-dialog');
 if (!dlg) return;
 ppAudioStop(true); // ★ 2.14.1 ปิดมือถือแล้วเพลงเล่นต่อ เสียงอื่นหยุด
 try { document.activeElement?.blur(); } catch {}
 if (dlg.open && typeof dlg.close === 'function') dlg.close();
 else dlg.removeAttribute('open');
 islandRefresh();
}
/** ★ 2.36.0 อนิเมชันเปิดแอพ ให้รู้สึกว่ากำลังเปิดจริง ไม่ใช่สลับทันที */
function ppAppOpenAnim(screen) {
 try {
  if (screen === 'home' || ppCurrentScreen === screen) return;
  const el = document.getElementById('pp-scr-' + screen) || (screen === 'home' ? document.getElementById('pp-home') : null);
  if (!el) return;
  el.classList.remove('pp-anim-in', 'pp-anim-back');
  void el.offsetWidth;   // บังคับให้เริ่มอนิเมชันใหม่ ไม่งั้นเปิดซ้ำจะไม่เล่น
  el.classList.add(ppCurrentScreen === 'home' ? 'pp-anim-in' : 'pp-anim-back');
  setTimeout(() => el.classList.remove('pp-anim-in', 'pp-anim-back'), 340);
 } catch {}
}

