// ══════════════════════════════════════════════════════════
// ★ 1.6.0 PROFILE VIEW — หน้าโปรไฟล์แบบ IG สองแท็บ
// แท็บกริด: สามคอลัมน์ กดเข้าโพสต์ · แท็บไทม์ไลน์: ไล่ประวัติทั้งหมด
// ══════════════════════════════════════════════════════════
let ppProfViewId = null;      // null = โปรไฟล์ผู้ใช้
let ppProfViewTab = 'grid';   // grid | timeline
let ppProfViewFrom = 'feed';  // กลับไปหน้าไหน

/** ข้อมูลโปรไฟล์ของเจ้าของรายนี้
 * ★ 2.5.0 'user' คือบัญชีที่ใช้อยู่ · 'acc:xxx' คือบัญชีเจาะจง */
function ppProfileOf(id) {
 const cfg = getCfg();
 if (!id || id === 'user' || String(id).startsWith('acc:')) {
  const accId = (!id || id === 'user') ? ppActiveAccountId() : String(id).slice(4);
  const a = ppFindAccount(accId);
  // ★ 2.7.0 บัญชีของ NPC ไม่ใช่บัญชีของผู้ใช้ อย่าเหมารวม
  const owner = a ? (a.owner || 'user') : 'user';
  if (owner !== 'user') {
   const hostC = findContact(owner);
   return {
    id: 'acc:' + a.id, accId: a.id, isUser: false, contact: hostC, altOf: owner,
    name: ppAccName(a.id), handle: ppAccHandle(a.id),
    bio: a.bio || '', link: a.link || '',
    avatar: a.avatar || '', cover: a.cover || '',
    locked: !!a.locked,
    secret: Array.isArray(a.knownBy) && !a.knownBy.length,
   };
  }
  const isMain = !a || a.id === 'main';
  return {
   id: isMain ? 'user' : 'acc:' + a.id,
   accId: a ? a.id : 'main',
   isUser: true,
   name: ppAccName(a ? a.id : 'main'),
   handle: ppAccHandle(a ? a.id : 'main'),
   bio: a ? (a.bio || (isMain ? (cfg.userBio || '') : '')) : (cfg.userBio || ''),
   link: a ? (a.link || (isMain ? (cfg.userLink || '') : '')) : (cfg.userLink || ''),
   avatar: ppAccAvatar(a ? a.id : 'main'),
   cover: a ? (a.cover || '') : (cfg.userCover || ''),
   locked: a ? !!a.locked : !!cfg.accountLocked,
   secret: !!(a && a.id !== 'main' && Array.isArray(a.knownBy) && !a.knownBy.length),
  };
 }
 const c = findContact(id);
 if (!c) return null;
 return {
  id: c.id, isUser: false, contact: c,
  name: dname(c), handle: c.handle || dname(c).replace(/\s+/g, '').toLowerCase(),
  bio: c.bio || '', link: c.link || '',
  avatar: c.avatar || '', cover: c.cover || '',
  locked: false,
 };
}
/** โพสต์ของเจ้าของรายนี้ เรียงใหม่ก่อน
 * ★ 2.5.0 id 'user' หมายถึงบัญชีที่ใช้อยู่ ไม่ใช่ทุกบัญชีรวมกัน */
function ppProfilePosts(id) {
 let owner;
 if (!id || id === 'user') owner = ppAuthorKey(ppActiveAccountId());
 else if (String(id).startsWith('acc:')) owner = id;
 else owner = id;
 return getFeedPosts()
  .filter(p => p.author === owner && p.kind !== 'news' && !isPostArchived(p.id))
  .slice().sort((a, b) => (b.ts || 0) - (a.ts || 0));
}
function ppPostHasMedia(p) {
 if (!p) return false;
 if (postMediaKeys(p).length) return true;
 return !!(p.mediaUrls && p.mediaUrls.length);
}
/** รวมสื่อของโพสต์เป็นรายการเดียว — ทั้งลิงก์และของติดเครื่อง */
function ppPostMediaList(p) {
 const out = [];
 if (p && Array.isArray(p.mediaUrls)) {
  p.mediaUrls.forEach((u, i) => {
   const url = String(u || '').trim();
   if (!url) return;
   out.push({ src: url, remote: true, kind: ppGuessMediaKind(url), caption: (p.captions || [])[i] || '' });
  });
 }
 postMediaKeys(p).forEach((k, i) => {
  out.push({ mediaKey: k, remote: false, kind: 'image', caption: (p.captions || [])[out.length] || '' });
 });
 return out;
}
/** ★ 2.8.1 กล่องพิมพ์ที่มีปุ่มแท็กติดมาด้วย — ใช้แทน ppPrompt ได้ทุกที่
 * ตัวเลือกแท็กจะลอยขึ้นมาทับกล่องนี้ กดเลือกแล้วแทรกให้ที่ตำแหน่งเคอร์เซอร์
 * กล่องเดิมยังอยู่ ไม่ปิดตัวเอง จึงพิมพ์ต่อได้เลย */
function ppPromptWithTag(title, initial, onOk, opts) {
 const o = opts || {};
 const ov = ppOverlay('center', `<div class="pp-dlg">
  <div class="pp-dlg-title">${esc(title)}</div>
  ${o.hint ? `<div class="pp-hint" style="margin:0 0 8px">${esc(o.hint)}</div>` : ''}
  <textarea class="pp-input-line pp-pt-in" rows="${o.rows || 3}" placeholder="${esc(o.placeholder || '')}">${esc(initial || '')}</textarea>
  <div class="pp-btn-row" style="margin:8px 0 0">
  <button class="pp-btn pp-pt-tag">${ICON.at} แท็กคน</button>
  </div>
  <div class="pp-dlg-row">
  <button class="pp-btn pp-pt-no">ยกเลิก</button>
  <button class="pp-btn primary pp-pt-yes">${esc(o.okLabel || 'บันทึก')}</button>
  </div>
 </div>`);
 const ta = ov.querySelector('.pp-pt-in');
 setTimeout(() => ta?.focus(), 60);
 ov.querySelector('.pp-pt-tag')?.addEventListener('click', e => {
  e.stopPropagation();
  ppTagPicker(h => ppInsertAtCursor(ta, '@' + h));
 });
 ov.querySelector('.pp-pt-no')?.addEventListener('click', () => ov.remove());
 ov.querySelector('.pp-pt-yes')?.addEventListener('click', () => {
  const v = (ta.value || '').trim();
  ov.remove();
  onOk(v);
 });
}
/** ★ 2.8.0 เลือกคนที่จะแท็ก แล้วแทรก @handle ให้ */
function ppTagPicker(onPick) {
 const list = ppMentionTargets();
 if (!list.length) { ppToast('ยังไม่มีใครให้แท็ก'); return; }
 const sub = t => t.kind === 'me' ? 'บัญชีของคุณ'
  : t.kind === 'alt' ? 'แอครองของ ' + cname(t.ownerId)
  : t.kind === 'npc' ? 'NPC' : 'ตัวละคร';
 const rowHTML = t => `<button class="pp-ms-row pp-ms-compact" data-tagpick="${esc(t.handle)}" data-tagname="${esc((t.label + ' ' + t.handle).toLowerCase())}">
  ${avHTML(t.avatar, t.label[0], 30)}
  <span style="flex:1;min-width:0;display:flex;flex-direction:column;gap:1px">
  <span style="font-size:13.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(t.label)}</span>
  <span style="font-size:10px;color:var(--pp-txt3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">@${esc(t.handle)} · ${esc(sub(t))}</span>
  </span></button>`;
 const ov = ppOverlay('bottom', `<div class="pp-sheet">
  <div class="pp-sheet-grab"></div>
  <div class="pp-sheet-head"><span class="pp-sheet-title">แท็กใคร</span>
  <span style="font-size:11px;color:var(--pp-txt3)">${list.length} บัญชี</span></div>
  ${list.length > 6 ? `<div class="pp-pickbar"><span class="ic">${ICON.search}</span>
  <input class="pp-tag-search" placeholder="ค้นหาชื่อ หรือ @"></div>` : ''}
  <div class="pp-sheet-body">${list.map(rowHTML).join('')}</div>
  <button class="pp-sheet-cancel">ยกเลิก</button>
 </div>`);
 const sheet = ov.querySelector('.pp-sheet');
 if (sheet) sheet.addEventListener('click', ev => ev.stopPropagation());
 ov.querySelectorAll('[data-tagpick]').forEach(b => b.addEventListener('click', ev => {
  ev.preventDefault(); ev.stopPropagation();
  const h = b.dataset.tagpick;
  ov.remove();
  setTimeout(() => onPick(h), 50);
 }));
 const sIn = ov.querySelector('.pp-tag-search');
 if (sIn) {
  sIn.addEventListener('click', ev => ev.stopPropagation());
  sIn.addEventListener('input', () => {
   const q = sIn.value.trim().toLowerCase().replace(/^@/, '');
   ov.querySelectorAll('[data-tagpick]').forEach(b => {
    b.style.display = (!q || (b.dataset.tagname || '').includes(q)) ? '' : 'none';
   });
  });
 }
 ov.querySelector('.pp-sheet-cancel')?.addEventListener('click', ev => { ev.stopPropagation(); ov.remove(); });
}
/** ★ 2.8.0 ป้ายสถานะล็อกข้างชื่อ */
function ppLockBadge(id) {
 if (!ppIsLocked(id)) return '';
 if (ppIsApproved(id)) return `<span class="pp-lockstate open">${ICON.unlock}เปิดให้คุณ</span>`;
 if (ppLockPending(id)) return `<span class="pp-lockstate pending">${ICON.clock}รอเขาตอบ</span>`;
 return `<span class="pp-lockstate locked">${ICON.lock}ส่วนตัว</span>`;
}
/** หน้าล็อกที่แทนกริดกับไทม์ไลน์ */
function ppLockPanelHTML(prof) {
 const o = ppLockState(prof.id) || {};
 const pend = ppLockPending(prof.id);
 return `<div class="pp-lockpanel">${ICON.lock}
 <b>บัญชีนี้เป็นส่วนตัว</b>
 <p>${esc(o.lockNote || `${prof.name} ยังไม่เปิดให้คุณเห็นโพสต์`)}<br><br>
 กดขอติดตาม แล้วไปคุยกับเขาในโรล เขาตัดสินใจเองว่าจะเปิดให้หรือไม่ ปฏิเสธก็ได้</p>
 ${pend
  ? `<button class="pp-btn wide" style="opacity:.6">ส่งคำขอแล้ว · รอเขาตัดสินใจในโรล</button>`
  : `<button class="pp-btn primary wide" data-lockreq="${esc(prof.id)}">${ICON.person} ขอติดตาม</button>`}
 </div>`;
}
/** แผ่นตั้งค่าบัญชีส่วนตัว */
function ppLockEditSheet(id) {
 const o = ppLockState(id);
 if (!o) return;
 const nm = ppLockName(id);
 const redraw = () => {
  if (ppCurrentScreen === 'profbuild') renderProfileBuilder();
  if (ppCurrentScreen === 'profview') renderProfileView();
 };
 const reopen = () => setTimeout(() => ppLockEditSheet(id), 80);
 ppSheet(`บัญชีส่วนตัวของ ${nm}`, [
  { label: o.locked ? 'เปิดเป็นสาธารณะ' : 'ตั้งเป็นบัญชีส่วนตัว', icon: o.locked ? ICON.unlock : ICON.lock, onClick: () => {
    if (o.locked) {
     ppSetLock(id, false);
     ppToast('เปิดสาธารณะแล้ว');
     redraw(); reopen();
     return;
    }
    ppPrompt('เหตุผลที่เขาล็อกไว้', o.lockNote || '', v => {
     ppSetLock(id, true, v);
     const o2 = ppLockState(id);
     if (o2) { o2.approved = false; o2.reqPending = false; saveCfg(); }
     redraw();
     ppAlert('ล็อกแล้ว',
      `โพสต์ของ ${esc(nm)} จะถูกซ่อนจากคุณ<br><br>
       เข้าโปรไฟล์เขาแล้วกดขอติดตาม จากนั้นไปคุยในโรล เขาตัดสินใจเองว่าจะเปิดให้หรือไม่<br><br>
       ข้อความเหตุผลที่ใส่จะโชว์บนหน้าล็อก และส่งเข้าโรลให้เขารู้ว่าตัวเองล็อกไว้เพราะอะไร`);
    }, { rows: 2, hint: 'เช่น ไม่อยากให้คนอื่นเห็นชีวิตส่วนตัว หรือ เพิ่งทะเลาะกับใครมา · เว้นว่างได้' });
   } },
  o.locked ? { label: o.approved ? 'ปิดไม่ให้คุณเห็นอีก' : 'เปิดให้คุณเห็นเลย (ข้ามการโรล)', icon: ICON.eye, onClick: () => {
    ppApproveLock(id, !o.approved);
    ppToast(o.approved ? 'ปิดแล้ว' : 'เปิดให้แล้ว');
    redraw(); reopen();
   } } : null,
  o.locked ? { label: 'แก้เหตุผลที่ล็อก', icon: ICON.compose, onClick: () => ppPrompt('เหตุผล', o.lockNote || '', v => {
    o.lockNote = String(v || '').slice(0, 160); saveCfg(); redraw(); reopen();
   }, { rows: 2 }) } : null,
  o.locked && o.reqPending ? { label: 'ยกเลิกคำขอที่ค้างอยู่', icon: ICON.close, onClick: () => {
    o.reqPending = false; saveCfg(); redraw(); ppToast('ยกเลิกคำขอแล้ว'); reopen();
   } } : null,
 ].filter(Boolean));
}
/** ★ 2.7.0 แผ่นตั้งค่า NPC — คีย์เวิร์ด บัญชี ความสัมพันธ์ อยู่ที่เดียว */
function ppNpcSettingsSheet(cid) {
 const c = findContact(cid);
 if (!c) return;
 ppNpcFlags(c);
 const host = ppParentCharOf(cid);
 const hostName = host ? cname(host) : 'ตัวละครหลัก';
 const accs = ppAccountsOf(cid);
 const kw = ppNpcKwWords(c);
 const reopen = () => setTimeout(() => ppNpcSettingsSheet(cid), 80);
 ppSheet(`ตั้งค่า ${dname(c)}`, [
  { label: `คีย์เวิร์ด · ${kw.length} คำ`, icon: ICON.search, onClick: () => ppNpcKwEdit(cid, reopen) },
  { label: `บัญชีของเขา · ${accs.length + 1} อัน`, icon: ICON.users, onClick: () => ppNpcAccountsSheet(cid) },
  { label: `${c.folHost ? '✓' : '✗'} เขาติดตาม ${hostName}`, icon: ICON.person, onClick: () => {
    const v = ppToggleNpcFlag(cid, 'folHost');
    ppToast(v ? `${dname(c)} ตาม ${hostName} แล้ว` : `เอาออกจากผู้ติดตามของ ${hostName}`);
    if (ppCurrentScreen === 'profview') renderProfileView();
    if (ppCurrentScreen === 'profbuild') renderProfileBuilder();
    reopen();
   } },
  { label: `${c.hostFol ? '✓' : '✗'} ${hostName} ติดตามเขา`, icon: ICON.person, onClick: () => {
    const v = ppToggleNpcFlag(cid, 'hostFol');
    ppToast(v ? `${hostName} ตาม ${dname(c)} แล้ว` : `${hostName} เลิกตาม ${dname(c)}`);
    if (ppCurrentScreen === 'profview') renderProfileView();
    if (ppCurrentScreen === 'profbuild') renderProfileBuilder();
    reopen();
   } },
  { label: `${c.folUser ? '✓' : '✗'} เขาติดตามคุณ`, icon: ICON.heart, onClick: () => {
    const v = ppToggleNpcFlag(cid, 'folUser');
    ppToast(v ? `${dname(c)} ตามคุณแล้ว` : `${dname(c)} เลิกตามคุณ`);
    ppRefreshAllViews();
    reopen();
   } },
  { label: 'ปั้นโปรไฟล์เขา', icon: ICON.compose, onClick: () => ppBuildOpen(cid, ppCurrentScreen) },
  { label: 'ดูโปรไฟล์เขา', icon: ICON.eye, onClick: () => { ppPushRoute(ppCurrentScreen); ppProfileOpen(cid, ppCurrentScreen); } },
  { label: 'ทักแชท', icon: ICON.messages, onClick: () => { ppAudioStop(); ppActiveContact = c; ppActiveGroup = null; ppNav('chat'); } },
 ]);
}
/** แก้คีย์เวิร์ดของ NPC — เรียกได้จากทุกที่ */
function ppNpcKwEdit(cid, done) {
 const c = findContact(cid);
 if (!c) return;
 const auto = [dname(c), c.handle].filter(Boolean).join(', ');
 ppPrompt(`คีย์เวิร์ดเพิ่มของ ${dname(c)}`, c.kwWords || '', v => {
  c.kwWords = (v || '').trim().slice(0, 200);
  saveCfg();
  ppToast(c.kwWords ? 'บันทึกคีย์เวิร์ดแล้ว' : 'ใช้แต่ชื่อเป็นคำค้น');
  if (ppCurrentScreen === 'npckw') renderNpcKwPage();
  if (ppCurrentScreen === 'profbuild') renderProfileBuilder();
  if (done) done();
 }, { rows: 2, hint: `ระบบใช้ "${auto || dname(c)}" เป็นคำค้นให้อยู่แล้ว ตรงนี้ใส่ชื่อเล่น ฉายา หรือคำที่คนในเรื่องเรียกเขา คั่นด้วยจุลภาค\n\nเวลาโรลแล้วมีใครเอ่ยคำเหล่านี้ ตัวละครจะรู้ว่าเขาเป็นใคร มีรูปและโปรไฟล์แบบไหน (ต้องเปิดสวิตช์โปรไฟล์ NPC ในตั้งค่า สะพานเชื่อม)\n\nค่านี้ติดไปกับการ์ดตอนกดฝัง คนที่รับการ์ดไปได้คำค้นชุดเดียวกัน ไม่ต้องตั้งใหม่` });
}
/** ★ 2.7.0 บัญชีหลายอันของ NPC หนึ่งคน */
function ppNpcAccountsSheet(cid) {
 const c = findContact(cid);
 if (!c) return;
 const accs = ppAccountsOf(cid);
 const reopen = () => setTimeout(() => ppNpcAccountsSheet(cid), 80);
 const items = [
  { label: `${dname(c)} · บัญชีหลัก${c.handle ? ' @' + c.handle : ''}`, icon: ICON.person,
    onClick: () => { ppPushRoute(ppCurrentScreen); ppProfileOpen(cid, ppCurrentScreen); } },
 ];
 accs.forEach(a => items.push({
  label: `${ppAccName(a.id)} · @${ppAccHandle(a.id)} · ${ppProfilePosts('acc:' + a.id).length} โพสต์`,
  icon: ICON.at,
  onClick: () => ppNpcAccountEdit(cid, a.id, reopen),
 }));
 items.push({ label: 'สร้างบัญชีให้เขาอีกอัน', icon: ICON.plus, onClick: () => {
  ppPrompt(`ชื่อบัญชีใหม่ของ ${dname(c)}`, '', name => {
   name = (name || '').trim();
   if (!name) return;
   const a = ppCreateAccount(cid, name);
   ppPrompt('ชื่อแอค (ไม่ต้องใส่ @)', '', h => {
    a.handle = (h || '').trim().replace(/^@/, '').slice(0, 40);
    saveCfg();
    ppPrompt('คีย์เวิร์ดของบัญชีนี้', '', k => {
     a.kwWords = (k || '').trim().slice(0, 200);
     saveCfg();
     ppLog('account', `สร้างบัญชีรอง "${name}" ให้ ${dname(c)}`);
     ppAlert('สร้างบัญชีแล้ว',
      `${esc(name)} · @${esc(ppAccHandle(a.id))}<br><br>
       บัญชีนี้มีคลังโพสต์และไฮไลท์ของตัวเอง แยกจากบัญชีหลักของ ${esc(dname(c))}<br><br>
       คีย์เวิร์ดที่ใส่จะทำให้ตัวละครในโรลรู้ว่าแอคนี้คือแอคไหน`);
     reopen();
    }, { rows: 2, hint: 'เช่น แอคหลุม แอครูปอาหาร แอคด่า · คั่นด้วยจุลภาค เว้นว่างได้' });
   }, { rows: 1 });
  }, { rows: 1, hint: 'NPC หนึ่งคนมีได้หลายบัญชี เหมือนคนจริงที่มีแอคหลักกับแอครอง' });
 } });
 ppSheet(`บัญชีของ ${dname(c)}`, items);
}
function ppNpcAccountEdit(cid, accId, done) {
 const a = ppFindAccount(accId);
 const c = findContact(cid);
 if (!a || !c) return;
 const back = () => { if (done) done(); };
 ppSheet(`@${ppAccHandle(a.id)}`, [
  { label: 'ดูโปรไฟล์บัญชีนี้', icon: ICON.eye, onClick: () => {
    ppPushRoute(ppCurrentScreen);
    ppProfileOpen('acc:' + a.id, ppCurrentScreen);
   } },
  { label: 'ชื่อที่แสดง', icon: ICON.compose, onClick: () => ppPrompt('ชื่อที่แสดง', a.name || '', v => {
    a.name = (v || '').trim().slice(0, 60); saveCfg(); ppToast('บันทึกแล้ว'); back();
   }, { rows: 1 }) },
  { label: 'ชื่อแอค', icon: ICON.at, onClick: () => ppPrompt('ชื่อแอค (ไม่ต้องใส่ @)', a.handle || '', v => {
    a.handle = (v || '').trim().replace(/^@/, '').slice(0, 40); saveCfg(); ppToast('บันทึกแล้ว'); back();
   }, { rows: 1 }) },
  { label: `คีย์เวิร์ด${a.kwWords ? ' · มีแล้ว' : ' · ยังไม่มี'}`, icon: ICON.search, onClick: () => ppPrompt(`คีย์เวิร์ดของ @${ppAccHandle(a.id)}`, a.kwWords || '', v => {
    a.kwWords = (v || '').trim().slice(0, 200); saveCfg(); ppToast('บันทึกแล้ว'); back();
   }, { rows: 2, hint: 'คำที่ทำให้ตัวละครในโรลรู้ว่าแอคนี้คือแอคไหน · คั่นด้วยจุลภาค' }) },
 { label: 'bio', icon: ICON.compose, onClick: () => ppPromptWithTag('bio', a.bio || '', v => {
   a.bio = (v || '').trim().slice(0, 300); saveCfg(); back();
  }, { rows: 3, hint: 'แอครองมัก bio สั้นและแท็กแอคหลักของตัวเอง ใส่ @ ได้เลย' }) },
  { label: 'รูปโปรไฟล์จากลิงก์', icon: ICON.image, onClick: () => ppLinkPrompt({
    title: 'ลิงก์รูปโปรไฟล์', kind: 'image', initial: a.avatar || '',
    hint: 'ต้องเป็นลิงก์ เพราะรูปจากเครื่องจะไม่ติดไปกับการ์ด',
    onOk: u => { a.avatar = u; saveCfg(); ppToast('เปลี่ยนรูปแล้ว'); back(); },
   }) },
  { label: 'ยอดผู้ติดตามที่แสดง', icon: ICON.person, onClick: () => ppPrompt('ผู้ติดตาม', String(a.followerCount || 0), v => {
    a.followerCount = Math.max(0, parseInt(String(v).replace(/[^\d]/g, ''), 10) || 0);
    saveCfg(); back();
   }, { rows: 1 }) },
  { label: 'ลบบัญชีนี้', icon: ICON.trash, danger: true, onClick: () => {
    const n = ppProfilePosts('acc:' + a.id).length;
    ppConfirm('ลบบัญชีรอง', `ลบ @${ppAccHandle(a.id)} และโพสต์ ${n} อัน? กู้คืนไม่ได้`, () => {
     const cfg2 = getCfg();
     const key = 'acc:' + a.id;
     cfg2.feedPosts = cfg2.feedPosts.filter(p => p.author !== key);
     cfg2.stories = (cfg2.stories || []).filter(s => s.author !== key);
     cfg2.accounts = ppAccounts().filter(x => x.id !== a.id);
     saveCfg();
     ppRefreshAllViews();
     ppToast('ลบบัญชีแล้ว');
     back();
    }, 'ลบ');
   } },
 ]);
}
/** ★ 2.6.0 แผ่นวงคนรู้จัก — NPC ที่ผูกกับตัวละครนี้
 * filter: 'all' | 'followers' | 'following' */
function ppOpenNpcCircle(charId, filter) {
 const host = findContact(charId);
 if (!host) return;
 const all = ppLinkedNpcs(charId);
 if (!all.length) { ppToast(`${dname(host)} ยังไม่มีคนใกล้ตัวที่มีบัญชี`); return; }
 const mode = filter === 'followers' ? 'followers' : filter === 'following' ? 'following' : 'all';
 const list = mode === 'followers' ? ppNpcFollowersOf(charId)
  : mode === 'following' ? ppNpcFollowingOf(charId) : all;
 const title = mode === 'followers' ? `ผู้ติดตามของ ${dname(host)}`
  : mode === 'following' ? `${dname(host)} กำลังติดตาม` : `คนใกล้ตัวของ ${dname(host)}`;
 const rowHTML = n => {
  ppNpcFlags(n);
  const posts = ppProfilePosts(n.id).length;
  const alt = ppAccountsOf(n.id).length;
  const kwOn = ppNpcKwWords(n).length > 1;
  return `<div class="pp-circrow">
  ${contactAvatarHTML(n, 34)}
  <span class="pp-circmeta" data-circopen="${esc(n.id)}">
  <span class="pp-circname">${esc(dname(n))}</span>
  <span class="pp-circsub">${n.handle ? '@' + esc(n.handle) : 'ยังไม่มีชื่อแอค'}${posts ? ` · ${fmtCount(posts)} โพสต์` : ''}${alt ? ` · อีก ${alt} บัญชี` : ''} · ${esc(ppNpcRelLabel(n))}</span>
  </span>
  <span class="pp-npckwtag${kwOn ? '' : ' off'}">${kwOn ? 'มีคำค้น' : 'ไม่มีคำค้น'}</span>
  <span class="pp-circbtns">
  <button data-circset="${esc(n.id)}" title="ตั้งค่า">${ICON.gear}</button>
  <button data-circchat="${esc(n.id)}" title="ทักแชท">${ICON.messages}</button>
  </span>
  </div>`;
 };
 const ov = ppOverlay('bottom', `<div class="pp-sheet">
  <div class="pp-sheet-grab"></div>
  <div class="pp-sheet-head"><span class="pp-sheet-title">${esc(title)}</span>
  <span style="font-size:11px;color:var(--pp-txt3)">${list.length} คน</span></div>
  <div class="pp-seg" style="margin:0 16px 8px">
  <button data-circtab="all"${mode === 'all' ? ' class="on"' : ''}>ทั้งหมด ${all.length}</button>
  <button data-circtab="followers"${mode === 'followers' ? ' class="on"' : ''}>ผู้ติดตาม ${ppNpcFollowersOf(charId).length}</button>
  <button data-circtab="following"${mode === 'following' ? ' class="on"' : ''}>ติดตามอยู่ ${ppNpcFollowingOf(charId).length}</button>
  </div>
  ${all.length > 6 ? `<div class="pp-pickbar"><span class="ic">${ICON.search}</span>
  <input class="pp-circ-search" placeholder="ค้นหาชื่อ"></div>` : ''}
  <div class="pp-sheet-body">${list.length ? list.map(rowHTML).join('') : `<div class="pp-empty">${ICON.users}<br>ไม่มีใครในหมวดนี้<span>แตะป้ายสีข้างชื่อในแท็บทั้งหมดเพื่อกำหนดทิศทาง</span></div>`}</div>
  <button class="pp-sheet-cancel">ปิด</button>
 </div>`);
 const sheet = ov.querySelector('.pp-sheet');
 if (sheet) sheet.addEventListener('click', ev => ev.stopPropagation());
 ov.querySelectorAll('[data-circtab]').forEach(b => b.addEventListener('click', ev => {
  ev.stopPropagation();
  const nx = b.dataset.circtab;
  ov.remove();
  setTimeout(() => ppOpenNpcCircle(charId, nx), 60);
 }));
 ov.querySelectorAll('[data-circopen]').forEach(b => b.addEventListener('click', ev => {
  ev.stopPropagation();
  const id2 = b.dataset.circopen;
  ov.remove();
  setTimeout(() => { ppPushRoute('profview'); ppProfileOpen(id2, 'profview'); }, 60);
 }));
 ov.querySelectorAll('[data-circchat]').forEach(b => b.addEventListener('click', ev => {
  ev.stopPropagation();
  const c2 = findContact(b.dataset.circchat);
  ov.remove();
  if (c2) setTimeout(() => { ppAudioStop(); ppActiveContact = c2; ppActiveGroup = null; ppNav('chat'); }, 60);
 }));
 // ★ 2.7.0 เฟืองเปิดแผ่นตั้งค่าเต็ม แทนป้ายสลับสามค่าเดิม
 ov.querySelectorAll('[data-circset]').forEach(b => b.addEventListener('click', ev => {
  ev.stopPropagation();
  const id2 = b.dataset.circset;
  ov.remove();
  setTimeout(() => ppNpcSettingsSheet(id2), 80);
 }));
 const sIn = ov.querySelector('.pp-circ-search');
 if (sIn) {
  sIn.addEventListener('click', ev => ev.stopPropagation());
  sIn.addEventListener('input', () => {
   const q = sIn.value.trim().toLowerCase();
   ov.querySelectorAll('.pp-circrow').forEach(r => {
    const nm = (r.querySelector('.pp-circname')?.textContent || '').toLowerCase();
    r.style.display = (!q || nm.includes(q)) ? '' : 'none';
   });
  });
 }
 ov.querySelector('.pp-sheet-cancel')?.addEventListener('click', ev => { ev.stopPropagation(); ov.remove(); });
}
/** ★ 2.7.0 คำสั่งขอคอมเมนต์ — จำนวนตามความดัง และรับคนแปลกหน้าได้ */
function ppInlineCmtInstruction(authorName, pool, authorId) {
 const cfg = getCfg();
 if (cfg.postCommentsInline === false) return null;
 const max = ppFameCmtCount(authorId);
 const names = (pool || []).map(dname);
 const strangers = cfg.cmtAllowStrangers !== false;
 if (!names.length && !strangers) return null;
 const fame = ppShownFollowers(authorId);
 return [
  ``,
  `AFTER the post line, write ${max === 1 ? 'exactly 1 comment' : `1-${max} comments`} under it.`,
  names.length ? `People who know ${authorName} and may comment: ${names.join(', ')}` : null,
  strangers
   ? `${authorName} has about ${fame} followers, so strangers see this post too. Some comments may come from strangers — invent short Thai internet nicknames for them yourself. Anyone not in the list above is treated as a stranger, which is fine.`
   : `Only use names from the list above. Never invent a name.`,
  `Each comment on its own line, format EXACTLY: [CMT CommenterName|N] "comment text"`,
  `N = a small realistic like count. Keep comments SHORT, like real people typing on a phone.`,
  `Different commenters must sound different. ${authorName} never comments on their own post.`,
 ].filter(Boolean).join('\n');
}
/** แกะ [CMT ชื่อ|N] "..." ของโพสต์เดียว — ★ 2.7.0 ชื่อที่ไม่รู้จักกลายเป็นคนแปลกหน้า */
function ppParseInlineComments(raw, post, pool) {
 if (!post) return 0;
 const cfgC = getCfg();
 if (cfgC.postCommentsInline === false) return 0;
 pool = pool || [];
 const allowGhost = cfgC.cmtAllowStrangers !== false;
 if (!pool.length && !allowGhost) return 0;
 if (!post.comments) post.comments = [];
 const cap = ppFameCmtCount(post.author);
 const rx = /^[ \t]*\[CMT\s+([^\|\]>]+?)\s*\|?\s*(\d*)\s*\]\s*(.+)$/gim;
 let m, n = 0;
 const seen = new Set();
 while ((m = rx.exec(String(raw || '')))) {
  if (n >= cap) break;
  const nm = m[1].trim();
  const likes = parseInt(m[2] || '0', 10) || 0;
  const c = pool.find(x => dname(x) === nm)
   || pool.find(x => nm && (nm.includes(dname(x)) || dname(x).includes(nm)));
  if (c && c.id === post.author) continue;
  if (!c && !allowGhost) continue;
  const q = extractSpoken(m[3]);
  const text = q.length ? q[0]
   : stripEmoji(cleanReply(m[3]).replace(/^["'“”‘’„«»「」『』]+|["'“”‘’„«»「」『』]+$/g, '')).trim();
  if (!text || looksLikeThought(text)) continue;
  const who = c ? c.id : 'ghost:' + nm;
  const key = who + '|' + text.slice(0, 40);
  if (seen.has(key)) continue;
  seen.add(key);
  post.comments.push(c
   ? { id: newId(), author: c.id, text, ts: Date.now() + n * 1200, likes: [], extraLikes: likes, parentId: null }
   : { id: newId(), author: who, authorName: nm, handle: nm, ghost: true, text,
       ts: Date.now() + n * 1200, likes: [], extraLikes: likes, parentId: null });
  post.views = post.views || {};
  post.views[who] = Date.now();
  if (c) pushNotif(c.id, 'comment', `${dname(c)} คอมเมนต์: ${text.slice(0, 40)}`);
  else ghostRememberName(nm);
  n++;
 }
 return n;
}
/** แกะ [CMT เจ้าของโพสต์ > คนคอมเมนต์|N] "..." ของชุดหลายโพสต์ */
function ppParseBatchComments(raw, postMap, pool) {
 if (getCfg().postCommentsInline === false) return 0;
 if (!postMap || !pool || !pool.length) return 0;
 const keys = Object.keys(postMap);
 const rx = /^[ \t]*\[CMT\s+([^>\]]+?)\s*>\s*([^\|\]]+?)\s*\|?\s*(\d*)\s*\]\s*(.+)$/gim;
 let m, n = 0;
 while ((m = rx.exec(String(raw || '')))) {
  const ownerName = m[1].trim();
  const cmtName = m[2].trim();
  const likes = parseInt(m[3] || '0', 10) || 0;
  const key = keys.find(k => k === ownerName)
   || keys.find(k => ownerName.includes(k) || k.includes(ownerName));
  const post = key ? postMap[key] : null;
  if (!post) continue;
  const c = pool.find(x => dname(x) === cmtName)
   || pool.find(x => cmtName && (cmtName.includes(dname(x)) || dname(x).includes(cmtName)));
  const allowGhost2 = getCfg().cmtAllowStrangers !== false;
  if (c && c.id === post.author) continue;
  if (!c && !allowGhost2) continue;
  const q = extractSpoken(m[4]);
  const text = q.length ? q[0]
   : stripEmoji(cleanReply(m[4]).replace(/^["'“”‘’„«»「」『』]+|["'“”‘’„«»「」『』]+$/g, '')).trim();
  if (!text || looksLikeThought(text)) continue;
  if (!post.comments) post.comments = [];
  const who2 = c ? c.id : 'ghost:' + cmtName;
  post.comments.push(c
   ? { id: newId(), author: c.id, text, ts: Date.now() + n * 1200, likes: [], extraLikes: likes, parentId: null }
   : { id: newId(), author: who2, authorName: cmtName, handle: cmtName, ghost: true, text,
       ts: Date.now() + n * 1200, likes: [], extraLikes: likes, parentId: null });
  post.views = post.views || {};
  post.views[who2] = Date.now();
  if (c) pushNotif(c.id, 'comment', `${dname(c)} คอมเมนต์: ${text.slice(0, 40)}`);
  else ghostRememberName(cmtName);
  n++;
 }
 return n;
}
function ppProfileOpen(id, from) {
 // ★ 1.7.1 จำชั้นที่มาจากจริง แทนการเซ็ตค่าเดียวที่ทับกันเอง
 ppPushRoute(from || ppCurrentScreen || 'feed');
 ppProfViewId = (!id || id === 'user') ? null : id;
 ppProfViewFrom = from || 'feed';
 ppProfViewTab = getCfg().profileTabMode || 'grid';
 ppNav('profview');
}
// ══════════════════════════════════════════════════════════
// ★ 1.7.0 PROFILE BUILDER — ปั้นโปรไฟล์ครบชุดต่อตัวละคร
// ทั้งของตัวเองและ NPC ที่ผูกไว้ · เขียนลงการ์ดได้ · ไม่กินโทเคน
// ══════════════════════════════════════════════════════════
let ppBuildId = null;      // contact id ที่กำลังปั้น
let ppBuildFrom = 'feed';
let ppQbDraft = null;      // ร่างโพสต์ย้อนหลัง
// ★ 1.7.1 จำเส้นทางเป็นชั้น — กัน profview กับ profbuild ส่งกันไปกลับไม่จบ
let ppNavStack = [];
function ppPushRoute(screen) {
 const last = ppNavStack[ppNavStack.length - 1];
 if (last === screen) return;           // กันชั้นซ้ำตัวเอง
 ppNavStack.push(screen);
 if (ppNavStack.length > 8) ppNavStack.shift();
}
/** ถอยหนึ่งชั้น — ถ้าไม่มีชั้นเหลือให้ตกกลับ fallback */
function ppPopRoute(fallback) {
 while (ppNavStack.length) {
  const prev = ppNavStack.pop();
  if (prev && prev !== ppCurrentScreen) return prev;
 }
 return fallback || 'feed';
}
function ppClearRoute() { ppNavStack = []; }

function ppBuildOpen(cid, from) {
 // ★ 1.7.1 จำชั้นที่มาจากจริง
 ppPushRoute(from || ppCurrentScreen || 'feed');
 ppBuildId = cid;
 ppBuildFrom = from || 'profview';
 ppNav('profbuild');
}
function ppGhosts() {
 const cfg = getCfg();
 if (!Array.isArray(cfg.ghostAccounts)) cfg.ghostAccounts = [];
 return cfg.ghostAccounts;
}
function ppFindGhost(id) { return ppGhosts().find(g => g.id === id) || null; }
/** NPC ที่ผูกกับตัวละครนี้ */
function ppLinkedNpcs(charId) {
 return getContacts().filter(c => c.npc && (c.baseCharId === charId || c.ownerCharId === charId));
}
/** ★ 2.7.0 ความสัมพันธ์ของ NPC ที่ผูกไว้ — สามสวิตช์อิสระ
 * folHost  = NPC ติดตามตัวละครหลักที่ผูกไว้
 * hostFol  = ตัวละครหลักติดตาม NPC
 * folUser  = NPC ติดตามผู้ใช้ */
function ppNpcFlags(c) {
 if (!c) return { folHost: true, hostFol: true, folUser: false };
 // ย้ายค่าจากรุ่น 2.6.0 ที่เก็บเป็นสามค่าในช่องเดียว
 if (c.followDir !== undefined && c.folHost === undefined) {
  const d = c.followDir;
  c.folHost = d !== 'followed';
  c.hostFol = d !== 'follows';
  delete c.followDir;
  saveCfg();
 }
 let dirty = false;
 if (c.folHost === undefined) { c.folHost = true; dirty = true; }
 if (c.hostFol === undefined) { c.hostFol = true; dirty = true; }
 if (c.folUser === undefined) { c.folUser = false; dirty = true; }
 if (dirty) saveCfg();
 return c;
}
function ppNpcRelLabel(c) {
 ppNpcFlags(c);
 const bits = [];
 if (c.folHost && c.hostFol) bits.push('ติดตามกัน');
 else if (c.folHost) bits.push('ตามเขา');
 else if (c.hostFol) bits.push('เขาตาม');
 else bits.push('ไม่ตามกัน');
 if (c.folUser) bits.push('ตามคุณ');
 return bits.join(' · ');
}
function ppToggleNpcFlag(cid, key) {
 const c = findContact(cid);
 if (!c) return false;
 ppNpcFlags(c);
 c[key] = !c[key];
 saveCfg();
 return c[key];
}
/** NPC ที่นับเป็นผู้ติดตามของตัวละครหลัก */
function ppNpcFollowersOf(charId) {
 return ppLinkedNpcs(charId).filter(c => { ppNpcFlags(c); return c.folHost === true; });
}
/** NPC ที่ตัวละครหลักตามอยู่ */
function ppNpcFollowingOf(charId) {
 return ppLinkedNpcs(charId).filter(c => { ppNpcFlags(c); return c.hostFol === true; });
}
/** NPC ทั้งระบบที่ติดตามผู้ใช้ */
function ppNpcFollowUserCount() {
 return getContacts().filter(c => c.npc && (ppNpcFlags(c), c.folUser === true)).length;
}
/** ★ 2.7.0 ยอดผู้ติดตามที่แสดงบนโปรไฟล์ตัวละคร */
function ppShownFollowers(cid) {
 const c = findContact(cid);
 return ((c && c.followerCount) || 0) + ppNpcFollowersOf(cid).length;
}
// ══════════════════════════════════════════════════════════
// ★ 2.8.4 DM GUARD — กันข้อความที่ไม่ได้ส่งถึงผู้ใช้เด้งเข้ามือถือ
// อาการเดิม โมเดลเขียนว่าตัวละคร A ส่งข้อความให้ B แต่ระบบอ่านแค่ช่องคนส่ง
// ไม่มีที่ไหนถามว่าส่งถึงใคร จึงเปิดห้องแชทกับผู้ใช้ทุกครั้ง
// รุ่นนี้อ่านช่องปลายทาง ถ้าไม่ใช่ผู้ใช้จะไม่เด้งเข้าห้องแชท
// แต่ไม่ทิ้งทั้งดุ้น เก็บเป็นเรื่องที่ได้ยินมาแทน โรลจะยังรู้ว่าเกิดอะไรขึ้น
// ══════════════════════════════════════════════════════════
/** ชื่อที่นับว่าเป็นผู้ใช้ ทุกบัญชีทุกชื่อเล่นที่ตัวละครตั้งให้ */
function ppUserAliases() {
 const out = [];
 const push = s => {
  const t = String(s || '').trim().toLowerCase().replace(/^@/, '');
  if (t && t.length >= 2 && !out.includes(t)) out.push(t);
 };
 push(getUserName());
 push(getUserDisplayName());
 push(getUserHandle());
 try { ppAccountsOf('user').forEach(a => { push(ppAccName(a.id)); push(ppAccHandle(a.id)); }); } catch {}
 getContacts().forEach(c => { if (c.userNickname) push(c.userNickname); });
 ['user', 'you', 'me', 'ผู้ใช้', 'คุณ', 'เธอ'].forEach(push);
 return out;
}
/** ปลายทางที่โมเดลระบุมา คืนสตริงว่างถ้าไม่ได้ระบุ */
function ppDmTargetRaw(ev) {
 if (!ev || typeof ev !== 'object') return '';
 const keys = ['to', 'target', 'recipient', 'toName', 'to_name', 'receiver', 'addressee', 'audience', 'forWho', 'sentTo', 'sent_to'];
 for (const k of keys) {
  const v = ev[k];
  if (v == null) continue;
  const s = Array.isArray(v) ? v.join(' ') : String(v);
  if (s.trim()) return s.trim();
 }
 return '';
}
/** ข้อความนี้ถึงผู้ใช้ไหม
 * คืน { ok, reason, target } — ok คือให้เด้งเข้ามือถือได้ */
function ppDmToUser(ev, senderName) {
 const cfg = getCfg();
 const mode = cfg.dmGuardMode || 'normal';
 if (mode === 'off') return { ok: true, reason: 'ปิดตัวคัดกรอง', target: '' };
 const raw = ppDmTargetRaw(ev);
 // ไม่ระบุปลายทาง — ระดับกลางปล่อยผ่าน ระดับเข้มตีกลับ
 if (!raw) {
  return mode === 'strict'
   ? { ok: false, reason: 'ไม่ได้ระบุว่าส่งถึงใคร', target: '' }
   : { ok: true, reason: 'ไม่ได้ระบุปลายทาง ถือว่าถึงผู้ใช้', target: '' };
 }
 const low = raw.toLowerCase().replace(/^@/, '');
 // ตรงกับชื่อผู้ใช้หรือชื่อเล่นที่ตัวละครตั้งไว้
 const aliases = ppUserAliases();
 if (aliases.some(a => low === a || low.includes(a) || a.includes(low))) {
  return { ok: true, reason: 'ปลายทางคือผู้ใช้', target: raw };
 }
 // ตรงกับคอนแทกต์คนอื่น แปลว่าคุยกันเอง
 const other = getContacts().find(c => {
  const dn = dname(c).toLowerCase();
  const h = String(c.handle || '').toLowerCase();
  return dn === low || (dn.length >= 3 && (low.includes(dn) || dn.includes(low))) || (h && h === low);
 });
 if (other) {
  const sn = String(senderName || '').toLowerCase();
  if (sn && dname(other).toLowerCase() === sn) {
   return { ok: true, reason: 'ปลายทางเป็นคนเดียวกับคนส่ง ถือว่าเพี้ยน ปล่อยผ่าน', target: raw };
  }
  return { ok: false, reason: `ส่งถึง ${dname(other)} ไม่ใช่คุณ`, target: dname(other) };
 }
 // ระบุมาแต่ไม่รู้จัก
 return mode === 'strict'
  ? { ok: false, reason: `ส่งถึง "${raw.slice(0, 30)}" ซึ่งไม่ใช่คุณ`, target: raw }
  : { ok: true, reason: 'ปลายทางไม่รู้จัก ถือว่าถึงผู้ใช้', target: raw };
}
/** เก็บข้อความที่ถูกตีกลับไว้เล่าให้โรลรู้ว่าเป็นเรื่องที่ได้ยินมา */
function ppDmBounce(senderName, targetName, lines, kindLabel) {
 const cfg = getCfg();
 const who = senderName || 'ใครคนหนึ่ง';
 const to = targetName || 'คนอื่น';
 const body = (Array.isArray(lines) ? lines : [lines]).filter(Boolean).map(String);
 console.info('[pocket-phone] ตีกลับข้อความที่ไม่ได้ส่งถึงผู้ใช้', { who, to, kindLabel });
 if (cfg.dmGuardLog !== false) {
  ppLogBot('chat', `${who} ${kindLabel || 'ส่งข้อความ'}ถึง ${to} ไม่ได้ส่งถึง ${getUserDisplayName()}`,
   body.length ? body.slice(0, 4).map(t => `"${t.slice(0, 120)}"`) : null);
 }
 if (cfg.dmGuardNotice !== false) {
  ppToast(`${who} คุยกับ ${to} ไม่ใช่คุณ · ไม่เด้งเข้ามือถือ`);
 }
 return { ok: true, label: `${who} คุยกับ ${to} (ไม่เข้ามือถือ)`, bounced: true };
}
/** ★ 2.7.0 คนที่มีสิทธิ์คอมเมนต์โพสต์ของ authorId
 * NPC ที่ผูกกับเขามาก่อน แล้วค่อยคอนแทกต์อื่น */
function ppCmtPoolFor(authorId, limit) {
 const cap = Math.max(1, Math.min(40, limit || getCfg().cmtPoolLimit || 14));
 const own = ppLinkedNpcs(authorId).filter(c => !isBlocked(c.id));
 const ownIds = new Set(own.map(c => c.id));
 let rest = getContacts().filter(c => !isBlocked(c.id) && c.id !== authorId && !ownIds.has(c.id));
 if (ppScopeActive()) rest = rest.filter(c => ppContactInScope(c));
 return own.concat(rest).slice(0, cap);
}
/** ★ 2.7.0 จำนวนคอมเมนต์ที่ควรได้ — ยิ่งดังยิ่งเยอะ */
function ppFameCmtCount(authorId) {
 const cfg = getCfg();
 if (cfg.cmtCountMode === 'fixed') return Math.max(1, Math.min(6, cfg.postCommentsMax || 3));
 const f = ppShownFollowers(authorId);
 if (f < 50) return 1;
 if (f < 300) return 2;
 if (f < 2000) return 3;
 if (f < 20000) return 4;
 if (f < 200000) return 5;
 return 6;
}
/** ตัวละครนี้เป็นตัวหลักของ ST ไหม (ไม่ใช่ NPC) */
function ppIsStChar(cid) {
 return ppFindStCharIndex(cid) >= 0;
}
/** ตัวการ์ดแม่ของ NPC ตัวนี้ */
function ppParentCharOf(cid) {
 const c = findContact(cid);
 if (!c) return null;
 return c.baseCharId || c.ownerCharId || null;
}
/** charId ที่ใช้เก็บรหัสล็อกและเขียนการ์ด */
function ppLockOwnerOf(cid) {
 return ppIsStChar(cid) ? cid : (ppParentCharOf(cid) || cid);
}
