 bub_b: 'data:image/png;base64,',
 bub_rainbow: 'data:image/png;base64,',
 bub_dark: 'data:image/png;base64,',
 bub_pop: 'data:image/png;base64,',
 mouse_gray: 'data:image/png;base64,',
 mouse_gold: 'data:image/png;base64,',
 bomb: 'data:image/png;base64,',
 hole: 'data:image/png;base64,',
 scene_pond: 'data:image/jpeg;base64,',
