function ppUnreadVersions() {
 const cfg = getCfg();
 const seen = Array.isArray(cfg.seenVersions) ? cfg.seenVersions : [];
 // [2.39.0] ผู้ใช้ใหม่ (seenVersions ว่างเปล่า) ให้ถือว่าอ่านทุกรุ่นแล้วยกเว้นรุ่นปัจจุบัน
 // กันป้ายแดงขึ้นเลข 100 ตั้งแต่เปิดแอพครั้งแรก
 if (seen.length === 0) return PP_CHANGELOG.filter(c => c.v === PP_VERSION);
 return PP_CHANGELOG.filter(c => !seen.includes(c.v));
}
function ppMarkVersionSeen(v) {
 const cfg = getCfg();
 if (!Array.isArray(cfg.seenVersions)) cfg.seenVersions = [];
 if (!cfg.seenVersions.includes(v)) { cfg.seenVersions.push(v); saveCfg(); }
}

/* ══════════════════════════════════════════════════════════
 * [2.39.0] แอพนาฬิกา — เวลาโลก ปลุก จับเวลา นับถอยหลัง
 * ══════════════════════════════════════════════════════════ */
const PP_TZ_CITIES = [
 { name: 'กรุงเทพฯ', off: 7 }, { name: 'โตเกียว', off: 9 }, { name: 'โซล', off: 9 },
 { name: 'ลอนดอน', off: 0 }, { name: 'ปารีส', off: 1 }, { name: 'นิวยอร์ก', off: -5 },
 { name: 'ลอสแอนเจลิส', off: -8 }, { name: 'ซิดนีย์', off: 10 }, { name: 'ดูไบ', off: 4 },
 { name: 'สิงคโปร์', off: 8 }, { name: 'ปักกิ่ง', off: 8 }, { name: 'มอสโก', off: 3 },
];
function ppClockCfg() {
 const cfg = getCfg();
 if (!cfg.clockApp || typeof cfg.clockApp !== 'object') cfg.clockApp = {};
 const c = cfg.clockApp;
 if (!Array.isArray(c.cities)) c.cities = ['กรุงเทพฯ', 'โตเกียว', 'ลอนดอน'];
 if (!Array.isArray(c.alarms)) c.alarms = [];
 if (!c.tab) c.tab = 'world';
 return c;
}
let ppSwState = { running: false, startTs: 0, elapsed: 0, laps: [] };
let ppCdState = { running: false, endTs: 0, totalMs: 0, mins: 5, secs: 0 };
let ppClockAppTimer = null;
function renderClockApp() {
 const c = ppClockCfg();
 const body = document.getElementById('pp-clock-body');
 if (!body) return;
 const tabs = [['world', 'เวลาโลก'], ['alarms', 'ปลุก'], ['stopwatch', 'จับเวลา'], ['countdown', 'ถอยหลัง']];
 const tabsEl = document.getElementById('pp-clock-tabs');
 if (tabsEl) tabsEl.innerHTML = tabs.map(([k, l]) => `<button class="${c.tab === k ? 'on' : ''}" data-clocktab="${k}">${esc(l)}</button>`).join('');
 if (c.tab === 'world') body.innerHTML = ppClockWorldHTML(c);
 else if (c.tab === 'alarms') body.innerHTML = ppClockAlarmsHTML(c);
 else if (c.tab === 'stopwatch') body.innerHTML = ppClockStopwatchHTML();
 else body.innerHTML = ppClockCountdownHTML();
 clearInterval(ppClockAppTimer);
 ppClockAppTimer = setInterval(ppClockTick, 1000);
}
function ppTzNow(off) {
 const now = new Date();
 const utcMs = now.getTime() + now.getTimezoneOffset() * 60000;
 return fmtHM(new Date(utcMs + off * 3600000));
}
function ppClockTick() {
 if (ppCurrentScreen !== 'clock') { clearInterval(ppClockAppTimer); return; }
 const c = ppClockCfg();
 if (c.tab === 'world') document.querySelectorAll('[data-tzclock]').forEach(el => { el.textContent = ppTzNow(+el.dataset.tzoff); });
 else if (c.tab === 'stopwatch' && ppSwState.running) ppSwRenderTime();
 else if (c.tab === 'countdown' && ppCdState.running) ppCdTick();
 if (new Date().getSeconds() === 0) ppClockCheckAlarms();
}
function ppClockWorldHTML(c) {
 return `<div class="pp-sec-label">เมืองของฉัน</div>
 <div class="pp-card">${c.cities.map(name => {
  const city = PP_TZ_CITIES.find(x => x.name === name) || { name, off: 7 };
  const diff = city.off - 7;
  return `<div class="pp-cell">
   <span class="pp-cell-lb" style="flex-direction:column;align-items:flex-start;gap:1px">
    <b>${esc(city.name)}</b><span style="font-size:11px;color:var(--pp-txt3)">${diff === 0 ? 'เวลาเดียวกับกรุงเทพฯ' : (diff > 0 ? `เร็วกว่า ${diff} ชม.` : `ช้ากว่า ${Math.abs(diff)} ชม.`)}</span>
   </span>
   <span class="pp-clock-tz-time" data-tzclock data-tzoff="${city.off}">${ppTzNow(city.off)}</span>
   <button class="pp-clock-tz-del" data-tzdel="${esc(city.name)}">${ICON.trash}</button>
  </div>`;
 }).join('') || `<div class="pp-nc-empty">ยังไม่มีเมือง</div>`}</div>
 <div class="pp-sec-label">เพิ่มเมือง</div>
 <div class="pp-poschips">${PP_TZ_CITIES.filter(x => !c.cities.includes(x.name)).map(x => `<button class="pp-poschip" data-tzadd="${esc(x.name)}">${esc(x.name)}</button>`).join('') || '<span class="pp-hint">เพิ่มครบทุกเมืองแล้ว</span>'}</div>`;
}
function ppClockAlarmsHTML(c) {
 return `<div class="pp-card">${c.alarms.length ? c.alarms.map(a => `<div class="pp-cell">
  <span class="pp-cell-lb" style="flex-direction:column;align-items:flex-start;gap:1px">
   <b style="font-size:22px;font-weight:300">${esc(a.time)}</b>
   <span style="font-size:11px;color:var(--pp-txt3)">${esc(a.label || 'ปลุก')}${a.days && a.days.length ? ' · ' + a.days.map(d => ['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'][d]).join(' ') : ' · ครั้งเดียว'}</span>
  </span>
  <label class="pp-switch"><input type="checkbox" data-alarmtoggle="${esc(a.id)}"${a.on ? ' checked' : ''}><span></span></label>
  <button class="pp-clock-tz-del" data-alarmdel="${esc(a.id)}">${ICON.trash}</button>
 </div>`).join('') : `<div class="pp-nc-empty">ยังไม่มีปลุก</div>`}</div>
 <button class="pp-btn primary wide" id="pp-alarm-add-btn">${ICON.plus} เพิ่มปลุก</button>`;
}
function ppClockStopwatchHTML() {
 return `<div class="pp-clock-sw-wrap">
  <div class="pp-clock-sw-time" id="pp-sw-time">${ppSwFmt(ppSwState.elapsed)}</div>
  <div class="pp-clock-sw-btns">
   <button class="pp-btn wide" id="pp-sw-lap">${ppSwState.running ? 'รอบ' : 'ล้าง'}</button>
   <button class="pp-btn primary wide" id="pp-sw-startstop">${ppSwState.running ? 'หยุด' : 'เริ่ม'}</button>
  </div>
  <div class="pp-card" id="pp-sw-laps">${ppSwState.laps.slice().reverse().map((l, i) => `<div class="pp-cell"><span class="pp-cell-lb">รอบ ${ppSwState.laps.length - i}</span><span class="pp-cell-val">${ppSwFmt(l)}</span></div>`).join('') || ''}</div>
 </div>`;
}
function ppSwFmt(ms) {
 const cs = Math.floor(ms / 10) % 100, s = Math.floor(ms / 1000) % 60, m = Math.floor(ms / 60000);
 return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(cs).padStart(2, '0')}`;
}
function ppSwRenderTime() {
 const el = document.getElementById('pp-sw-time');
 if (el) el.textContent = ppSwFmt(ppSwState.elapsed + (ppSwState.running ? Date.now() - ppSwState.startTs : 0));
}
function ppClockCountdownHTML() {
 const c = ppCdState;
 const remain = c.running ? Math.max(0, c.endTs - Date.now()) : c.totalMs || (c.mins * 60000 + c.secs * 1000);
 const pct = c.totalMs ? Math.max(0, Math.min(1, remain / c.totalMs)) : 1;
 return `<div class="pp-clock-cd-wrap">
  <div class="pp-clock-cd-ring" style="--pct:${pct}">
   <span>${ppCdFmt(remain)}</span>
  </div>
  ${!c.running ? `<div class="pp-clock-cd-set">
   <input class="pp-num" type="number" min="0" max="180" value="${c.mins}" id="pp-cd-mins"> นาที
   <input class="pp-num" type="number" min="0" max="59" value="${c.secs}" id="pp-cd-secs"> วินาที
  </div>` : ''}
  <button class="pp-btn primary wide" id="pp-cd-startstop">${c.running ? 'ยกเลิก' : 'เริ่มนับถอยหลัง'}</button>
 </div>`;
}
function ppCdFmt(ms) {
 const s = Math.ceil(ms / 1000);
 return `${String(Math.floor(s / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`;
}
function ppCdTick() {
 const remain = ppCdState.endTs - Date.now();
 if (remain <= 0) {
  ppCdState.running = false;
  islandStatus('หมดเวลาแล้ว');
  setTimeout(islandCollapse, 4000);
  ppToast('ถอยหลังครบเวลาแล้ว');
  renderClockApp();
  return;
 }
 const ring = document.querySelector('.pp-clock-cd-ring');
 if (ring) { ring.style.setProperty('--pct', String(remain / ppCdState.totalMs)); ring.querySelector('span').textContent = ppCdFmt(remain); }
 islandStatus('ถอยหลัง ' + ppCdFmt(remain));
}
function ppClockCheckAlarms() {
 const c = ppClockCfg();
 const now = new Date();
 const hm = fmtHM(now);
 const day = now.getDay();
 c.alarms.forEach(a => {
  if (!a.on) return;
  if (a.time !== hm) return;
  if (a.days && a.days.length && !a.days.includes(day)) return;
  if (a._firedAt === hm) return;
  a._firedAt = hm;
  ppRingAlarm(a);
 });
}
function ppRingAlarm(a) {
 islandStatus((a.label || 'ปลุก') + ' · ' + a.time);
 const ov = ppOverlay('center', `<div class="pp-dlg pp-clock-ring-dlg">
  <div class="pp-clock-ring-ic">${ICON.bell}</div>
  <div class="pp-dlg-title">${esc(a.label || 'ได้เวลาแล้ว')}</div>
  <div class="pp-dlg-body">${esc(a.time)}</div>
  <div class="pp-dlg-row"><button class="pp-btn wide" id="pp-alarm-snooze">เลื่อน 5 นาที</button>
  <button class="pp-btn primary wide" id="pp-alarm-stop">ปิด</button></div>
 </div>`);
 ov.querySelector('#pp-alarm-stop')?.addEventListener('click', () => { ov.remove(); islandCollapse(); });
 ov.querySelector('#pp-alarm-snooze')?.addEventListener('click', () => {
  ov.remove(); islandCollapse();
  const t = new Date(Date.now() + 5 * 60000);
  a._firedAt = null;
  const snoozed = Object.assign({}, a, { id: newId(), time: fmtHM(t), days: [], label: (a.label || 'ปลุก') + ' (เลื่อน)' });
  ppClockCfg().alarms.push(snoozed);
  saveCfg();
  ppToast('เลื่อนไป 5 นาที');
 });
}

/* ══════════════════════════════════════════════════════════
 * [2.39.0] แอพเครื่องคิดเลข
 * ══════════════════════════════════════════════════════════ */
let ppCalc = { cur: '0', prev: null, op: null, reset: false, hist: [] };
function renderCalcApp() {
 const grid = document.getElementById('pp-calc-grid');
 if (!grid) return;
 const keys = [['AC', '±', '%', '÷'], ['7', '8', '9', '×'], ['4', '5', '6', '−'], ['1', '2', '3', '+'], ['0', '.', '=']];
 grid.innerHTML = keys.map(row => `<div class="pp-calc-row">${row.map(k => {
  const wide = k === '0';
  const isOp = ['÷', '×', '−', '+', '='].includes(k);
  const isFn = ['AC', '±', '%'].includes(k);
  return `<button class="pp-calc-key${isOp ? ' op' : ''}${isFn ? ' fn' : ''}${wide ? ' wide' : ''}" data-calc="${esc(k)}">${esc(k)}</button>`;
 }).join('')}</div>`).join('');
 ppCalcRenderDisplay();
}
function ppCalcRenderDisplay() {
 const d = document.getElementById('pp-calc-display');
 if (d) { d.textContent = ppCalc.cur; d.classList.toggle('shrink', ppCalc.cur.replace('-', '').length > 8); }
 const h = document.getElementById('pp-calc-hist');
 if (h) h.textContent = ppCalc.hist.length ? ppCalc.hist[ppCalc.hist.length - 1] : '';
}
function fmtCalcNum(n) { return Number.isFinite(n) ? (Math.abs(n) >= 1e12 ? n.toExponential(4) : String(n)) : '0'; }
function ppCalcOp(k, btn) {
 const c = ppCalc;
 if (btn) { btn.classList.add('press'); setTimeout(() => btn.classList.remove('press'), 150); }
 if (k === 'AC') { c.cur = '0'; c.prev = null; c.op = null; c.reset = false; }
 else if (k === '±') { c.cur = String(parseFloat(c.cur || '0') * -1); }
 else if (k === '%') { c.cur = String(parseFloat(c.cur || '0') / 100); }
 else if (['÷', '×', '−', '+'].includes(k)) {
  if (c.op && !c.reset) ppCalcEquals();
  c.prev = parseFloat(c.cur); c.op = k; c.reset = true;
 } else if (k === '=') { ppCalcEquals(); }
 else if (k === '.') { if (c.reset) { c.cur = '0.'; c.reset = false; } else if (!c.cur.includes('.')) c.cur += '.'; }
 else { if (c.reset || c.cur === '0') { c.cur = k; c.reset = false; } else if (c.cur.replace('-', '').replace('.', '').length < 12) c.cur += k; }
 ppCalcRenderDisplay();
}
function ppCalcEquals() {
 const c = ppCalc;
 if (c.op == null || c.prev == null) return;
 const b = parseFloat(c.cur);
 let r = c.prev;
 if (c.op === '+') r = c.prev + b; else if (c.op === '−') r = c.prev - b;
 else if (c.op === '×') r = c.prev * b; else if (c.op === '÷') r = b === 0 ? NaN : c.prev / b;
 r = Math.round(r * 1e9) / 1e9;
 c.hist.push(`${fmtCalcNum(c.prev)} ${c.op} ${fmtCalcNum(b)} = ${fmtCalcNum(r)}`);
 if (c.hist.length > 20) c.hist.shift();
 c.cur = isNaN(r) ? 'Error' : String(r);
 c.op = null; c.prev = null; c.reset = true;
}

/* ══════════════════════════════════════════════════════════
 * [2.39.0] แอพโน้ต
 * ══════════════════════════════════════════════════════════ */
function ppNotesData() {
 const cfg = getCfg();
 if (!Array.isArray(cfg.notesApp)) cfg.notesApp = [];
 return cfg.notesApp;
}
let ppNotesFilter = '';
function renderNotesApp() {
 const body = document.getElementById('pp-notes-body');
 if (!body) return;
 const q = ppNotesFilter.trim().toLowerCase();
 let list = ppNotesData().slice().sort((a, b) => (b.pinned - a.pinned) || (b.ts - a.ts));
 if (q) list = list.filter(n => (n.title || '').toLowerCase().includes(q) || (n.body || '').toLowerCase().includes(q));
 body.innerHTML = list.length ? list.map(n => `<div class="pp-card pp-note-card tap" data-noteopen="${esc(n.id)}">
  <div class="pp-note-row">
   <span class="pp-note-title">${n.pinned ? ICON.pin + ' ' : ''}${esc(n.title || 'ไม่มีชื่อ')}</span>
   <span class="pp-note-age">${esc(fmtNoteAge(n.ts))}</span>
  </div>
  <div class="pp-note-preview">${esc((n.body || '').slice(0, 80))}</div>
 </div>`).join('') : `<div class="pp-nc-empty">${q ? 'ไม่พบโน้ตที่ค้นหา' : 'ยังไม่มีโน้ต แตะปุ่มบวกเพื่อเริ่มเขียน'}</div>`;
}
function ppNoteOpen(id) {
 const n = id ? ppNotesData().find(x => x.id === id) : null;
 const ov = ppOverlay('bottom', `<div class="pp-sheet pp-note-editor">
  <div class="pp-sheet-grab"></div>
  <input class="pp-input-line" id="pp-note-title" placeholder="หัวเรื่อง" value="${esc(n ? n.title || '' : '')}">
  <textarea class="pp-input-line" id="pp-note-body" rows="8" placeholder="เขียนอะไรก็ได้…">${esc(n ? n.body || '' : '')}</textarea>
  <div class="pp-sheet-acts">
   ${n ? `<button class="pp-sheet-act" id="pp-note-pin">${n.pinned ? 'เลิกปักหมุด' : 'ปักหมุด'}</button>
   <button class="pp-sheet-act" id="pp-note-share">แชร์เข้าแชท</button>
   <button class="pp-sheet-act danger" id="pp-note-del">ลบโน้ต</button>` : ''}
  </div>
  <button class="pp-btn primary wide" id="pp-note-save">บันทึก</button>
 </div>`);
 ov.querySelector('#pp-note-save')?.addEventListener('click', () => {
  const title = ov.querySelector('#pp-note-title').value.trim();
  const bodyTxt = ov.querySelector('#pp-note-body').value.trim();
  if (!title && !bodyTxt) { ppToast('ยังไม่มีข้อความ'); return; }
  const list = ppNotesData();
  if (n) { n.title = title; n.body = bodyTxt; n.ts = Date.now(); }
  else list.push({ id: newId(), title, body: bodyTxt, pinned: false, ts: Date.now() });
  saveCfg(); ov.remove(); renderNotesApp(); ppToast('บันทึกโน้ตแล้ว');
 });
 ov.querySelector('#pp-note-pin')?.addEventListener('click', () => { n.pinned = !n.pinned; saveCfg(); ov.remove(); renderNotesApp(); });
 ov.querySelector('#pp-note-del')?.addEventListener('click', () => {
  ppConfirm('ลบโน้ต', `ลบ "${n.title || 'โน้ตนี้'}" ถาวร?`, () => {
   const list = ppNotesData();
   const i = list.findIndex(x => x.id === n.id);
   if (i !== -1) list.splice(i, 1);
   saveCfg(); ov.remove(); renderNotesApp(); ppToast('ลบโน้ตแล้ว');
  });
 });
 ov.querySelector('#pp-note-share')?.addEventListener('click', () => {
  ppPickContact('แชร์โน้ตให้ใคร', cid => {
   const c = findContact(cid); if (!c) return;
   pushThreadMsg(c.id, { from: 'me', text: `[โน้ต] ${n.title || 'ไม่มีชื่อ'}\n${n.body || ''}`.slice(0, 500) });
   ppLog('note', `แชร์โน้ต "${n.title || ''}" ให้ ${dname(c)}`);
   ppToast('แชร์เข้าแชทแล้ว');
  });
 });
}

/* ══════════════════════════════════════════════════════════
 * [2.39.0] แอพสภาพอากาศ — จำลองด้วย seed จากวันและเมือง ตามฤดูไทย
 * ══════════════════════════════════════════════════════════ */
const PP_WX_CITIES = ['กรุงเทพฯ', 'เชียงใหม่', 'ภูเก็ต', 'ขอนแก่น', 'เชียงราย', 'หาดใหญ่'];
function ppWxCfg() {
 const cfg = getCfg();
 if (!cfg.weatherApp || typeof cfg.weatherApp !== 'object') cfg.weatherApp = { city: 'กรุงเทพฯ' };
 if (!cfg.weatherApp.city) cfg.weatherApp.city = 'กรุงเทพฯ';
 return cfg.weatherApp;
}
function ppWxSeedNum(str) { let h = 0; for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) >>> 0; return h; }
function ppWxRand(seed) { let t = seed + 0x6D2B79F5; t = Math.imul(t ^ t >>> 15, t | 1); t ^= t + Math.imul(t ^ t >>> 7, t | 61); return ((t ^ t >>> 14) >>> 0) / 4294967296; }
function ppWxSeasonRange(month) {
 if (month >= 2 && month <= 4) return { lo: 28, hi: 39, cond: ['แดดจัด', 'แดดจัด', 'มีเมฆบางส่วน'] };
 if (month >= 5 && month <= 9) return { lo: 24, hi: 33, cond: ['ฝนตก', 'เมฆมาก', 'ฝนฟ้าคะนอง', 'มีเมฆบางส่วน'] };
 return { lo: 18, hi: 29, cond: ['แดดจัด', 'มีเมฆบางส่วน', 'หมอกยามเช้า'] };
}
function ppWxDayData(city, dayOffset) {
 const d = new Date(); d.setDate(d.getDate() + dayOffset);
 const key = city + '-' + ppLocalDateStr(d);
 const seed = ppWxSeedNum(key);
 const r0 = ppWxRand(seed), r1 = ppWxRand(seed + 1), r2 = ppWxRand(seed + 2);
 const range = ppWxSeasonRange(d.getMonth());
 const temp = Math.round(range.lo + r0 * (range.hi - range.lo));
 const cond = range.cond[Math.floor(r1 * range.cond.length)];
 return {
  date: d, temp, lo: temp - 3 - Math.round(r1 * 3), hi: temp + 2 + Math.round(r2 * 3), cond,
  uv: Math.max(1, Math.round(r0 * 11)), humidity: Math.round(50 + r1 * 40),
  wind: Math.round(4 + r2 * 20), aqi: Math.round(20 + r0 * 130),
  sunrise: '06:' + String(Math.round(10 + r1 * 30)).padStart(2, '0'),
  sunset: '18:' + String(Math.round(10 + r2 * 30)).padStart(2, '0'), seed,
 };
}
function ppWxIcon(cond) {
 if (cond === 'แดดจัด') return ICON.sun;
 if (cond === 'ฝนตก' || cond === 'ฝนฟ้าคะนอง') return ICON.drop;
 return ICON.cloud;
}
function ppWxBgClass(cond) {
 if (cond === 'แดดจัด') return 'wx-sunny';
 if (cond === 'ฝนตก' || cond === 'ฝนฟ้าคะนอง') return 'wx-rain';
 return 'wx-cloudy';
}
function renderWeatherApp() {
 const wc = ppWxCfg();
 const scr = document.getElementById('pp-scr-weather');
 const body = document.getElementById('pp-weather-body');
 if (!body) return;
 const today = ppWxDayData(wc.city, 0);
 if (scr) { scr.classList.remove('wx-sunny', 'wx-cloudy', 'wx-rain'); scr.classList.add(ppWxBgClass(today.cond)); }
 const hours = Array.from({ length: 12 }, (_, i) => {
  const h = (new Date().getHours() + i) % 24;
  const r = ppWxRand(today.seed + h);
  return { h, temp: Math.round(today.lo + r * (today.hi - today.lo)) };
 });
 const days = Array.from({ length: 7 }, (_, i) => ppWxDayData(wc.city, i));
 const wkLo = Math.min(...days.map(d => d.lo)), wkHi = Math.max(...days.map(d => d.hi));
 const dayNames = ['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'];
 body.innerHTML = `
 <div class="pp-wx-head">
  <button class="pp-wx-city tap" id="pp-wx-city-btn">${esc(wc.city)}${ICON.chevron}</button>
  <div class="pp-wx-ic">${ppWxIcon(today.cond)}</div>
  <div class="pp-wx-temp">${today.temp}°</div>
  <div class="pp-wx-cond">${esc(today.cond)}</div>
  <div class="pp-wx-hl">สูงสุด ${today.hi}° · ต่ำสุด ${today.lo}°</div>
 </div>
 <div class="pp-sec-label">รายชั่วโมง</div>
 <div class="pp-card pp-wx-hourly">${hours.map(h => `<div class="pp-wx-hcell">
  <span>${h.h === new Date().getHours() ? 'ตอนนี้' : h.h + ':00'}</span>
  <span class="pp-wx-hic">${ppWxIcon(today.cond)}</span>
  <span>${h.temp}°</span>
 </div>`).join('')}</div>
 <div class="pp-sec-label">รายสัปดาห์</div>
 <div class="pp-card">${days.map((d, i) => {
  const left = ((d.lo - wkLo) / Math.max(1, wkHi - wkLo)) * 100;
  const width = ((d.hi - d.lo) / Math.max(1, wkHi - wkLo)) * 100;
  return `<div class="pp-cell pp-wx-drow">
   <span class="pp-wx-dname">${i === 0 ? 'วันนี้' : dayNames[d.date.getDay()]}</span>
   <span class="pp-wx-dic">${ppWxIcon(d.cond)}</span>
   <span class="pp-wx-dlo">${d.lo}°</span>
   <span class="pp-wx-dbar"><i style="left:${left}%;width:${Math.max(8, width)}%"></i></span>
   <span class="pp-wx-dhi">${d.hi}°</span>
  </div>`;
 }).join('')}</div>
 <div class="pp-sec-label">รายละเอียด</div>
 <div class="pp-wx-grid">
  <div class="pp-wx-tile"><span class="lb">UV</span><b>${today.uv}</b><span class="sub">${today.uv >= 8 ? 'สูงมาก' : today.uv >= 5 ? 'ปานกลาง' : 'ต่ำ'}</span></div>
  <div class="pp-wx-tile"><span class="lb">ความชื้น</span><b>${today.humidity}%</b></div>
  <div class="pp-wx-tile"><span class="lb">ลม</span><b>${today.wind}</b><span class="sub">กม./ชม.</span></div>
  <div class="pp-wx-tile"><span class="lb">พระอาทิตย์ขึ้น</span><b style="font-size:15px">${today.sunrise}</b></div>
  <div class="pp-wx-tile"><span class="lb">พระอาทิตย์ตก</span><b style="font-size:15px">${today.sunset}</b></div>
  <div class="pp-wx-tile"><span class="lb">AQI</span><b>${today.aqi}</b><span class="sub">${today.aqi > 100 ? 'ไม่ดี' : today.aqi > 50 ? 'ปานกลาง' : 'ดี'}</span></div>
 </div>`;
}

/* ══════════════════════════════════════════════════════════
 * [2.39.0] แอพเตือนความจำ
 * ══════════════════════════════════════════════════════════ */
function ppRemData() {
 const cfg = getCfg();
 if (!Array.isArray(cfg.remindersApp)) cfg.remindersApp = [];
 return cfg.remindersApp;
}
let ppRemFilter = 'open';
function renderRemindersApp() {
 const body = document.getElementById('pp-rem-body');
 if (!body) return;
 const all = ppRemData();
 const todayStr = ppLocalDateStr(new Date());
 const todayCount = all.filter(r => !r.done && r.due === todayStr).length;
 let list = all.slice().sort((a, b) => (a.done - b.done) || (b.flagged - a.flagged) || (a.ts - b.ts));
 if (ppRemFilter === 'open') list = list.filter(r => !r.done);
 else if (ppRemFilter === 'flagged') list = list.filter(r => r.flagged && !r.done);
 else if (ppRemFilter === 'done') list = list.filter(r => r.done);
 body.innerHTML = `
 <div class="pp-hint">วันนี้เหลือ <b>${todayCount}</b> รายการ</div>
 <div class="pp-seg" id="pp-rem-seg">
  ${[['open', 'ค้างอยู่'], ['flagged', 'ตั้งธง'], ['done', 'เสร็จแล้ว']].map(([k, l]) => `<button class="${ppRemFilter === k ? 'on' : ''}" data-remfilter="${k}">${esc(l)}</button>`).join('')}
 </div>
 <div class="pp-card" id="pp-rem-list">${list.length ? list.map(r => `<div class="pp-cell pp-rem-row" data-remid="${esc(r.id)}">
  <button class="pp-rem-ring${r.done ? ' done' : ''}" data-remdone="${esc(r.id)}"></button>
  <span class="pp-cell-lb" style="flex-direction:column;align-items:flex-start;gap:1px">
   <span style="${r.done ? 'text-decoration:line-through;opacity:.5' : ''}">${esc(r.text)}</span>
   ${r.due ? `<span style="font-size:11px;color:${r.due < todayStr && !r.done ? '#ff453a' : 'var(--pp-txt3)'}">${esc(r.due)}</span>` : ''}
  </span>
  <button class="pp-rem-flag${r.flagged ? ' on' : ''}" data-remflag="${esc(r.id)}">${ICON.flag}</button>
 </div>`).join('') : `<div class="pp-nc-empty">ไม่มีรายการ</div>`}</div>
 <button class="pp-btn primary wide" id="pp-rem-add-btn">${ICON.plus} เพิ่มรายการ</button>`;
}
function ppRemAdd(text, due) {
 ppRemData().push({ id: newId(), text, done: false, flagged: false, due: due || '', ts: Date.now() });
 saveCfg(); renderRemindersApp();
}
function ppRemToggleDone(id, rowEl) {
 const r = ppRemData().find(x => x.id === id);
 if (!r) return;
 if (!r.done) {
  const ring = rowEl && rowEl.querySelector('.pp-rem-ring');
  if (ring) ring.classList.add('filling');
  setTimeout(() => { r.done = true; saveCfg(); renderRemindersApp(); }, 420);
 } else { r.done = false; saveCfg(); renderRemindersApp(); }
}


/* ══════════════════════════════════════════════════════════════
 * [2.40.0] ระบบสัตว์เลี้ยง — แมวส้มเป็นตัวแรก
 * สไปรท์เก็บเป็นลิงก์ภายนอก ไฟล์โค้ดจึงไม่บวม
 * ผู้ใช้อัปโหลดรูปของตัวเองทับได้ทีหลัง (เก็บใน IndexedDB)
 * ══════════════════════════════════════════════════════════════ */
const PET_SPECIES = {
 'cat-orange': {
  name: 'แมวส้ม', kind: 'cat',
  sprites: {
   idle:   'data:image/png;base64,',
   happy:   'data:image/png;base64,',
   hungry:   'data:image/png;base64,',
   sleepy:   'data:image/png;base64,',
   dirty:   'data:image/png;base64,',
   sick:   'data:image/png;base64,',
   eating:   'data:image/png;base64,',
   play:   'data:image/png;base64,',
   bath:   'data:image/png;base64,',
   sleep:   'data:image/png;base64,',
   dead:   'data:image/png;base64,',
  },
 },
};
const PET_SCENE_DAY = 'data:image/jpeg;base64,';
const PET_SCENE_NIGHT = 'data:image/jpeg;base64,';

/** กล่องข้อมูลสัตว์เลี้ยง สร้างครั้งแรกแบบ lazy เหมือนส่วนอื่นในแอพ */
function ppPets() {
 const cfg = getCfg();
 if (!cfg.pets || typeof cfg.pets !== 'object') cfg.pets = { list: [], activeId: null, coins: 0 };
 if (!Array.isArray(cfg.pets.list)) cfg.pets.list = [];
 if (typeof cfg.pets.coins !== 'number') cfg.pets.coins = 0;
 return cfg.pets;
}
function ppPetActive() {
 const P = ppPets();
 return P.list.find(p => p.id === P.activeId) || P.list[0] || null;
}
function ppPetNew(species, name, sex) {
 const now = Date.now();
 return {
  id: newId(), species, name: String(name || 'น้องแมว').slice(0, 24), sex: sex || 'ไม่ระบุ',
  born: now, stage: 'baby',
  full: 80, clean: 80, fun: 80, health: 100,
  lastTick: now, poop: [], sick: false, dead: false,
  pinned: false, walkUntil: 0, walkHours: 0, meds: 3,
  act: null, actUntil: 0,      // ท่าชั่วคราว เช่น กำลังกิน/อาบน้ำ
 };
}

/* ── เดินเวลาจริง: ค่าต่าง ๆ ลดลงตามชั่วโมงที่ผ่านไป ── */
function ppPetTick(p) {
 if (!p || p.dead) return;
 const now = Date.now();
 // [2.40.0] เช็คการกลับจากเดินเล่นก่อนเสมอ — ของเดิมอยู่ใต้ if (hrs <= 0) return
 // ทำให้ถ้าแอพเพิ่งอัปเดตค่าไปหมาด ๆ น้องกลับถึงบ้านแล้วแต่ไม่ได้เงิน
 if (p.walkUntil && now >= p.walkUntil) {
  const earn = Math.round(10 * p.walkHours * (0.7 + Math.random() * 0.9));
  ppPets().coins += earn;
  p.walkUntil = 0; p.fun = Math.min(100, p.fun + 18); p.clean = Math.max(0, p.clean - 12);
  p.lastWalkEarn = earn; p.lastWalkEarnAt = now;
  ppPetLog(p, 'user', `กลับจากเดินเล่น ได้ ${fmtMoney(earn)}`);
 }
 const hrs = Math.max(0, (now - (p.lastTick || now)) / 3600000);
 if (hrs <= 0) return;
 p.lastTick = now;
 // [2.40.0] ของพรีเมียมจากร้านค้าทำให้ค่าลดช้าลงชั่วคราว (เซ็ตอาหารใหญ่ / Grooming Deluxe)
 // [ปรับให้ค่าลดช้าลง] เลี้ยงจากค่าเต็ม 100 แล้วไม่เข้ามาเลย 20 ชม. ก็ยังไม่ตาย/ไม่ป่วย
 const fullRate = (p.fullSlowUntil && now < p.fullSlowUntil) ? 0.84 : 1.68;
 const cleanRate = (p.cleanSlowUntil && now < p.cleanSlowUntil) ? 0.6 : 1.2;
 p.full  = Math.max(0, p.full  - hrs * fullRate);
 p.clean = Math.max(0, p.clean - hrs * cleanRate);
 p.fun   = Math.max(0, p.fun   - hrs * 1.44);
 // อึโผล่ราวทุก 8 ชั่วโมง เก็บได้สูงสุด 4 กอง
 const poops = Math.floor(hrs / 8);
 for (let i = 0; i < poops && p.poop.length < 4; i++) {
  p.poop.push({ id: newId(), x: 18 + Math.random() * 64, y: 62 + Math.random() * 22 });
 }
 // ปล่อยให้หิว/สกปรกนาน หรืออึกองเยอะ = สุขภาพตก แล้วป่วย
 let drain = 0;
 if (p.full < 20) drain += hrs * 3;
 if (p.clean < 20) drain += hrs * 2;
 if (p.poop.length >= 3) drain += hrs * 2;
 if (drain > 0) p.health = Math.max(0, p.health - drain);
 else if (p.full > 55 && p.clean > 55) p.health = Math.min(100, p.health + hrs * 2);
 p.sick = p.health < 35;
 if (p.health <= 0) { p.dead = true; p.act = null; }
 // โตเป็นตัวเต็มวัยหลังเลี้ยงครบ 7 วัน
 if (p.stage === 'baby' && now - p.born > 7 * 86400000) p.stage = 'adult';
}
function ppPetTickAll() {
 const P = ppPets();
 P.list.forEach(ppPetTick);
 saveCfg();
}

/** เลือกท่าที่จะแสดง เรียงตามลำดับความสำคัญ */
function ppPetPose(p) {
 if (!p) return 'idle';
 if (p.dead) return 'dead';
 if (p.act && Date.now() < p.actUntil) return p.act;   // ท่าชั่วคราวมาก่อน
 if (p.walkUntil && Date.now() < p.walkUntil) return 'sleep';
 if (p.sick) return 'sick';
 if (p.clean < 30) return 'dirty';
 if (p.full < 30) return 'hungry';
 const h = new Date().getHours();
 if (h >= 23 || h < 6) return 'sleep';
 if (h >= 21 || p.fun < 25) return 'sleepy';
 if (p.full > 70 && p.clean > 70 && p.fun > 70) return 'happy';
 return 'idle';
}
function ppPetSprite(p, pose) {
 const sp = PET_SPECIES[p.species] || PET_SPECIES['cat-orange'];
 return (sp.sprites[pose] || sp.sprites.idle);
}
function ppPetIsNight() { const h = new Date().getHours(); return h >= 19 || h < 6; }
function ppPetMoodText(p) {
 if (p.dead) return 'จากไปแล้ว';
 if (p.sick) return 'ไม่สบาย ต้องกินยา';
 if (p.walkUntil && Date.now() < p.walkUntil) return 'ออกไปเดินเล่นอยู่';
 if (p.clean < 30) return 'ตัวเลอะ อยากอาบน้ำ';
 if (p.full < 30) return 'หิวแล้วนะ';
 if (p.fun < 30) return 'เบื่อ ๆ อยากเล่น';
 if (p.full > 70 && p.clean > 70 && p.fun > 70) return 'อารมณ์ดีสุด ๆ';
 return 'สบายดี';
}

/* ── ท่าชั่วคราว: กิน อาบน้ำ เล่น ── */
function ppPetAct(p, act, secs, apply) {
 p.act = act; p.actUntil = Date.now() + secs * 1000;
 if (apply) apply(p);
 saveCfg(); renderPetApp();
 setTimeout(() => { if (ppCurrentScreen === 'pet') renderPetApp(); }, secs * 1000 + 60);
}


/* [2.40.0] ไอคอนร้านค้า + ฉากเดินเล่น/อาบน้ำ ที่ผู้ใช้วาดส่งมาเอง */
const PET_ICONS = {
 feed: 'data:image/png;base64,',
 med: 'data:image/png;base64,',
 bath: 'data:image/png;base64,',
 walk: 'data:image/png;base64,',
 sleep: 'data:image/png;base64,',
};
const PET_SCENE_WALK = 'data:image/jpeg;base64,';
const PET_SCENE_BATH = 'data:image/jpeg;base64,';

/* ── ร้านค้า — ยิ่งแพงยิ่งได้ผลเยอะ ใช้เงินในกระเป๋าเงินเดียวกับทั้งแอพ ──
 * กันกดรัว: ปุ่มถูกปิดครึ่งวินาทีหลังซื้อทุกครั้ง + ต้องมีเงินพอจริงเท่านั้น */
const PET_ICONS2 = {
'food1_kibble_pink': 'data:image/png;base64,',
'food2_wet_blue': 'data:image/png;base64,',
'food3_bones': 'data:image/png;base64,',
'food4_can': 'data:image/png;base64,',
'food5_bag': 'data:image/png;base64,',
'bath1_shower': 'data:image/png;base64,',
'bath2_tub': 'data:image/png;base64,',
'bath3_shampoo': 'data:image/png;base64,',
'bath4_towel': 'data:image/png;base64,',
'bath5_dryer': 'data:image/png;base64,',
'toy1_yarn': 'data:image/png;base64,',
'toy2_wand': 'data:image/png;base64,',
'toy3_rope': 'data:image/png;base64,',
'toy4_ball': 'data:image/png;base64,',
'toy5_laser': 'data:image/png;base64,',
};

/* [2.40.0] ร้านค้าฉบับเต็ม 3 หมวด — ราคา/ผลตามที่ออกแบบมา
 * ของเล่นเป็นหมวดใหม่: เล่นได้ตามเวลาที่กำหนด ยิ่งแพงยิ่งเล่นนานและสุขมากขึ้น
 * เซ็ตอาหารใหญ่/Grooming Deluxe ให้ "คงสภาพได้นานสุด" คือชะลอการลดค่าไปชั่วคราว */
const PET_SHOP = {
 food: [
  { id: 'kibble', name: 'อาหารเม็ด', price: 26, full: 20, icon: 'food1_kibble_pink' },
  { id: 'wet', name: 'อาหารเปียก', price: 52, full: 35, fun: 5, icon: 'food2_wet_blue' },
  { id: 'treat', name: 'ขนม/ทรีต', price: 40, full: 8, fun: 15, icon: 'food3_bones' },
  { id: 'special', name: 'อาหารพิเศษ', price: 90, full: 55, fun: 10, icon: 'food4_can' },
  { id: 'bigset', name: 'เซ็ตอาหารใหญ่', price: 135, full: 80, fun: 0, slow: 'full', icon: 'food5_bag' },
 ],
 bath: [
  { id: 'plain', name: 'อาบน้ำธรรมดา', price: 40, clean: 30, icon: 'bath1_shower' },
  { id: 'bubble', name: 'อาบน้ำฟองนุ่ม', price: 78, clean: 55, fun: 5, icon: 'bath2_tub' },
  { id: 'spa', name: 'สปาขนนุ่ม', price: 118, clean: 80, fun: 15, icon: 'bath3_shampoo' },
  { id: 'deluxe', name: 'Grooming Deluxe', price: 170, clean: 100, fun: 25, slow: 'clean', icon: 'bath5_dryer' },
 ],
 toy: [
  { id: 'ball', name: 'ลูกบอล', price: 26, fun: 15, secs: 30, icon: 'toy1_yarn' },
  { id: 'wand', name: 'ไม้ตกแมว', price: 40, fun: 20, secs: 45, icon: 'toy2_wand' },
  { id: 'rope', name: 'เชือกกัดเล่น', price: 52, fun: 25, secs: 60, icon: 'toy3_rope' },
  { id: 'laser', name: 'เลเซอร์', price: 68, fun: 30, secs: 90, icon: 'toy5_laser' },
  { id: 'playground', name: 'ของเล่นพิเศษ', price: 105, fun: 50, secs: 120, icon: 'toy4_ball' },
 ],
};

/** [2.40.0] บันทึกกิจกรรมของน้อง เก็บย้อนหลัง 30 วัน รวมทั้งที่ผู้ใช้ทำและที่พ่อ (บอท) ทำ */
function ppPetLog(p, who, text) {
 try {
  if (!p) return;
  if (!Array.isArray(p.log)) p.log = [];
  p.log.push({ ts: Date.now(), who: who || 'user', text: String(text || '').slice(0, 120) });
  const cut = Date.now() - 30 * 86400000;
  p.log = p.log.filter(x => x.ts >= cut).slice(-300);
 } catch {}
}
function ppPetOpenLog() {
 const p = ppPetActive();
 if (!p) return;
 const list = (p.log || []).slice().reverse();
 const rows = list.length ? list.map(l => `<div class="pp-plog-row">
   <span class="pp-plog-who ${l.who === 'bot' ? 'bot' : 'me'}">${l.who === 'bot' ? esc(p.fatherName || 'พ่อ') : 'ฉัน'}</span>
   <span class="pp-plog-tx">${esc(l.text)}</span>
   <span class="pp-plog-ts">${esc(fmtNoteAge(l.ts))}</span>
  </div>`).join('') : '<div class="pp-nc-empty">ยังไม่มีบันทึก</div>';
 ppOverlay('bottom', `<div class="pp-sheet pp-plog-sheet">
  <div class="pp-sheet-grab"></div>
  <div class="pp-sheet-head"><span class="pp-sheet-title">ประวัติการดูแล ${esc(p.name)}</span></div>
  <div class="pp-hint">เก็บย้อนหลัง 30 วัน · รวมทั้งที่คุณทำและที่พ่อทำ</div>
  <div class="pp-sheet-body">${rows}</div>
  <button class="pp-sheet-cancel">ปิด</button>
 </div>`);
}
function ppPetInv(p) { if (!p.inv || typeof p.inv !== 'object') p.inv = {}; return p.inv; }
function ppShopFind(kind, id) { return (PET_SHOP[kind] || []).find(x => x.id === id); }
/** [2.40.0] ซื้อ = เก็บเข้าคลังของน้อง ยังไม่ใช้ · ใช้เงินกระเป๋าของน้องเอง ไม่ปนกับกระเป๋าเงินหลัก */
function ppShopBuy(kind, itemId) {
 const P = ppPets();
 const now = Date.now();
 if (P.lastBuyAt && now - P.lastBuyAt < 700) return;
 const p = ppPetActive();
 if (!p || p.dead) { ppToast('ยังไม่มีน้องให้ซื้อของ'); return; }
 const item = ppShopFind(kind, itemId);
 if (!item) return;
 if ((P.coins || 0) < item.price) { ppToast('เงินของน้องไม่พอ'); return; }
 P.lastBuyAt = now;
 P.coins -= item.price;
 const inv = ppPetInv(p);
 const key = kind + ':' + itemId;
 inv[key] = (inv[key] || 0) + 1;
 saveCfg(); renderPetApp();
 const sh = document.getElementById('pp-shop');
 if (sh) { const t = sh.querySelector('.pp-shop-title span'); if (t) t.textContent = 'เงินของน้อง ' + fmtMoney(P.coins); }
 ppPetLog(p, 'user', `ซื้อ${item.name}`);
 ppToast(`ซื้อ${item.name}เก็บไว้แล้ว`);
}
/** ใช้ของจากคลัง — ตรงนี้ถึงจะมีผลกับน้องจริง */
function ppPetUseItem(key) {
 const p = ppPetActive();
 if (!p || p.dead) return;
 const inv = ppPetInv(p);
 if (!inv[key]) return;
 const [kind, id] = key.split(':');
 const item = ppShopFind(kind, id);
 if (!item) return;
 if (p.act && Date.now() < p.actUntil) { ppToast('น้องกำลังทำอย่างอื่นอยู่'); return; }
 inv[key]--; if (inv[key] <= 0) delete inv[key];
 const now = Date.now();
 // [2.40.0] ให้ท่าอยู่นานขึ้นเป็น 4.5 วิ ของเดิม 3 วิ เร็วเกินจนดูไม่ทัน
 const HOLD = 4.5;
 if (kind === 'food') {
  p.full = Math.min(100, p.full + (item.full || 0));
  if (item.fun) p.fun = Math.min(100, p.fun + item.fun);
  if (item.slow === 'full') p.fullSlowUntil = now + 6 * 3600000;
  ppPetAct(p, 'eating', HOLD);
 } else if (kind === 'bath') {
  p.clean = Math.min(100, p.clean + (item.clean || 0));
  p.bathCount = (p.bathCount || 0) + 1;   // [2.41.0] ใช้เป็นเงื่อนไขปลดล็อกเกมฟองสบู่
  if (item.fun) p.fun = Math.min(100, p.fun + item.fun);
  if (item.slow === 'clean') p.cleanSlowUntil = now + 6 * 3600000;
  ppPetAct(p, 'bath', HOLD);
 } else if (kind === 'toy') {
  p.fun = Math.min(100, p.fun + (item.fun || 0));
  ppPetAct(p, 'play', Math.max(HOLD, (item.secs || 30) / 8));
 }
 ppPetLog(p, 'user', `ใช้${item.name}`);
 saveCfg(); renderPetApp();
 ppToast(`ใช้${item.name}แล้ว`);
}
function ppOpenShop() {
 document.getElementById('pp-shop')?.remove();
 const cfg = getCfg();
 const fx = (it) => {
  const bits = [];
  if (it.full) bits.push('อิ่ม +' + it.full);
  if (it.clean) bits.push('สะอาด +' + it.clean);
  if (it.fun) bits.push('สุข +' + it.fun);
  if (it.secs) bits.push('เล่น ' + it.secs + ' วิ');
  if (it.slow) bits.push('อยู่ได้นานขึ้น');
  return bits.join(' · ');
 };
 const cat = (kind, label, items) => `<div class="pp-shop-cat">
  <div class="pp-shop-cat-label">${label}</div>
  <div class="pp-shop-items">${items.map(it => `<button class="pp-shop-item" data-shopbuy="${kind}:${it.id}">
   <img class="pp-shop-item-ic" src="${PET_ICONS2[it.icon]}" alt="">
   <span class="tx"><span class="nm">${esc(it.name)}</span><span class="fx">${fx(it)}</span></span>
   <span class="pr">฿${it.price}</span>
  </button>`).join('')}</div></div>`;
 const box = document.createElement('div');
 box.id = 'pp-shop';
 box.innerHTML = `<div class="pp-shop-sheet">
  <div class="pp-sheet-grab"></div>
  <div class="pp-shop-title">ร้านค้าสัตว์เลี้ยง <span>เงินของน้อง ${fmtMoney(ppPets().coins || 0)}</span></div>
  ${cat('food', 'อาหาร', PET_SHOP.food)}
  ${cat('bath', 'อาบน้ำ', PET_SHOP.bath)}
  ${cat('toy', 'ของเล่น', PET_SHOP.toy)}
 </div>`;
 const f = document.getElementById('pp-frame');
 (f || document.body).appendChild(box);
 requestAnimationFrame(() => box.classList.add('show'));
 box.addEventListener('click', ev => { if (ev.target === box) { box.classList.remove('show'); setTimeout(() => box.remove(), 220); } });
}

/* ── แชร์น้อง ── */
function ppPetShareChat(p) {
 ppPickContact('แชร์น้องให้ใครดู', cid => {
  const c = findContact(cid); if (!c) return;
  // [2.40.0] เดิมส่งเป็นข้อความ [แนะนำน้อง] ธรรมดา ไม่มี UI เลย อ่านแล้วงง
  // เปลี่ยนเป็นข้อความรูปภาพจริง เหมือนส่งรูปในแชทปกติ
  pushThreadMsg(c.id, {
   from: 'me', type: 'image', mediaUrl: ppPetSprite(p, ppPetPose(p)), mediaKey: '',
   caption: `${p.name} · ${(PET_SPECIES[p.species] || {}).name || ''} · ${ppPetMoodText(p)}`,
  });
  ppToast('แชร์เข้าแชทแล้ว');
 });
}
function ppPetShareFeed(p) {
 const doPost = (personaName) => {
  const cfg = getCfg();
  cfg.feedPosts.push({
   id: newId(), author: 'user', kind: 'post',
   text: `${p.name} ${(PET_SPECIES[p.species] || {}).name || ''} · ${ppPetMoodText(p)}`,
   mediaUrls: [ppPetSprite(p, ppPetPose(p))], mediaKeys: [], captions: [''],
   visibility: 'all', ts: Date.now(), likes: [], extraLikes: 0, comments: [], views: {}, saves: 0,
   petShare: true, petPersonaName: personaName || '',
  });
  saveCfg(); ppToast('แชร์ลงฟีดแล้ว'); if (ppCurrentScreen === 'feed') renderFeed();
 };
 const personas = listUserPersonas();
 if (personas.length) ppSheet('โพสต์ด้วยบัญชีไหน', personas.map(ps => ({ label: ps.name, onClick: () => doPost(ps.name) })));
 else doPost();
}

/* ── ตั้งพ่อของน้อง ── */
function ppPetSetFather(p) {
 // [2.40.0] ppPickContact ส่ง "ไอดี" กลับมา ไม่ใช่ตัวคอนแทกต์
 // ของเดิมรับเป็น c แล้วไปเรียก c.id กับ dname(c) เลยพังเงียบ ๆ กดแล้วไม่มีอะไรเกิดขึ้น
 ppPickContact('เลือกพ่อของน้อง', cid => {
  const c = findContact(cid);
  if (!c) { ppToast('ไม่พบคอนแทกต์นี้'); return; }
  p.fatherId = c.id; p.fatherName = dname(c);
  if (p.fatherAware === undefined) p.fatherAware = true;
  saveCfg(); renderPetApp();
  ppToast(`ตั้ง ${dname(c)} เป็นพ่อของ ${p.name} แล้ว`);
 });
}

function renderPetApp() {
 const body = document.getElementById('pp-pet-body');
 if (!body) return;
 ppPetTickAll();
 const P = ppPets();
 const p = ppPetActive();
 const scr = document.getElementById('pp-scr-pet');
 if (scr) {
  let bg = ppPetIsNight() ? PET_SCENE_NIGHT : PET_SCENE_DAY;
  if (p && p.walkUntil && Date.now() < p.walkUntil) bg = PET_SCENE_WALK;
  else if (p && p.act === 'bath' && Date.now() < p.actUntil) bg = PET_SCENE_BATH;
  scr.style.setProperty('--pet-bg', `url("${bg}")`);
 }

 if (!p) {
  body.innerHTML = `<div class="pp-pet-empty">
   <div class="pp-pet-empty-ic">${ICON.heart}</div>
   <div class="pp-pet-empty-t">ยังไม่มีสัตว์เลี้ยง</div>
   <div class="pp-pet-empty-s">รับน้องมาเลี้ยงสักตัวไหม</div>
   <button class="pp-btn primary wide" id="pp-pet-adopt">รับน้องมาเลี้ยง</button>
  </div>`;
  return;
 }
 const pose = ppPetPose(p);
 const walking = p.walkUntil && Date.now() < p.walkUntil;
 // [2.40.0] เดิมเช็คเงื่อนไขเวลาไว้แต่ไม่มีอะไรสั่งเรนเดอร์ใหม่ตอนหมดเวลา
 // ป้าย "เก็บเงินกลับมาได้" เลยค้างจนกว่าจะมีการกระทำอื่นบังเอิญมาเรนเดอร์ซ้ำ
 if (p.lastWalkEarn && p.lastWalkEarnAt && Date.now() - p.lastWalkEarnAt < 8000) {
  setTimeout(() => { if (ppCurrentScreen === 'pet') renderPetApp(); }, 8000 - (Date.now() - p.lastWalkEarnAt) + 50);
 }
 const bar = (lb, v, col) => `<div class="pp-pet-stat">
   <span class="lb">${lb}</span>
   <span class="bar"><i style="width:${Math.round(v)}%;background:${col}"></i></span>
   <span class="pct">${Math.round(v)}</span></div>`;

 body.innerHTML = `
 <div class="pp-pet-stage${ppPetIsNight() ? ' night' : ''}">
  <img class="pp-pet-sprite ${pose}" id="pp-pet-sprite" src="${ppPetSprite(p, pose)}" alt="${esc(p.name)}" onerror="this.classList.add(&#39;noimg&#39;)">
  ${p.poop.map(d => `<button class="pp-pet-poop" data-poop="${esc(d.id)}" style="left:${d.x}%;top:${d.y}%" title="เก็บอึ"></button>`).join('')}
  ${walking ? `<div class="pp-pet-away">ออกไปเดินเล่น · เหลือ ${Math.max(1, Math.round((p.walkUntil - Date.now()) / 60000))} นาที</div>` : ''}
  ${(p.lastWalkEarn && p.lastWalkEarnAt && Date.now() - p.lastWalkEarnAt < 8000) ? `<div class="pp-pet-earn">เก็บเงินกลับมาได้ ฿${p.lastWalkEarn}</div>` : ''}
 </div>
 <div class="pp-pet-head">
  <div class="pp-pet-name">${esc(p.name)} <span class="pp-pet-sex">${esc(p.sex)}</span>
   <span class="pp-pet-stage-tag">${p.stage === 'baby' ? 'เด็ก' : 'โตแล้ว'}</span></div>
  <div class="pp-pet-mood">${esc(ppPetMoodText(p))}</div>
  <div class="pp-pet-father">${p.fatherId ? `พ่อ: ${esc(p.fatherName || '')}` : 'ยังไม่มีพ่อ'} <button id="pp-pet-father-btn">${p.fatherId ? 'เปลี่ยน' : 'ตั้งพ่อ'}</button>
   ${p.fatherId ? `<label class="pp-pet-father-aware"><input type="checkbox" id="pp-pet-aware"${p.fatherAware !== false ? ' checked' : ''}> ให้พ่อรับรู้ว่าน้องหิว/อึ/ป่วย</label>` : ''}</div>
 </div>
 <div class="pp-pet-stats">
  ${bar('อิ่ม', p.full, 'linear-gradient(90deg,#ffb26b,#ff8f5e)')}
  ${bar('สะอาด', p.clean, 'linear-gradient(90deg,#64d2ff,#5ac8fa)')}
  ${bar('สนุก', p.fun, 'linear-gradient(90deg,#ff8fa8,#ff6482)')}
  ${bar('สุขภาพ', p.health, 'linear-gradient(90deg,#30d158,#8ce99a)')}
 </div>
 ${p.dead ? `<div class="pp-hint">น้องจากไปแล้ว · รับน้องใหม่ได้จากปุ่มด้านล่าง</div>
  <button class="pp-btn primary wide" id="pp-pet-adopt">รับน้องใหม่</button>`
 : `
  <div class="pp-pet-invwrap">
   <div class="pp-pet-sec">ของที่มี · แตะเพื่อใช้</div>
   <div class="pp-pet-inv">${(() => {
     const inv = ppPetInv(p);
     const keys = Object.keys(inv).filter(k => inv[k] > 0);
     if (!keys.length) return '<div class="pp-pet-invempty">ยังไม่มีของ · ไปซื้อที่ร้านค้าก่อนนะ</div>';
     return keys.map(k => {
      const [kind, id] = k.split(':');
      const it = ppShopFind(kind, id);
      if (!it) return '';
      return `<button class="pp-pet-invitem" data-useitem="${esc(k)}">
       <img src="${PET_ICONS2[it.icon]}" alt="">
       <span class="nm">${esc(it.name)}</span>
       <span class="ct">${inv[k]}</span></button>`;
     }).join('');
   })()}</div>
  </div>
  <div class="pp-pet-acts">
   <button class="pp-pet-act" id="pp-pet-shop"${walking ? ' disabled' : ''}><img src="${PET_ICONS.feed}" alt=""><span>ร้านค้า</span></button>
   <button class="pp-pet-act" id="pp-pet-walk"${walking || p.sick ? ' disabled' : ''}><img src="${PET_ICONS.walk}" alt=""><span>พาเดินเล่น</span></button>
   <button class="pp-pet-act" id="pp-pet-med"${p.sick ? '' : ' disabled'}><img src="${PET_ICONS.med}" alt=""><span>ให้ยา (${p.meds})</span></button>
   <button class="pp-pet-act" id="pp-pet-game"><img src="${PET_ICONS.sleep}" alt=""><span>เล่นเกม</span></button>
   <button class="pp-pet-act" id="pp-pet-log">${ICON.gridList}<span>ประวัติ</span></button>
   <button class="pp-pet-act" id="pp-pet-list">${ICON.users}<span>น้องทั้งหมด</span></button>
  </div>
  <div class="pp-pet-acts2">
   <button class="pp-pet-act2" id="pp-pet-share-chat">${ICON.messages}<span>แชร์ลงแชท</span></button>
   <button class="pp-pet-act2" id="pp-pet-share-feed">${ICON.feed}<span>แชร์ลงฟีด</span></button>
  </div>
  ${p.sick ? `<div class="pp-hint">น้องป่วยอยู่ พาไปเดินเล่นไม่ได้จนกว่าจะหาย</div>` : ''}`}
 <div class="pp-pet-coins">${ICON.money} เงินของน้อง ${fmtMoney(P.coins || 0)}</div>`;
}

function ppPetAdopt() {
 ppPrompt('ตั้งชื่อน้อง', '', v => {
  const name = v.trim(); if (!name) return;
  ppSheet('เพศของน้อง', ['เพศผู้', 'เพศเมีย', 'ไม่ระบุ'].map(sx => ({ label: sx, onClick: () => {
   const P = ppPets();
   const np = ppPetNew('cat-orange', name, sx);
   P.list.push(np); P.activeId = np.id;
   saveCfg(); renderPetApp();
   ppToast(`ยินดีต้อนรับน้อง${name}`);
  } })));
 }, { placeholder: 'เช่น ส้มโอ' });
}
/* ══ [2.45.0] จัดการน้องหลายตัว — เลือก เปลี่ยนชื่อ ปักหมุด ลบ ลบหลายตัว เรียกคืน ══
 * สิ่งที่ผูกกับตัวน้องและจะหายไปด้วยเมื่อลบ: ค่าพลัง บันทึก คลังของ และการผูกพ่อ
 * สิ่งที่ใช้ร่วมกันและไม่หาย: เงินของน้อง (P.coins) กับสถิติเกม */
let ppPetTrash = [];   // เก็บตัวที่เพิ่งลบไว้ในหน่วยความจำ เรียกคืนได้จนกว่าจะปิดหน้าเว็บ
function ppPetStatusText(p) {
 if (!p) return '';
 if (p.dead) return 'จากไปแล้ว';
 if (p.walkUntil && Date.now() < p.walkUntil) return 'กำลังเดินเล่น';
 try { return ppPetMoodText(p); } catch { return ''; }
}
/** เลือกตัวที่จะแสดงต่อหลังลบ: ปักหมุดที่ยังมีชีวิต > ยังมีชีวิต > ตัวไหนก็ได้ */
function ppPetPickNext() {
 const P = ppPets();
 if (P.list.some(x => x.id === P.activeId)) return;
 const next = P.list.find(x => x.pinned && !x.dead) || P.list.find(x => !x.dead) || P.list[0] || null;
 P.activeId = next ? next.id : null;
}
/** ลบจริง รับเป็นรายการรหัส ทำครั้งเดียวแล้วบันทึก */
function ppPetRemove(ids) {
 const P = ppPets();
 const set = new Set(ids);
 const gone = P.list.filter(x => set.has(x.id));
 if (!gone.length) return 0;
 P.list = P.list.filter(x => !set.has(x.id));
 ppPetTrash = gone.map(x => JSON.parse(JSON.stringify(x))).concat(ppPetTrash).slice(0, 30);
 ppPetPickNext();
 saveCfg();
 try { ppLog('pet', gone.length === 1 ? `ลบน้อง${gone[0].name}` : `ลบน้อง ${gone.length} ตัว`, gone.map(x => x.name)); } catch {}
 return gone.length;
}
function ppPetRestore() {
 if (!ppPetTrash.length) return;
 const P = ppPets();
 const have = new Set(P.list.map(x => x.id));
 const back = ppPetTrash.filter(x => !have.has(x.id));
 P.list = P.list.concat(back);
 if (!P.activeId && back[0]) P.activeId = back[0].id;
 ppPetTrash = [];
 saveCfg(); renderPetApp();
 ppToast(back.length === 1 ? `เรียกคืนน้อง${back[0].name}แล้ว` : `เรียกคืน ${back.length} ตัวแล้ว`);
}
/** คำเตือนเฉพาะตัว ให้ผู้ใช้รู้ว่ากำลังจะเสียอะไร */
function ppPetLossNote(list) {
 const notes = [];
 if (list.some(x => x.walkUntil && Date.now() < x.walkUntil)) notes.push('มีตัวที่กำลังเดินเล่นอยู่ เงินจากรอบนี้จะไม่ได้');
 if (list.some(x => x.fatherId)) notes.push('ตัวละครที่เป็นพ่อจะไม่รับรู้เรื่องน้องตัวนี้อีก');
 if (list.some(x => x.pinned)) notes.push('มีตัวที่ปักหมุดไว้');
 const itemN = list.reduce((a, x) => a + Object.values(x.inv || {}).reduce((b, n) => b + (+n || 0), 0), 0);
 if (itemN) notes.push(`ของในคลัง ${itemN} ชิ้นจะหายไปด้วย`);
 notes.push('เงินของน้องกับสถิติเกมยังอยู่ครบ');
 return notes.join(' · ');
}
function ppPetAskDelete(p) {
 ppConfirm(`ลบน้อง${p.name}`, `ค่าพลัง บันทึก และคลังของของน้องตัวนี้จะหายไป · ${ppPetLossNote([p])} · เรียกคืนได้จากเมนูน้องทั้งหมดจนกว่าจะปิดหน้าเว็บ`, () => {
  ppPetRemove([p.id]); renderPetApp();
  ppToast(`ลบน้อง${p.name}แล้ว · เรียกคืนได้ที่เมนูน้องทั้งหมด`);
 }, 'ลบ');
}
function ppPetRename(p) {
 ppPrompt('เปลี่ยนชื่อน้อง', p.name, v => {
  const nm = String(v || '').trim().slice(0, 24);
  if (!nm) return ppToast('ชื่อว่างไม่ได้');
  p.name = nm; saveCfg(); renderPetApp(); ppToast('เปลี่ยนชื่อแล้ว');
 }, { rows: 1 });
}
/** เมนูของน้องทีละตัว */
function ppPetItemSheet(p) {
 const P = ppPets();
 ppSheet(`${p.name} · ${ppPetStatusText(p)}`, [
  P.activeId !== p.id ? { label: 'ดูน้องตัวนี้', icon: ICON.eye, onClick: () => { P.activeId = p.id; saveCfg(); renderPetApp(); } } : null,
  { label: 'เปลี่ยนชื่อ', icon: ICON.compose, onClick: () => ppPetRename(p) },
  { label: p.pinned ? 'เลิกปักหมุด' : 'ปักหมุด', icon: ICON.star, onClick: () => { p.pinned = !p.pinned; saveCfg(); renderPetApp(); } },
  { label: 'ลบน้องตัวนี้', icon: ICON.trash, danger: true, onClick: () => ppPetAskDelete(p) },
 ].filter(Boolean));
}
/** ลบหลายตัวในครั้งเดียว ติ๊กเลือกได้ */
function ppPetBulkDelete() {
 const P = ppPets();
 if (!P.list.length) return;
 const picked = new Set();
 const ov = ppOverlay('bottom', `<div class="pp-sheet">
  <div class="pp-sheet-grab"></div>
  <div class="pp-sheet-head"><span class="pp-sheet-title">เลือกน้องที่จะลบ</span></div>
  <div class="pp-sheet-body">
   <div class="pp-petpick-tools">
    <button class="pp-btn" data-pk="dead">เลือกตัวที่จากไปแล้ว</button>
    <button class="pp-btn" data-pk="unpin">เลือกทุกตัวที่ไม่ปักหมุด</button>
    <button class="pp-btn" data-pk="none">ล้างที่เลือก</button>
   </div>
   <div class="pp-card pp-petpick-list">${P.list.map(x => `<label class="pp-petpick-row">
    <input type="checkbox" data-pid="${esc(x.id)}">
    <span class="nm">${x.pinned ? ICON.star : ''}${esc(x.name)}</span>
    <span class="st">${esc(ppPetStatusText(x))}</span>
   </label>`).join('')}</div>
  </div>
  <button class="pp-btn danger wide pp-petpick-go" disabled>ลบ 0 ตัว</button>
  <button class="pp-sheet-cancel">ยกเลิก</button>
 </div>`);
 const sheet = ov.querySelector('.pp-sheet');
 sheet?.addEventListener('click', ev => ev.stopPropagation());
 const go = ov.querySelector('.pp-petpick-go');
 if (!go) { ov.remove(); return; }
 const sync = () => {
  ov.querySelectorAll('[data-pid]').forEach(cb => { cb.checked = picked.has(cb.dataset.pid); });
  go.disabled = !picked.size;
  go.textContent = `ลบ ${picked.size} ตัว`;
 };
 ov.querySelectorAll('[data-pid]').forEach(cb => cb.addEventListener('change', () => {
  cb.checked ? picked.add(cb.dataset.pid) : picked.delete(cb.dataset.pid); sync();
 }));
 ov.querySelectorAll('[data-pk]').forEach(b => b.addEventListener('click', () => {
  const k = b.dataset.pk;
  if (k === 'none') picked.clear();
  else P.list.forEach(x => { if ((k === 'dead' && x.dead) || (k === 'unpin' && !x.pinned)) picked.add(x.id); });
  sync();
 }));
 ov.querySelector('.pp-sheet-cancel')?.addEventListener('click', () => ov.remove());
 go.addEventListener('click', () => {
  if (!picked.size) return;
  const list = P.list.filter(x => picked.has(x.id));
  const all = list.length === P.list.length;
  ov.remove();
  ppConfirm(`ลบน้อง ${list.length} ตัว`, `${all ? 'จะไม่เหลือน้องเลยสักตัว · ' : ''}${ppPetLossNote(list)} · เรียกคืนได้จากเมนูน้องทั้งหมดจนกว่าจะปิดหน้าเว็บ`, () => {
   const n = ppPetRemove(list.map(x => x.id)); renderPetApp();
   ppToast(`ลบ ${n} ตัวแล้ว · เรียกคืนได้ที่เมนูน้องทั้งหมด`);
  }, `ลบ ${list.length} ตัว`);
 });
 sync();
}
function ppPetListSheet() {
 const P = ppPets();
 if (!P.list.length && !ppPetTrash.length) return ppPetAdopt();
 const deadN = P.list.filter(x => x.dead).length;
 const items = P.list.map(p => ({
  label: `${p.id === P.activeId ? '● ' : ''}${p.pinned ? '[ปักหมุด] ' : ''}${p.name} · ${ppPetStatusText(p)}`,
  onClick: () => ppPetItemSheet(p),
 }));
 items.push({ label: 'รับน้องใหม่', icon: ICON.plus, onClick: () => ppPetAdopt() });
 if (ppPetTrash.length) items.push({ label: `เรียกคืนน้องที่ลบไป (${ppPetTrash.length} ตัว)`, icon: ICON.regen, onClick: () => ppPetRestore() });
 if (deadN) items.push({ label: `ลบตัวที่จากไปแล้วทั้งหมด (${deadN})`, icon: ICON.trash, danger: true, onClick: () => {
  const list = P.list.filter(x => x.dead);
  ppConfirm(`ลบตัวที่จากไปแล้ว ${list.length} ตัว`, ppPetLossNote(list), () => {
   ppPetRemove(list.map(x => x.id)); renderPetApp(); ppToast(`ลบ ${list.length} ตัวแล้ว`);
  }, 'ลบ');
 } });
 if (P.list.length > 1) items.push({ label: 'เลือกลบหลายตัว', icon: ICON.trash, danger: true, onClick: () => ppPetBulkDelete() });
 ppSheet(`น้องทั้งหมด · ${P.list.length} ตัว · แตะเพื่อจัดการ`, items);
}

function renderHelper() {
 const tabs = document.getElementById('pp-helper-tabs');
 const body = document.getElementById('pp-helper-body');
 if (!body) return;
 const cfg = getCfg();
 const tab = cfg.helperTab || 'howto';
 const unread = ppUnreadVersions().length;
 if (tabs) {
  tabs.innerHTML = [
   { k: 'howto', ic: ICON.eye, lb: 'วิธีใช้' },
   { k: 'tools', ic: ICON.gear, lb: 'เครื่องมือ' },
   { k: 'faq', ic: ICON.comment, lb: 'คำถาม' },
   { k: 'updates', ic: ICON.bell, lb: 'อัปเดต' },
  ].map(x => `<button data-helptab="${x.k}"${tab === x.k ? ' class="on"' : ''}>${x.ic}<span>${x.lb}</span>${x.k === 'updates' && unread ? '<span class="pp-tabdot"></span>' : ''}</button>`).join('');
 }
 const guideCard = arr => `<div class="pp-card">${arr.map(g => `<div class="pp-guide">
  <div class="pp-guidetitle">${g.icon}<span>${esc(g.title)}</span></div>
  <div class="pp-guidetext">${esc(g.text)}</div>
 </div>`).join('')}</div>`;

 if (tab === 'howto') {
  body.innerHTML = `<div class="pp-hint" style="margin:0 0 10px">คู่มือนี้อ่านได้เฉพาะในแอปนี้ ไม่ถูกส่งเข้า prompt ของตัวละครหรือเนื้อเรื่องใด ๆ</div>`
   + guideCard(PP_GUIDE_HOWTO);
  return;
 }
 if (tab === 'tools') { body.innerHTML = guideCard(PP_GUIDE_TOOLS); return; }
 if (tab === 'faq') { body.innerHTML = guideCard(PP_GUIDE_FAQ); return; }

 const seen = cfg.seenVersions || [];
 body.innerHTML = `
 ${unread ? `<div class="pp-vertip" style="margin-bottom:10px"><b>มีอัปเดตใหม่ ${unread} รุ่น</b> ที่ยังไม่ได้อ่าน แตะหัวข้อเพื่อเปิดดูรายละเอียด</div>` : ''}
 <div class="pp-card">${PP_CHANGELOG.map((c, i) => `<div class="pp-verrow${i === 0 ? ' open' : ''}" data-verrow="${esc(c.v)}">
 <div class="pp-verhead" data-vertoggle="${esc(c.v)}">
 <span class="pp-verbadge${c.v === PP_VERSION ? ' now' : ''}">${esc(c.v)}</span>
 <span class="pp-vertitle">${esc(c.title)}</span>
 ${!seen.includes(c.v) ? '<span class="pp-setdot"></span>' : ''}
 ${ICON.chevron}
 </div>
 <div class="pp-verbody">
 ${c.lines.map(l => `<div class="pp-verline">${esc(l)}</div>`).join('')}
 ${c.tip ? `<div class="pp-vertip"><b>เคล็ดลับ</b> ${esc(c.tip)}</div>` : ''}
 </div>
 </div>`).join('')}</div>
 ${unread ? `<div class="pp-btn-row"><button class="pp-btn wide" id="pp-ver-allread">${ICON.check} ทำเครื่องหมายว่าอ่านหมดแล้ว</button></div>` : ''}
 <div class="pp-hint" style="text-align:center;padding:14px 0">Pocket Phone ${PP_VERSION}</div>`;
 // เปิดรุ่นแรกอยู่แล้ว จึงถือว่าอ่าน
 ppMarkVersionSeen(PP_CHANGELOG[0].v);
}
function renderPeriod() {
 const body = document.getElementById('pp-period-body');
 if (!body) return;
 document.querySelectorAll('#pp-period-seg button').forEach(b => b.classList.toggle('on', b.dataset.ptab === ppPeriodTab));
 if (ppPeriodTab === 'today') renderPeriodToday(body);
 else if (ppPeriodTab === 'calendar') renderPeriodCalendar(body);
 else if (ppPeriodTab === 'history') renderPeriodHistory(body);
 else renderPeriodPrivacy(body);
}
function renderPeriodToday(body) {
 const info = periodTodayInfo();
 const avg = info.avg;
 const today = ymd(new Date());
 const log = (getCfg().periodLogs || {})[today] || { flow: '', symptoms: [], mood: '', note: '' };
 const cycleLen = avg.cycleLen || 28;
 let dayNum, pct;
 if (info.onPeriod) { dayNum = info.dayNum; pct = Math.min(1, dayNum / (avg.duration || 5)); }
 else if (info.sinceStart != null) { dayNum = info.sinceStart + 1; pct = Math.min(1, dayNum / cycleLen); }
 else { dayNum = 0; pct = 0; }
 const R = 88, C = 2 * Math.PI * R;
 const marked = isPeriodDay(today);

 /* ★ 2.29.0 รื้อใหม่ทั้งแอพ
    เดิมเป็นรายการเรียงลงมาเฉย ๆ ตอนนี้เป็นการ์ดฮีโร่ ไทม์ไลน์รอบเดือน แล้วค่อยเป็นบันทึก */
 // ไทม์ไลน์เจ็ดวันรอบวันนี้ ให้เห็นว่าอยู่ตรงไหนของรอบ
 const days = [];
 for (let k = -3; k <= 3; k++) {
  const d = new Date(); d.setDate(d.getDate() + k);
  const key = ymd(d);
  days.push({
   key, k,
   lb: ['อา', 'จ', 'อ', 'พ', 'พฤ', 'ศ', 'ส'][d.getDay()],
   num: d.getDate(),
   on: isPeriodDay(key),
   today: k === 0,
  });
 }
 const pickRow = (title, items, attr, isOn) => `
  <div class="pp-pblock">
   <div class="pp-pblock-lb">${title}</div>
   <div class="pp-tags-pick">${items.map(x =>
    `<button class="pp-tag-btn${isOn(x) ? ' on' : ''}" data-${attr}="${esc(x)}">${esc(x)}</button>`).join('')}</div>
  </div>`;

 body.innerHTML = `
 <div class="pp-phero">
  <div class="pp-ring">
   <svg viewBox="0 0 204 204">
    <defs><linearGradient id="pp-ring-grad" x1="0" y1="0" x2="1" y2="1">
     <stop offset="0%" stop-color="#ff8fa8"/><stop offset="100%" stop-color="#ff375f"/>
    </linearGradient></defs>
    <circle class="pp-ring-bg" cx="102" cy="102" r="${R}"/>
    <circle class="pp-ring-fg" cx="102" cy="102" r="${R}" stroke-dasharray="${C}" stroke-dashoffset="${C * (1 - pct)}"/>
   </svg>
   <div class="pp-ring-mid">
    <div class="pp-ring-day">${dayNum || '—'}</div>
    <div class="pp-ring-lb">${info.onPeriod ? 'วันที่ของรอบ' : dayNum ? 'วันของวงจร' : 'ยังไม่มีข้อมูล'}</div>
   </div>
  </div>
  <div class="pp-ring-phase">${esc(phaseLabel(info.phase))}</div>
  <div class="pp-pweek">
   ${days.map(d => `<span class="pp-pday${d.on ? ' on' : ''}${d.today ? ' now' : ''}">
    <span class="pp-pday-lb">${d.lb}</span>
    <span class="pp-pday-num">${d.num}</span>
   </span>`).join('')}
  </div>
  <button class="pp-pmark${marked ? ' off' : ''}" id="pp-p-marktoday">
   ${marked ? ICON.close + ' ยกเลิกเครื่องหมายวันนี้' : ICON.drop + ' ประจำเดือนมาวันนี้'}</button>
 </div>

 <div class="pp-pstats">
  <div class="pp-pstat"><b>${info.onPeriod ? 'วันนี้' : (info.upcomingIn != null && info.upcomingIn >= 0 ? info.upcomingIn : '—')}</b>
   <span>${info.onPeriod ? 'มีประจำเดือน' : 'วันถึงรอบถัดไป'}</span></div>
  <div class="pp-pstat"><b>${cycleLen}</b><span>ความยาวรอบเฉลี่ย</span></div>
  <div class="pp-pstat"><b>${avg.duration || 5}</b><span>วันเฉลี่ยที่มา</span></div>
 </div>

 <div class="pp-sec-label">บันทึกของวันนี้</div>
 <div class="pp-card pp-pcard">
  ${pickRow('ปริมาณ', PERIOD_FLOWS, 'pflow', x => log.flow === x)}
  ${pickRow('อาการ', PERIOD_SYMPTOMS, 'psym', x => (log.symptoms || []).includes(x))}
  ${pickRow('อารมณ์', PERIOD_MOODS, 'pmood', x => log.mood === x)}
  <div class="pp-pblock">
   <div class="pp-pblock-lb">โน้ต</div>
   <textarea class="pp-input-line" id="pp-p-note" rows="3" placeholder="อยากบันทึกอะไรเพิ่ม">${esc(log.note || '')}</textarea>
   <button class="pp-btn wide" id="pp-p-savenote" style="margin-top:9px">บันทึกโน้ต</button>
  </div>
 </div>`;
}

function renderPeriodCalendar(body) {
 const y = ppCalMonth.getFullYear(), mo = ppCalMonth.getMonth();
 const first = new Date(y, mo, 1).getDay();
 const days = new Date(y, mo + 1, 0).getDate();
 const todayStr = ymd(new Date());
 const pred = periodPredicted();
 const ovu = periodOvulationDays();
 let cells = '';
 for (let i = 0; i < first; i++) cells += `<span class="pp-cal-cell empty"></span>`;
 for (let d = 1; d <= days; d++) {
 const sd = `${y}-${String(mo + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
 const cls = [
 isPeriodDay(sd) ? 'on' : '',
 sd === todayStr ? 'today' : '',
 !isPeriodDay(sd) && pred.includes(sd) ? 'pred' : '',
 !isPeriodDay(sd) && ovu.includes(sd) ? 'ovu' : '',
 ].filter(Boolean).join(' ');
 cells += `<button class="pp-cal-cell ${cls}" data-calday="${sd}">${d}${hasPeriodLog(sd) ? '<span class="pp-cal-dot"></span>' : ''}</button>`;
 }
 body.innerHTML = `
 <div class="pp-cal-head">
 <button class="pp-cal-nav" id="pp-cal-prev">${ICON.back}</button>
 <b>${TH_MONTHS_FULL[mo]} ${y}</b>
 <button class="pp-cal-nav" id="pp-cal-next">${ICON.fwd}</button>
 </div>
 <div class="pp-cal-dow"><span>อา</span><span>จ</span><span>อ</span><span>พ</span><span>พฤ</span><span>ศ</span><span>ส</span></div>
 <div class="pp-cal-grid" id="pp-cal-grid">${cells}</div>
 <div class="pp-cal-legend">
 <span><i style="background:#ff375f"></i>มีประจำเดือน</span>
 <span><i style="box-shadow:inset 0 0 0 1.5px rgba(255,100,130,.7)"></i>คาดการณ์</span>
 <span><i style="box-shadow:inset 0 0 0 1.5px rgba(50,173,230,.7)"></i>ไข่ตก</span>
 <span><i style="background:var(--pp-txt3);width:5px;height:5px"></i>มีบันทึกอาการ</span>
 </div>
 <div class="pp-hint">แตะวันเพื่อทำเครื่องหมาย · แตะซ้ำเพื่อบันทึกอาการของวันนั้น</div>`;
 bindCalSwipe(body);
}
function bindCalSwipe(root) {
 const grid = root.querySelector('#pp-cal-grid');
 if (!grid) return;
 let x0 = 0, active = false;
 grid.addEventListener('touchstart', e => { x0 = e.touches[0].clientX; active = false; }, { passive: true });
 grid.addEventListener('touchmove', e => { if (Math.abs(e.touches[0].clientX - x0) > 40) active = true; }, { passive: true });
 grid.addEventListener('touchend', e => {
 if (!active) return;
 const dx = e.changedTouches[0].clientX - x0;
 ppCalNav(dx > 0 ? -1 : 1);
 }, { passive: true });
}
function ppCalNav(delta) {
 ppCalMonth = new Date(ppCalMonth.getFullYear(), ppCalMonth.getMonth() + delta, 1);
 renderPeriod();
}
function renderPeriodHistory(body) {
 const cycles = periodCycles().slice().reverse();
 const avg = periodAvg();
 if (!cycles.length) { body.innerHTML = `<div class="pp-empty">${ICON.calendar}<br>ยังไม่มีประวัติรอบ<span>ทำเครื่องหมายวันในปฏิทินก่อน</span></div>`; return; }
 const notes = [];
 if (cycles.length >= 2) {
 const gap = Math.round((new Date(cycles[0].start) - new Date(cycles[1].start)) / 86400000);
 const diff = gap - avg.cycleLen;
 if (Math.abs(diff) <= 2) notes.push('รอบของคุณค่อนข้างสม่ำเสมอ');
 else if (diff > 0) notes.push(`รอบล่าสุดยาวกว่าค่าเฉลี่ย ${diff} วัน`);
 else notes.push(`รอบล่าสุดสั้นกว่าค่าเฉลี่ย ${Math.abs(diff)} วัน`);
 }
 if (cycles[0] && avg.duration && cycles[0].len > avg.duration + 2) notes.push('รอบล่าสุดมานานกว่าปกติ');
 body.innerHTML = `
 <div class="pp-pstats">
 <div class="pp-pstat"><b>${cycles.length}</b><span>รอบที่บันทึก</span></div>
 <div class="pp-pstat"><b>${avg.cycleLen}</b><span>ความยาวรอบเฉลี่ย</span></div>
 <div class="pp-pstat"><b>${avg.duration}</b><span>วันเฉลี่ยที่มา</span></div>
 </div>
 ${notes.length ? `<div class="pp-card"><div class="pp-cell pp-cell-col">
 <div class="pp-cell-lb" style="margin-bottom:6px">${ICON.chart} วิเคราะห์</div>
 ${notes.map(n => `<div class="pp-hint" style="margin:0 0 4px">${esc(n)}</div>`).join('')}
 </div></div>` : ''}
 <div class="pp-sec-label">รอบย้อนหลัง</div>
 <div class="pp-card">${cycles.map((cy, i) => {
 const prev = cycles[i + 1];
 const gap = prev ? Math.round((new Date(cy.start) - new Date(prev.start)) / 86400000) : null;
 return `<div class="pp-cyclerow">
 <span class="pp-cycle-ic">${ICON.drop}</span>
 <div class="pp-wrow-meta">
 <div class="pp-wrow-name">${esc(ymdLabel(cy.start))}${cy.len > 1 ? ` - ${esc(ymdLabel(cy.end))}` : ''}</div>
 <div class="pp-wrow-sub">มา ${cy.len} วัน${gap ? ` · ห่างรอบก่อน ${gap} วัน` : ''}</div>
 </div>
 </div>`;
 }).join('')}</div>`;
}
