function ppTokLabel(n) {
 const cache = getCfg().bridgeTokenCache;
 if (!cache || !cache.ok) return 'ยังไม่วัด';
 if (n == null) return '—';
 const v = Math.round(n);
 return v > 0 ? `${v} tok` : '0 tok';
}
