function ppSetPageValue(key) {
 const cfg = getCfg();
 const cache = cfg.bridgeTokenCache;
 if (key === 'bridge') return cache && cache.ok ? `${ppBridgeActiveTotal(cache)} tok` : 'ยังไม่วัด';
 if (key === 'memory') return `${ppLogCount() + ppBotLogCount()} คิว`;
 if (key === 'drama') return cfg.dramaEnabled ? 'เปิด' : 'ปิด';
 if (key === 'look') return cfg.theme === 'dark' ? 'มืด' : 'สว่าง';
 if (key === 'me') return cfg.userPersonaMode === 'shared' ? 'ร่วมทุกแชท' : 'แยกแชท';
 if (key === 'phone') return cfg.botCallKeyword ? 'บอทโทรได้' : 'ปิดการโทร';
 if (key === 'sound') return cfg.audioEnabled !== false ? 'เปิด' : 'ปิด';
 if (key === 'scope') return cfg.strictNpcScope ? 'โฟกัสเข้ม' : 'ปกติ';
 if (key === 'tools') return `${allStickers().length} สติกเกอร์`;
 if (key === 'glass') return ppGx().lg ? 'เปิด' : 'ปิด';
 return '';
}
/** ★ 2.27.0 แอพตั้งค่า รื้อใหม่ทั้งแอพ
 * การ์ดโปรไฟล์ด้านบน ช่องค้นหา และจัดหมวดเป็นกลุ่มแบบ iOS */
let ppSetFilter = '';
const PP_SET_GROUPS = [
 { name: 'การคุย', keys: ['chat', 'style', 'memory', 'bridge'] },
 { name: 'หน้าตาและเสียง', keys: ['deco', 'glass', 'look', 'sound', 'phone'] },
 { name: 'ตัวคุณและขอบเขต', keys: ['me', 'scope', 'drama'] },
 { name: 'เครื่องมือ', keys: ['tools'] },
];
function renderPhoneSettings() {
 const body = document.getElementById('pp-settings-body');
 if (!body) return;
 const cfg = getCfg();
 const unread = ppUnreadVersions().length;
 const q = ppSetFilter.trim().toLowerCase();
 const hit = p => !q || (p.name + ' ' + (p.sub || '')).toLowerCase().includes(q);

 const rowHTML = p => `<div class="pp-setrow" data-setpage="${esc(p.key)}">
  <span class="pp-seticon" style="background:linear-gradient(158deg,${p.color},${p.color}cc);color:#fff">${p.icon}</span>
  <span class="pp-setmeta">
   <span class="pp-setname">${esc(p.name)}</span>
   <span class="pp-setsub">${esc(p.sub)}</span>
  </span>
  <span class="pp-setval"><span>${esc(ppSetPageValue(p.key))}</span>${ICON.chevron}</span>
 </div>`;

 const me = getUserDisplayName();
 const avatar = cfg.userAvatar || '';
 const cnt = (cfg.contacts || []).length;

 const groups = PP_SET_GROUPS.map(g => {
  const rows = g.keys.map(k => PP_SET_PAGES.find(p => p.key === k)).filter(p => p && hit(p));
  if (!rows.length) return '';
  return `<div class="pp-sec-label">${esc(g.name)}</div>
   <div class="pp-card">${rows.map(rowHTML).join('')}</div>`;
 }).join('');
 // หมวดที่ยังไม่ได้จัดกลุ่ม จะได้ไม่มีหมวดไหนหายไปเงียบ ๆ
 const grouped = PP_SET_GROUPS.flatMap(g => g.keys);
 const rest = PP_SET_PAGES.filter(p => !grouped.includes(p.key) && hit(p));

 body.innerHTML = `
 <div class="pp-setme">
  <span class="pp-setme-av">${avatar ? `<img src="${esc(avatar)}" alt="">` : esc((me || '?')[0])}</span>
  <span class="pp-setme-meta">
   <span class="pp-setme-name">${esc(me)}</span>
   <span class="pp-setme-sub">${cnt} คนคุย · Pocket Phone ${PP_VERSION}</span>
  </span>
  <span class="pp-setme-go" data-setpage="me">${ICON.chevron}</span>
 </div>

 <div class="pp-setsearch">
  <span class="ic">${ICON.search}</span>
  <input id="pp-set-search" placeholder="ค้นหาการตั้งค่า" value="${esc(ppSetFilter)}">
 </div>

 ${groups}
 ${rest.length ? `<div class="pp-sec-label">อื่น ๆ</div><div class="pp-card">${rest.map(rowHTML).join('')}</div>` : ''}

 ${!q ? `<div class="pp-sec-label">ช่วยเหลือ</div>
 <div class="pp-card">
  <div class="pp-setrow" data-nav="helper">
   <span class="pp-seticon" style="background:linear-gradient(158deg,#34c759,#34c759cc);color:#fff">${ICON.eye}</span>
   <span class="pp-setmeta">
    <span class="pp-setname">ผู้ช่วยและบันทึกอัปเดต</span>
    <span class="pp-setsub">วิธีใช้ เครื่องมือ คำถามที่พบบ่อย</span>
   </span>
   <span class="pp-setval">${unread ? `<span class="pp-setdot"></span>` : ''}${ICON.chevron}</span>
  </div>
 </div>` : ''}

 ${q && !groups && !rest.length ? `<div class="pp-empty">${ICON.search}<br>ไม่เจอการตั้งค่าที่ค้นหา<span>ลองคำอื่นดู</span></div>` : ''}
 <div class="pp-hint" style="text-align:center;padding:14px 0 6px">Pocket Phone ${PP_VERSION}</div>`;

 const inp = document.getElementById('pp-set-search');
 if (inp) {
  inp.oninput = () => { ppSetFilter = inp.value; renderPhoneSettings();
   const el = document.getElementById('pp-set-search');
   if (el) { el.focus(); try { el.setSelectionRange(el.value.length, el.value.length); } catch {} } };
 }
 if (!cfg.bridgeTokenCache) {
  ppMeasureBridgeTokens(false).then(() => { if (ppCurrentScreen === 'settings') renderPhoneSettings(); });
 }
}
