   // ★ 1.9.0
   if (author.id === currentCharacterId()) ppLogBot('feed', `รีโพสต์ของ ${postAuthorLabel(root)}${rpM[2] ? ` พร้อมเขียนว่า "${stripEmoji((rpM[2] || '').trim())}"` : ''}`);
