 if (t.closest('#pp-pet-father-btn')) { const p = ppPetActive(); if (p && !p.dead) ppPetSetFather(p); return; }
 if (t.closest('#pp-pet-med')) {
  const p = ppPetActive(); if (!p || !p.sick) return;
  if (p.meds <= 0) return ppToast('ยาหมดแล้ว เดือนหน้าถึงจะได้ใหม่');
  p.meds--; p.health = Math.min(100, p.health + 45); p.sick = p.health < 35;
  saveCfg(); renderPetApp(); ppToast('ให้ยาน้องแล้ว'); return;
 }
 if (t.closest('#pp-pet-walk')) {
  const p = ppPetActive(); if (!p || p.dead) return;
  if (p.sick) return ppToast('น้องป่วยอยู่ พาไปเดินเล่นไม่ได้');
  return ppSheet('พาไปเดินเล่นนานแค่ไหน', [1, 2, 3, 5, 8].map(hr => ({
   label: `${hr} ชั่วโมง · ได้เงินราว ฿${Math.round(10 * hr * 0.7)}-${Math.round(10 * hr * 1.6)}`,
   onClick: () => {
    p.walkHours = hr; p.walkUntil = Date.now() + hr * 3600000; p.lastWalkEarn = 0; p.lastWalkEarnAt = 0;
    saveCfg(); renderPetApp(); ppToast(`น้องออกไปเดินเล่น ${hr} ชั่วโมง`);
   },
  })));
 }
 if (t.closest('#pp-pet-sprite')) {   // ลูบหัว
  const p = ppPetActive(); if (!p || p.dead) return;
  const el = t.closest('#pp-pet-sprite');
  el.classList.remove('pat'); void el.offsetWidth; el.classList.add('pat');
  p.fun = Math.min(100, p.fun + 3); saveCfg(); return;
 }
 // นาฬิกา
 if (t.closest('[data-clocktab]')) { ppClockCfg().tab = t.closest('[data-clocktab]').dataset.clocktab; saveCfg(); return renderClockApp(); }
 if (t.closest('[data-tzadd]')) { const c = ppClockCfg(); c.cities.push(t.closest('[data-tzadd]').dataset.tzadd); saveCfg(); return renderClockApp(); }
 if (t.closest('[data-tzdel]')) { const c = ppClockCfg(); const nm = t.closest('[data-tzdel]').dataset.tzdel; c.cities = c.cities.filter(x => x !== nm); saveCfg(); return renderClockApp(); }
 if (t.closest('[data-alarmdel]')) { const c = ppClockCfg(); const id = t.closest('[data-alarmdel]').dataset.alarmdel; c.alarms = c.alarms.filter(x => x.id !== id); saveCfg(); return renderClockApp(); }
 if (t.closest('#pp-alarm-add-btn')) {
  return ppPrompt('เพิ่มปลุก', '07:00', v => {
   const time = /^\d{1,2}:\d{2}$/.test(v.trim()) ? v.trim() : null;
   if (!time) { ppToast('ใส่เวลาแบบ 07:00'); return; }
   ppClockCfg().alarms.push({ id: newId(), time, label: 'ปลุก', days: [], on: true });
   saveCfg(); renderClockApp(); ppToast('เพิ่มปลุกแล้ว');
  }, { placeholder: 'เช่น 07:00' });
 }
 if (t.closest('#pp-sw-startstop')) {
  if (ppSwState.running) { ppSwState.elapsed += Date.now() - ppSwState.startTs; ppSwState.running = false; }
  else { ppSwState.startTs = Date.now(); ppSwState.running = true; }
  return renderClockApp();
 }
 if (t.closest('#pp-sw-lap')) {
  if (ppSwState.running) ppSwState.laps.push(ppSwState.elapsed + (Date.now() - ppSwState.startTs));
  else { ppSwState.elapsed = 0; ppSwState.laps = []; }
  return renderClockApp();
 }
 if (t.closest('#pp-cd-startstop')) {
  if (ppCdState.running) { ppCdState.running = false; islandCollapse(); }
  else {
   const mins = Math.max(0, Math.min(180, parseInt(document.getElementById('pp-cd-mins')?.value || '5', 10) || 0));
   const secs = Math.max(0, Math.min(59, parseInt(document.getElementById('pp-cd-secs')?.value || '0', 10) || 0));
   ppCdState.mins = mins; ppCdState.secs = secs;
   ppCdState.totalMs = mins * 60000 + secs * 1000;
   if (ppCdState.totalMs <= 0) { ppToast('ตั้งเวลามากกว่าศูนย์'); return; }
   ppCdState.endTs = Date.now() + ppCdState.totalMs;
   ppCdState.running = true;
  }
  return renderClockApp();
 }
 // เครื่องคิดเลข
 if (t.closest('[data-calc]')) { const btn = t.closest('[data-calc]'); ppCalcOp(btn.dataset.calc, btn); return; }
 // โน้ต
 if (t.closest('#pp-notes-add-btn')) return ppNoteOpen(null);
