 // double-tap like บนรูปโพสต์
 frame.addEventListener('click', e => {
 const img = e.target.closest('[data-dbl]');
 if (!img) return;
 const pid = img.dataset.dbl;
 const now = Date.now();
 if (img._lastTap && now - img._lastTap < 330) {
 const p = findPost(pid);
 if (p && !(p.likes || []).includes('user')) { toggleFeedLike(pid); flyHeart(pid); }
 else flyHeart(pid);
 }
 img._lastTap = now;
 }, true);

 // ── input events ──
 const chatInput = document.getElementById('pp-input');
 if (chatInput) {
 chatInput.addEventListener('input', function () {
 this.style.height = 'auto';
 this.style.height = Math.min(120, this.scrollHeight) + 'px';
 const tid = curTid();
 if (tid) saveDraft(tid, this.value);
 });
 chatInput.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); ppSendUserMessage(); } });
 }
 const callInput = document.getElementById('pp-call-input');
 if (callInput) {
 // ★ 1.8.4 ช่องพิมพ์ขยายได้ไม่เกินสามบรรทัด และคืนตำแหน่งจอทุกครั้งที่เลิกโฟกัส
 const LINE = 21, PAD = 20, MAXL = 3;
 const fitCall = el => {
  const txt = String(el.value || '');
  if (!txt) { el.style.height = ''; el.rows = 1; return; }
  const hard = txt.split('\n').length;
  const wrap = Math.ceil(txt.length / 34) || 1;
  const rows = Math.max(1, Math.min(MAXL, Math.max(hard, wrap)));
  el.rows = rows;
  el.style.height = (rows * LINE + PAD) + 'px';
 };
 callInput.addEventListener('input', function () { fitCall(this); });
 callInput.addEventListener('blur', function () { fitCall(this); });
 callInput.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); ppCallSend(); } });
 }
 // ★ 2.4.0 ลบตัวคืนตำแหน่งจอทั้งชุดแล้ว
 // สาเหตุจริงของบั๊ก UI ค้างลอยในคนที่ไม่ได้เปิดมือถือ:
 //   ตัวเดิมผูก visualViewport ไว้ที่ window แล้วเรียก ppSnapFrameBack ทุกครั้งที่
 //   แป้นพิมพ์ขยับ โดยไม่เช็คว่ามือถือเปิดอยู่ไหม
 //   ในนั้นสั่ง document.documentElement.scrollTop = 0 ซึ่งเลื่อนหน้าเว็บทั้งหน้า
 //   และเติม class ที่สั่ง transform ให้ #pp-frame ทำให้ element นั้นกลายเป็น
 //   containing block ใหม่ของ position:fixed ทุกตัว → UI ของ ST ที่ลอยอยู่กระตุก
 // ตัวแทนที่ปลอดภัย: จำกัดทุกอย่างไว้ใน #pp-scr-call ด้วย CSS เท่านั้น
 const cmtInput = document.getElementById('pp-comment-input');
 if (cmtInput) {
 cmtInput.addEventListener('input', function () { this.style.height = 'auto'; this.style.height = Math.min(100, this.scrollHeight) + 'px'; });
 cmtInput.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); ppSendComment(); } });
 }
